// Content for My Choices, My Future (node g29, ages 15-18, Chapter 5 OPENER): NEW v2 build to GDD 29
// (mechanic-embodying), the contraception / family-planning / services node (Thread F · Sexual &
// Reproductive Health). "Your choices, your information, free of pressure in any direction." 84 researched,
// India-grounded, COMPREHENSIVE-BUT-NEVER-EXPLICIT scenarios across the full-picture → if-when-whether →
// decide-it → access-and-rights → talk-it-through → my-future-no-pressure arc, each encoded as one of the
// shared v2 play actions (branch / strike-rewrite / reflect / sort / role-play / spot / match): no binary
// "tap the right card". Lead mechanics: branch (decide it ×18), strike-rewrite (bust the myth ×16), sort
// (real vs myth ×13). Teaches: methods/effectiveness/access (the full picture), if-when-whether it's your
// call, values-based decisions, real access & rights, talking to a partner/doctor, and a future on your
// terms. AUTONOMY-FIRST, mature, matter-of-fact: NO PRESSURE IN ANY DIRECTION, delaying / not having sex is
// fully valid, respected, and the only 100%-certain option; being active isn't irresponsible: what matters
// is informed, consensual, protected. India: RKSK / Adolescent-Friendly Health Clinics (Ujala), CONFIDENTIAL
// services. Age of consent 18; POCSO protects under-18s and coercion/exploitation is a child-protection
// matter: routes to a doctor / trusted adult / Childline 1098. Builds on g22 (Plan It); links g30/g31.
// Rendered by the shared engine (components/games/v2-engine.tsx). gameId "my-choices" (the engine-host
// registry id; the GDD/library aspirational id is "my-choices-future"). DO NOT RENAME.

import type { Scenario, V2GameConfig } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  // The full picture: methods, effectiveness, access
  {"id":"mc-001","cat":"the-full-picture","type":"sort","persona":"any","source":"effectiveness tiers (WHO)","hook":"Sort by real-life effectiveness: very high, or depends on perfect use?","items":[{"id":"a","text":"IUD / implant (LARC)"},{"id":"b","text":"The daily pill"},{"id":"c","text":"Male condom"},{"id":"d","text":"Not having sex (delaying)"},{"id":"e","text":"Hormonal IUD"},{"id":"f","text":"Withdrawal ('pulling out')"}],"bins":[{"id":"top","label":"Top-tier / certain","valence":"pos"},{"id":"depends","label":"Depends on consistent use","valence":"uhoh"}],"key":{"a":"top","b":"depends","c":"depends","d":"top","e":"top","f":"depends"},"relearn":"LARC and delaying are most certain; the pill, condoms and withdrawal depend on consistent, correct use."},
  {"id":"mc-002","cat":"the-full-picture","type":"sort","persona":"any","source":"dual protection (CDC)","hook":"Sort: protects against STIs too, or only against pregnancy?","items":[{"id":"a","text":"Condom"},{"id":"b","text":"The pill"},{"id":"c","text":"IUD / implant"},{"id":"d","text":"Injectable"},{"id":"e","text":"Hormonal IUD"},{"id":"f","text":"Copper IUD"}],"bins":[{"id":"both","label":"Pregnancy + STIs","valence":"pos"},{"id":"preg","label":"Pregnancy only","valence":"uhoh"}],"key":{"a":"both","b":"preg","c":"preg","d":"preg","e":"preg","f":"preg"},"relearn":"Only condoms protect against STIs as well as pregnancy; that's 'dual protection'."},
  {"id":"mc-003","cat":"the-full-picture","type":"sort","persona":"any","source":"methods vs myths","hook":"Sort: a real contraceptive method, or a myth?","items":[{"id":"a","text":"Implant"},{"id":"b","text":"Pulling out fully prevents pregnancy"},{"id":"c","text":"Condom"},{"id":"d","text":"Washing after sex prevents pregnancy"},{"id":"e","text":"Copper IUD"},{"id":"f","text":"A 'safe day' always works"}],"bins":[{"id":"real","label":"Real method","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"real","b":"myth","c":"real","d":"myth","e":"real","f":"myth"},"relearn":"Implants, IUDs and condoms are real methods; 'pulling out', 'washing after' and 'safe day' are unreliable myths."},
  {"id":"mc-004","cat":"the-full-picture","type":"match","persona":"Sneha","source":"method features","hook":"Match the method to its key feature.","pairs":[{"left":"IUD / implant","right":"Set-and-forget, longest-lasting"},{"left":"Condom","right":"Also blocks STIs"},{"left":"The pill","right":"Taken daily"},{"left":"Emergency pill","right":"Backup within 5 days"},{"left":"Delaying sex","right":"The 100%-certain choice"}],"relearn":"Each method has a feature: LARC lasts, condoms protect from STIs, the pill is daily, EC is backup, delaying is certain."},
  {"id":"mc-005","cat":"the-full-picture","type":"match","persona":"any","source":"effectiveness (WHO)","hook":"Match the method to its real-life effectiveness.","pairs":[{"left":"IUD / implant","right":"Over 99 in 100"},{"left":"Pill (typical use)","right":"About 91 in 100"},{"left":"Condom (typical use)","right":"About 87 in 100"},{"left":"Condom (used right every time)","right":"About 98 in 100"},{"left":"Not having sex","right":"Certain, 100 in 100"}],"relearn":"LARC is over 99%; the pill and condoms are lower in typical use, but still effective when used well."},
  {"id":"mc-006","cat":"the-full-picture","type":"match","persona":"any","source":"method matching","hook":"Match the situation to the method worth knowing.","pairs":[{"left":"Want STI protection too","right":"Condom (with or without another method)"},{"left":"Want nothing to remember daily","right":"IUD / implant"},{"left":"Unprotected sex already happened","right":"Emergency contraception (within 5 days)"},{"left":"Keep forgetting a daily pill","right":"Switch to a LARC method"},{"left":"Want the most certain option","right":"Choosing not to have sex"}],"relearn":"Match the method to the need: dual protection, set-and-forget, backup, or certainty."},
  {"id":"mc-007","cat":"the-full-picture","type":"strike-rewrite","hook":"\"The pill protects you against STIs.\"","myth":{"un":"The pill protects you against STIs.","re":"The pill prevents pregnancy only; condoms are what protect against STIs.","why":"Different methods do different jobs."},"relearn":"The pill stops pregnancy, not STIs; only condoms do both.","persona":"any","source":"dual protection"},
  {"id":"mc-008","cat":"the-full-picture","type":"strike-rewrite","hook":"\"Using contraception now makes you infertile later.\"","myth":{"un":"Contraception now makes you infertile later.","re":"These methods are reversible; fertility returns after stopping.","why":"They prevent pregnancy while used, not permanently."},"relearn":"Contraception is reversible; it doesn't cause future infertility.","persona":"Sneha","source":"reversibility (WHO)"},
  {"id":"mc-009","cat":"the-full-picture","type":"strike-rewrite","hook":"\"Emergency contraception is the same as an abortion.\"","myth":{"un":"Emergency contraception is the same as an abortion.","re":"It mainly delays ovulation to prevent pregnancy; it won't end an existing pregnancy.","why":"It's prevention after unprotected sex, not termination."},"relearn":"Emergency contraception prevents pregnancy; it is not an abortion.","persona":"Counsellor","source":"emergency contraception (WHO)"},
  {"id":"mc-010","cat":"the-full-picture","type":"strike-rewrite","hook":"\"Condoms never really work, so why bother.\"","myth":{"un":"Condoms don't really work.","re":"Used correctly every time they're about 98% effective, and they're the only STI protection.","why":"Most 'failure' is inconsistent or incorrect use."},"relearn":"Used right every time, condoms work well and uniquely guard against STIs.","persona":"Vijay","source":"condom effectiveness"},
  {"id":"mc-011","cat":"the-full-picture","type":"match","persona":"any","source":"typical vs perfect use","hook":"Match the term to what it means.","pairs":[{"left":"Typical use","right":"Real life, including slips"},{"left":"Perfect use","right":"Every time, exactly right"},{"left":"Dual protection","right":"Pregnancy + STIs covered"},{"left":"LARC","right":"Long-acting, nothing to remember"},{"left":"Reversible","right":"Fertility returns after stopping"}],"relearn":"Real-life effectiveness depends on consistent, correct use. That's 'typical use'."},
  {"id":"mc-012","cat":"the-full-picture","type":"sort","persona":"any","source":"consistent use","hook":"Sort: raises real-life effectiveness, or lowers it?","items":[{"id":"a","text":"Using it correctly every single time"},{"id":"b","text":"Skipping pills or going without"},{"id":"c","text":"Knowing how your method works"},{"id":"d","text":"Guessing from rumour"},{"id":"e","text":"Keeping an in-date condom ready"},{"id":"f","text":"Reusing one condom"}],"bins":[{"id":"up","label":"Raises it","valence":"pos"},{"id":"down","label":"Lowers it","valence":"neg"}],"key":{"a":"up","b":"down","c":"up","d":"down","e":"up","f":"down"},"relearn":"Consistent, correct, informed use is what makes a method actually effective."},
  {"id":"mc-013","cat":"the-full-picture","type":"sort","persona":"any","source":"access (RKSK/AFHC)","hook":"Sort: where you can actually get these.","items":[{"id":"a","text":"Condoms at a pharmacy"},{"id":"b","text":"An IUD fitted by a clinician"},{"id":"c","text":"Pills via a doctor / AFHC clinic"},{"id":"d","text":"A reliable method from a rumour"},{"id":"e","text":"The emergency pill at a pharmacy"},{"id":"f","text":"A 'guaranteed' WhatsApp home trick"}],"bins":[{"id":"real","label":"A real source","valence":"pos"},{"id":"no","label":"Not a source","valence":"neg"}],"key":{"a":"real","b":"real","c":"real","d":"no","e":"real","f":"no"},"relearn":"Pharmacies, clinics and doctors are real sources; rumours and home tricks aren't."},
  {"id":"mc-014","cat":"the-full-picture","type":"reflect","hook":"Lensy: with the full picture, the choice of method is genuinely yours. Feel that?","prompt":"What do you think?","options":["Yes","I can choose now","Good to know it all"],"affirm":"Complete information is exactly what makes a choice truly your own.","relearn":"Full, accurate information is what makes the choice genuinely yours.","persona":"Sneha","source":"autonomy"},
  {"id":"mc-015","cat":"the-full-picture","type":"spot","persona":"any","source":"myth-spotting","hook":"Spot the two myths in this 'advice'.","scene":[{"id":"a","text":"\"You can't get pregnant the first time\"","trick":true},{"id":"b","text":"\"Condoms also protect from STIs\"","trick":false},{"id":"c","text":"\"A certain day of the month is always safe\"","trick":true},{"id":"d","text":"\"The pill is reversible\"","trick":false},{"id":"e","text":"\"LARC needs nothing daily\"","trick":false}],"why":"'First time' and 'always safe day' are myths; the other three lines are true.","relearn":"Spot the classic myths; trust evidence, not rumour."},
  {"id":"mc-016","cat":"the-full-picture","type":"strike-rewrite","hook":"\"Only people who have a lot of sex need to think about contraception.\"","myth":{"un":"Only people having lots of sex need contraception.","re":"Any unprotected sex can lead to pregnancy or an STI; and delaying is the certain option.","why":"It's about whether, not how often."},"relearn":"It's the act, not the frequency; informed choice (including delaying) is for everyone.","persona":"any","source":"risk basics"},
  // If, when & whether: choices & rights
  {"id":"mc-017","cat":"if-when-whether","type":"reflect","hook":"Lensy: whether to have children, and when, is genuinely your own choice. Sit with that.","prompt":"What do you think?","options":["It's my choice","Good to know","Reassuring"],"affirm":"Whether, when and how, those are yours to decide, on your timeline.","relearn":"Whether and when to have children is your own choice to make.","persona":"Sneha","source":"reproductive rights"},
  {"id":"mc-018","cat":"if-when-whether","type":"reflect","hook":"Lensy: choosing to delay sex, or not have it for now, is a fully valid, respected choice. Agree?","prompt":"What do you think?","options":["Yes","Totally valid","Respected"],"affirm":"Delaying is wise, certain and entirely your right, no one should pressure you out of it.","relearn":"Delaying or not having sex is fully valid and the most certain choice.","persona":"any","source":"delaying respected"},
  {"id":"mc-019","cat":"if-when-whether","type":"strike-rewrite","hook":"\"A girl your age should be thinking about marriage and babies, not the future.\"","myth":{"un":"At your age you should focus on marriage and babies.","re":"Your education and future are yours to build; family planning is a tool for the life you want.","why":"Whether and when is a personal right, not a deadline set by others."},"relearn":"Your future is yours to plan; whether and when to marry or have children is your choice.","persona":"Sneha","source":"rights / against early marriage"},
  {"id":"mc-020","cat":"if-when-whether","type":"strike-rewrite","hook":"\"Family planning is just about stopping babies.\"","myth":{"un":"Family planning is only about preventing babies.","re":"It's a positive tool to choose if, when and how, for the life and family you want.","why":"Planning is about building a future, not just preventing one thing."},"relearn":"Family planning is a positive tool for the future you choose.","persona":"any","source":"family planning framing"},
  {"id":"mc-021","cat":"if-when-whether","type":"strike-rewrite","hook":"\"Spacing pregnancies doesn't really matter.\"","myth":{"un":"When and how far apart you have children doesn't matter.","re":"Spacing supports the health of parent and child; it's part of planning.","why":"Timing is a real, health-relevant choice."},"relearn":"If and when, including spacing, are real choices that support health.","persona":"Counsellor","source":"family planning / health"},
  {"id":"mc-022","cat":"if-when-whether","type":"sort","hook":"Sort: a personal right, or something others get to force on you?","items":[{"id":"a","text":"Whether you have children"},{"id":"b","text":"When you have them"},{"id":"c","text":"Being forced into it by others"},{"id":"d","text":"Whether you delay sex"},{"id":"e","text":"Whether you marry at all"},{"id":"f","text":"Being shamed for your timeline"}],"bins":[{"id":"right","label":"Your right","valence":"pos"},{"id":"no","label":"Not theirs to force","valence":"neg"}],"key":{"a":"right","b":"right","c":"no","d":"right","e":"right","f":"no"},"relearn":"Whether, when, marrying and delaying are your rights; no one gets to force or shame them.","persona":"any","source":"reproductive rights"},
  {"id":"mc-023","cat":"if-when-whether","type":"sort","hook":"Sort: respects your choice, or pressures it?","items":[{"id":"a","text":"Giving you full information and space"},{"id":"b","text":"Pushing you to 'prove' love by having sex"},{"id":"c","text":"Supporting whatever you decide"},{"id":"d","text":"Shaming you for waiting"},{"id":"e","text":"Letting you take your time"},{"id":"f","text":"Setting a 'now or never' deadline"}],"bins":[{"id":"respect","label":"Respects you","valence":"pos"},{"id":"pressure","label":"Pressures you","valence":"uhoh"}],"key":{"a":"respect","b":"pressure","c":"respect","d":"pressure","e":"respect","f":"pressure"},"relearn":"Respect gives information, space and time; pressure pushes, shames or sets deadlines.","persona":"any","source":"pressure-free"},
  {"id":"mc-024","cat":"if-when-whether","type":"sort","hook":"Sort: no one should be pushed into this, versus what's yours to choose freely.","items":[{"id":"a","text":"Sex"},{"id":"b","text":"Marriage"},{"id":"c","text":"Having a child"},{"id":"d","text":"A freely made, informed choice"},{"id":"e","text":"Deciding your own timeline"},{"id":"f","text":"A child to 'save' a relationship"}],"bins":[{"id":"nopush","label":"Never to be forced","valence":"neg"},{"id":"ok","label":"Yours to make freely","valence":"pos"}],"key":{"a":"nopush","b":"nopush","c":"nopush","d":"ok","e":"ok","f":"nopush"},"relearn":"No one should be pushed into sex, marriage or childbearing; free, informed choice is the point.","persona":"any","source":"consent (links g31)"},
  {"id":"mc-025","cat":"if-when-whether","type":"reflect","hook":"Lensy: 'no pressure in any direction' includes no pressure to wait AND no pressure to rush. Fair?","prompt":"What do you think?","options":["Yes","Both ways","That's real freedom"],"affirm":"Real freedom is the absence of pressure either way, the choice is simply yours.","relearn":"Pressure-free means neither pushed to act nor shamed for waiting.","persona":"any","source":"pressure-free"},
  {"id":"mc-026","cat":"if-when-whether","type":"reflect","hook":"Lensy: knowing your rights here, do you feel more in charge of your own future?","prompt":"What do you think?","options":["Yes","More in charge","It's mine"],"affirm":"Knowing your rights is what puts your future in your own hands.","relearn":"Knowing your reproductive rights puts your future in your hands.","persona":"Arjun","source":"rights / agency"},
  {"id":"mc-027","cat":"if-when-whether","type":"branch","hook":"A relative insists you should marry and start a family soon. It's not what you want yet.","options":[{"text":"Respectfully hold that it's your choice and your timeline","consequence":"You keep ownership of your own future.","outcome":"autonomy","best":true},{"text":"Give in because they expect it","consequence":"Whether and when are your rights; you can hold your timeline respectfully."}],"debrief":"Family input is fine; the decision is still yours to make freely.","relearn":"You can respectfully hold that whether and when are your own choice.","persona":"Sneha","source":"autonomy / family"},
  {"id":"mc-028","cat":"if-when-whether","type":"branch","hook":"You're not ready for sex, but a partner implies everyone your age is doing it.","options":[{"text":"Trust your own pace; 'everyone's doing it' isn't a reason","consequence":"You honour your own readiness.","outcome":"own-pace","best":true},{"text":"Go along so you don't seem behind","consequence":"Your pace is yours; 'everyone' is pressure, not a fact."}],"debrief":"Readiness is personal; delaying is valid and certain.","relearn":"Decide by your own readiness, not 'everyone's doing it'.","persona":"Vijay","source":"delaying / pressure"},
  {"id":"mc-029","cat":"if-when-whether","type":"strike-rewrite","hook":"\"Wanting to wait means something's wrong with you.\"","myth":{"un":"Wanting to wait means something's wrong with you.","re":"Waiting is a common, healthy, fully respected choice.","why":"Readiness differs for everyone, and that's normal."},"relearn":"Choosing to wait is normal, healthy and respected.","persona":"any","source":"delaying respected"},
  // Decide It: values-based decisions
  {"id":"mc-030","cat":"decide-it","type":"branch","hook":"Decide It. You're choosing whether and how to be sexually active. How do you decide soundly?","options":[{"text":"Gather the facts, check your own values, decide freely, and own it","consequence":"You make a real, informed, self-owned choice.","outcome":"values-based","best":true},{"text":"Just do whatever your friends or partner expect","consequence":"That follows others' expectations, not your own values."}],"debrief":"Deciding well: gather facts, weigh values and consequences, choose freely, own it.","relearn":"Decide by facts and your own values, freely, and own it.","persona":"any","source":"decision skill"},
  {"id":"mc-031","cat":"decide-it","type":"branch","hook":"Decide It. You and a partner are active and want to avoid both pregnancy and STIs.","options":[{"text":"Use condoms (optionally plus another method for extra pregnancy cover)","consequence":"You get STI protection plus strong pregnancy cover.","outcome":"dual","best":true},{"text":"Use the pill alone and skip condoms","consequence":"The pill won't stop STIs; only condoms give that dual protection."}],"debrief":"For both pregnancy and STIs, condoms are essential, optionally paired for cover.","relearn":"Want both kinds of protection? Condoms are the dual-protection move.","persona":"Vijay","source":"dual protection"},
  {"id":"mc-032","cat":"decide-it","type":"branch","hook":"Decide It. A condom split during sex last night. What's the informed move?","options":[{"text":"Consider emergency contraception soon, it works best within 5 days","consequence":"You act in the window where EC can prevent pregnancy.","outcome":"ec","best":true},{"text":"Just hope for the best","consequence":"EC works within 5 days (sooner is better); it's the backup for exactly this."}],"debrief":"After unprotected sex or a split, EC within 5 days is the backup option.","relearn":"After a slip, emergency contraception works best within 5 days.","persona":"any","source":"emergency contraception (WHO)"},
  {"id":"mc-033","cat":"decide-it","type":"branch","hook":"Decide It. You keep forgetting the daily pill. How do you decide what fits your life?","options":[{"text":"Consider a method that doesn't need daily action, like a LARC","consequence":"You pick a method that matches how you actually live.","outcome":"fit","best":true},{"text":"Keep forgetting and hope it's fine","consequence":"If daily isn't working, a set-and-forget method may fit you better; ask a clinician."}],"debrief":"The 'best' method is the one you'll actually use consistently.","relearn":"Match the method to your real life; a forgotten pill protects less.","persona":"Sneha","source":"method fit"},
  {"id":"mc-034","cat":"decide-it","type":"branch","hook":"Decide It. You're unsure and want to choose well. Where do the facts come from?","options":[{"text":"A doctor / AFHC clinic and reliable sources","consequence":"Your decision rests on accurate information.","outcome":"informed","best":true},{"text":"Whatever a forwarded message claims","consequence":"Decide from a clinician and reliable sources, not forwards."}],"debrief":"A good decision starts with accurate facts from real sources.","relearn":"Base the choice on a clinician and reliable sources, not rumour.","persona":"any","source":"informed decisions"},
  {"id":"mc-035","cat":"decide-it","type":"branch","hook":"Decide It. There's no single 'right' life choice here, but some things hold always. Which?","options":[{"text":"Consent, safety and the law are non-negotiable","consequence":"You keep the floor that protects everyone.","outcome":"non-negotiables","best":true},{"text":"Anything goes if you want it enough","consequence":"Personal choices vary, but consent, safety and law always hold."}],"debrief":"Beyond consent, safety and law, the diverse choices people make are legitimate.","relearn":"Consent, safety and law are the non-negotiables; the rest is your values.","persona":"Counsellor","source":"non-negotiables"},
  {"id":"mc-036","cat":"decide-it","type":"branch","hook":"Decide It. A partner says using a condom 'means you don't trust them'.","options":[{"text":"Keep your boundary; protection is about health, not trust","consequence":"You protect yourself and set a fair standard.","outcome":"boundary","best":true},{"text":"Drop it to avoid upsetting them","consequence":"Protection isn't an insult; a caring partner respects it."}],"debrief":"Insisting on protection is health-smart and reasonable; pressure against it is a flag.","relearn":"Protection is about health, not distrust; hold the boundary.","persona":"Vijay","source":"consent / negotiation"},
  {"id":"mc-037","cat":"decide-it","type":"branch","hook":"Decide It. You realise you're choosing mostly to please someone else.","options":[{"text":"Pause, and re-decide from your own values","consequence":"You take the choice back as your own.","outcome":"self-owned","best":true},{"text":"Carry on to keep them happy","consequence":"A real choice is yours, not made to please someone else."}],"debrief":"If a choice isn't truly yours, you can pause and reclaim it.","relearn":"A genuine choice is owned by you, not made to please others.","persona":"any","source":"autonomy"},
  {"id":"mc-038","cat":"decide-it","type":"branch","hook":"Decide It. You're under 18 and a much older person is pushing a sexual relationship.","options":[{"text":"Step back and tell a trusted adult; the law protects you here","consequence":"You stay safe and supported.","outcome":"protected","best":true},{"text":"Go along to seem mature","consequence":"Pressure from an older person is a red flag to report."}],"debrief":"For under-18s the age of consent (18) protects you; coercion is a child-protection matter.","relearn":"Under 18, the law protects you; tell a trusted adult about an older person's pressure.","persona":"Counsellor","source":"POCSO / age of consent 18"},
  {"id":"mc-039","cat":"decide-it","type":"reflect","hook":"Lensy: the 'Decide It' skill, facts + values + free choice + ownership, works for big decisions for life. See it?","prompt":"What do you think?","options":["Yes","A skill for life","I can use this"],"affirm":"That four-step way of deciding will serve you far beyond this topic.","relearn":"Facts, values, free choice and ownership is a decision skill for life.","persona":"any","source":"decision skill"},
  {"id":"mc-040","cat":"decide-it","type":"reflect","hook":"Lensy: which part of deciding well do you most want to get better at?","prompt":"Pick one.","options":["Gathering real facts","Knowing my values","Choosing free of pressure","Owning it"],"affirm":"Strengthening any one of those makes your choices more truly yours.","relearn":"Facts, values, freedom and ownership are the parts of a good decision.","persona":"Arjun","source":"decision skill"},
  {"id":"mc-041","cat":"decide-it","type":"reflect","hook":"Lensy: there's no single 'right' life here, only your informed, freely made choice. Freeing?","prompt":"What do you think?","options":["Yes","Less judged","It's mine"],"affirm":"Beyond the non-negotiables, your legitimate choices are yours alone, and that's freedom.","relearn":"Beyond consent, safety and law, your informed choice is yours, no single 'right' answer.","persona":"any","source":"non-judgmental"},
  {"id":"mc-042","cat":"decide-it","type":"reflect","hook":"Lensy: a good decision can still feel hard. Knowing your values makes it clearer. Agree?","prompt":"What do you think?","options":["Yes","Values guide me","Clearer"],"affirm":"Your values are the compass when a choice feels genuinely hard.","relearn":"Knowing your own values guides you through hard decisions.","persona":"any","source":"values"},
  {"id":"mc-043","cat":"decide-it","type":"branch","hook":"Decide It. Friends pressure a quick decision 'right now'.","options":[{"text":"Take the time you need; a real choice isn't rushed","consequence":"You decide calmly and well.","outcome":"unrushed","best":true},{"text":"Decide on the spot to satisfy them","consequence":"You're allowed to take time; pressure to rush isn't a reason."}],"debrief":"Good decisions get the time they need; urgency is often just pressure.","relearn":"You can take the time a real decision needs; don't be rushed.","persona":"any","source":"unrushed choice"},
  {"id":"mc-044","cat":"decide-it","type":"spot","persona":"any","source":"decision skill","relearn":"Catch the two pressured reasons; the others are values-based, freely owned choices.","hook":"Catch the two pressured reasons; the others are values-based, freely owned choices.","scene":[{"id":"a","text":"Weighing facts against what matters to you","trick":false},{"id":"b","text":"Doing it because you'll look cool","trick":true},{"id":"c","text":"Choosing freely and owning it","trick":false},{"id":"d","text":"Doing it to avoid disappointing someone","trick":true},{"id":"e","text":"Deciding by your own values","trick":false}],"why":"Doing it for image or to avoid disappointment is pressure; weighing facts and choosing freely is deciding well."},
  {"id":"mc-045","cat":"decide-it","type":"reflect","hook":"Lensy: whatever you decide, deciding it well, informed and freely, is the win here. Yes?","prompt":"What do you think?","options":["Yes","The process matters","I've got this"],"affirm":"Deciding well is the real skill, the specific choice is yours.","relearn":"Deciding well, informed and free, is the win, whatever you choose.","persona":"any","source":"decision skill"},
  // Access & rights: making it real
  {"id":"mc-046","cat":"access-and-rights","type":"branch","hook":"You want contraception but worry it won't be private.","options":[{"text":"Use an Adolescent Friendly Health Clinic / doctor, confidentiality is part of the service","consequence":"You get private, professional care.","outcome":"confidential","best":true},{"text":"Give up because you assume everyone will know","consequence":"AFHCs and doctors offer confidential services; you can ask privately."}],"debrief":"Confidential services exist; privacy is part of good care.","relearn":"AFHCs / doctors offer confidential contraceptive services.","persona":"Sneha","source":"access / confidentiality (RKSK)"},
  {"id":"mc-047","cat":"access-and-rights","type":"match","hook":"Match the need to where to go (India).","pairs":[{"left":"Confidential adolescent SRH care","right":"AFHC / Ujala clinic"},{"left":"A method or prescription","right":"A doctor / family-planning service"},{"left":"Condoms / EC pills","right":"A pharmacy"},{"left":"Pressure from an older person","right":"A trusted adult / Childline 1098"},{"left":"A general health check too","right":"Your regular doctor"}],"relearn":"India routes: AFHC/Ujala clinics, doctors, pharmacies, and Childline for coercion.","persona":"Counsellor","source":"access (RKSK/AFHC)"},
  {"id":"mc-048","cat":"access-and-rights","type":"match","hook":"Match your right to what backs it.","pairs":[{"left":"To decide if/when/whether","right":"Reproductive rights"},{"left":"To private care","right":"Confidentiality"},{"left":"To be free from coercion","right":"Protection from exploitation"},{"left":"To accurate information","right":"Adolescent-friendly services"},{"left":"To go at your own pace","right":"Your own timeline"}],"relearn":"Your choices, privacy, freedom from coercion and information are real, backed rights.","persona":"any","source":"rights"},
  {"id":"mc-049","cat":"access-and-rights","type":"role-play","hook":"You're nervous to ask a clinician for contraception.","setup":"Keep it simple and direct. Say:","yourLine":[{"text":"\"I'd like to talk about contraception options, privately. Can you help me?\"","best":true},{"text":"Say nothing and leave"}],"relearn":"A simple, direct ask is all it takes to start; clinicians are there to help.","persona":"Arjun","source":"self-advocacy"},
  {"id":"mc-050","cat":"access-and-rights","type":"role-play","hook":"You want to ask whether your visit stays confidential.","setup":"Ask plainly. Say:","yourLine":[{"text":"\"Is what we discuss here kept confidential?\"","best":true},{"text":"Worry silently and never ask"}],"relearn":"You can ask up front what stays private; they'll explain, including the one legal limit.","persona":"any","source":"confidentiality"},
  {"id":"mc-051","cat":"access-and-rights","type":"role-play","hook":"A friend doesn't know services exist. Point them the right way.","setup":"Share what you know. Say:","yourLine":[{"text":"\"There are adolescent-friendly clinics for this, confidential, and a doctor can help too.\"","best":true},{"text":"\"No idea, you're on your own.\""}],"relearn":"Knowing services exist lets you guide a friend to confidential help.","persona":"Vijay","source":"peer support"},
  {"id":"mc-052","cat":"access-and-rights","type":"branch","hook":"You're under 18 and unsure if you can access services or info.","options":[{"text":"Seek adolescent-friendly services and a trusted adult or doctor's guidance","consequence":"You get age-appropriate, supportive help.","outcome":"supported","best":true},{"text":"Assume you're not allowed anything and stay in the dark","consequence":"Those services exist precisely for your age."}],"debrief":"Adolescent-friendly services and trusted guidance are made for under-18s.","relearn":"Under 18, adolescent-friendly services and trusted adults can guide you.","persona":"Counsellor","source":"access for adolescents"},
  {"id":"mc-053","cat":"access-and-rights","type":"branch","hook":"Someone is pressuring or exploiting you sexually and you feel trapped.","options":[{"text":"Tell a trusted adult / doctor; coercion is a child-protection matter","consequence":"You get protection and support.","outcome":"protected","best":true},{"text":"Stay silent and cope alone","consequence":"Coercion or exploitation is never your fault; a trusted adult can protect you."}],"debrief":"Pressure or exploitation is a safeguarding matter, route it to help, never carry it alone.","relearn":"Coercion or exploitation: tell a trusted adult / doctor; it's a child-protection matter.","persona":"Counsellor","source":"safeguarding / POCSO"},
  {"id":"mc-054","cat":"access-and-rights","type":"strike-rewrite","hook":"\"You need a parent's permission for any contraception info.\"","myth":{"un":"You can't get any contraception information without a parent's permission.","re":"Adolescent-friendly services offer confidential information and counselling.","why":"Confidentiality is a core part of these services."},"relearn":"Confidential adolescent services exist; you can seek information privately.","persona":"any","source":"confidentiality (RKSK)"},
  {"id":"mc-055","cat":"access-and-rights","type":"strike-rewrite","hook":"\"Asking a doctor about this is embarrassing and they'll judge you.\"","myth":{"un":"A doctor will judge you for asking about contraception.","re":"Clinicians are there to inform and help, not judge; it's routine care.","why":"This is exactly what these services are for."},"relearn":"Clinicians help, not judge; asking is normal, smart self-care.","persona":"Arjun","source":"self-advocacy"},
  {"id":"mc-056","cat":"access-and-rights","type":"sort","hook":"Sort: a safe, real way to access care, or not?","items":[{"id":"a","text":"An AFHC / Ujala clinic"},{"id":"b","text":"A licensed doctor"},{"id":"c","text":"An unverified online 'cure'"},{"id":"d","text":"A pharmacy for condoms"},{"id":"e","text":"A trusted adult's guidance"},{"id":"f","text":"A stranger selling 'pills' in chat"}],"bins":[{"id":"safe","label":"Safe / real","valence":"pos"},{"id":"no","label":"Not safe","valence":"neg"}],"key":{"a":"safe","b":"safe","c":"no","d":"safe","e":"safe","f":"no"},"relearn":"Clinics, doctors, pharmacies and trusted adults are safe; unverified 'cures' and chat sellers aren't.","persona":"any","source":"safe access"},
  {"id":"mc-057","cat":"access-and-rights","type":"sort","hook":"Sort: part of your rights, or not?","items":[{"id":"a","text":"Confidential care"},{"id":"b","text":"Deciding whether and when"},{"id":"c","text":"Being coerced into sex"},{"id":"d","text":"Accurate information"},{"id":"e","text":"Deciding at your own pace"},{"id":"f","text":"Being shamed into a choice"}],"bins":[{"id":"right","label":"Your right","valence":"pos"},{"id":"no","label":"A violation","valence":"neg"}],"key":{"a":"right","b":"right","c":"no","d":"right","e":"right","f":"no"},"relearn":"Confidential care, free choice, accurate info and your own pace are rights; coercion and shaming are violations.","persona":"any","source":"rights"},
  {"id":"mc-058","cat":"access-and-rights","type":"reflect","hook":"Lensy: knowledge only protects if you can act on it, and now you know where to go. Ready?","prompt":"What do you think?","options":["Yes","I know where to go","Ready"],"affirm":"Knowing the services turns information into something you can actually use.","relearn":"Knowing where to access services turns knowledge into real protection.","persona":"any","source":"access"},
  // Talk it through: partner & doctor
  {"id":"mc-059","cat":"talk-it-through","type":"role-play","hook":"You want to agree on protection with a partner, before anything.","setup":"Be clear and matter-of-fact. Say:","yourLine":[{"text":"\"If we ever do this, I want us to use protection. Are we agreed?\"","best":true},{"text":"Hope it just sorts itself out"}],"relearn":"Agreeing on protection beforehand is mature and caring.","persona":"Vijay","source":"partner communication"},
  {"id":"mc-060","cat":"talk-it-through","type":"role-play","hook":"A partner brushes off the conversation as 'unromantic'.","setup":"Hold it kindly but firmly. Say:","yourLine":[{"text":"\"Looking after each other is part of caring. Let's talk about it.\"","best":true},{"text":"\"Okay, forget I said anything.\""}],"relearn":"Caring includes the practical talk; a good partner will have it.","persona":"any","source":"partner communication"},
  {"id":"mc-061","cat":"talk-it-through","type":"role-play","hook":"You need to tell a partner you're not ready yet.","setup":"Be honest and kind. Say:","yourLine":[{"text":"\"I'm not ready for that yet, and I need you to respect that.\"","best":true},{"text":"Go along to avoid the conversation"}],"relearn":"You can say you're not ready and ask for respect, clearly.","persona":"Sneha","source":"boundaries"},
  {"id":"mc-062","cat":"talk-it-through","type":"role-play","hook":"You want to ask a doctor a question you find embarrassing.","setup":"Just ask it plainly. Say:","yourLine":[{"text":"\"This feels awkward to ask, but I want to understand my options.\"","best":true},{"text":"Leave without asking"}],"relearn":"Naming the awkwardness and asking anyway gets you the answers.","persona":"Arjun","source":"clinician communication"},
  {"id":"mc-063","cat":"talk-it-through","type":"role-play","hook":"A partner says they 'don't like' condoms.","setup":"Problem-solve together, keep the boundary. Say:","yourLine":[{"text":"\"Then let's find a protection plan we're both okay with, but protection stays.\"","best":true},{"text":"Drop protection to please them"}],"relearn":"You can negotiate the method, but keep protection itself non-negotiable.","persona":"Vijay","source":"negotiation"},
  {"id":"mc-064","cat":"talk-it-through","type":"role-play","hook":"You want to check in that a partner is comfortable and willing.","setup":"Ask, genuinely. Say:","yourLine":[{"text":"\"Are you okay with this, and do you actually want to?\"","best":true},{"text":"Assume it's fine without asking"}],"relearn":"Checking that a partner is comfortable and willing is part of consent.","persona":"any","source":"consent (links g31)"},
  {"id":"mc-065","cat":"talk-it-through","type":"branch","hook":"A partner won't discuss protection at all and gets annoyed.","options":[{"text":"Treat refusal-to-discuss as a serious flag, and don't proceed unprotected","consequence":"You protect your health and standards.","outcome":"safe","best":true},{"text":"Proceed anyway to keep the peace","consequence":"Refusing the conversation is a flag; don't proceed unprotected to keep peace."}],"debrief":"A partner who won't even discuss protection isn't respecting your health.","relearn":"Refusal to discuss protection is a flag; don't proceed unprotected.","persona":"any","source":"red flags"},
  {"id":"mc-066","cat":"talk-it-through","type":"branch","hook":"You don't know how to start the conversation at all.","options":[{"text":"Pick a calm, private moment and start simply and honestly","consequence":"The talk goes better than the dread suggested.","outcome":"opened","best":true},{"text":"Avoid it forever","consequence":"A calm, private, simple opener makes the talk doable."}],"debrief":"A calm moment and a simple honest start is usually all it takes.","relearn":"Start the talk simply, in a calm private moment.","persona":"Arjun","source":"communication"},
  {"id":"mc-067","cat":"talk-it-through","type":"branch","hook":"A friend asks you how to bring protection up with their partner.","options":[{"text":"Help them script a clear, kind, matter-of-fact line","consequence":"They feel ready to have the talk.","outcome":"helpful","best":true},{"text":"Tell them it's too awkward to bother","consequence":"A simple scripted line makes it doable; help them prepare."}],"debrief":"Helping a friend prepare the words makes a hard talk easy.","relearn":"A clear, kind, prepared line makes the protection talk doable.","persona":"Vijay","source":"peer support"},
  {"id":"mc-068","cat":"talk-it-through","type":"spot","hook":"Spot the two lines that aren't a respectful protection talk.","scene":[{"id":"a","text":"Both calmly agreeing on a plan","trick":false},{"id":"b","text":"One guilt-tripping the other out of it","trick":true},{"id":"c","text":"Checking each other's comfort","trick":false},{"id":"d","text":"Pressuring for a quick yes","trick":true},{"id":"e","text":"Listening to what each wants","trick":false}],"why":"Guilt-tripping and pressuring for a yes aren't respectful; agreeing, checking and listening are.","relearn":"Respectful talks are mutual and check comfort, not guilt-trips or pressure.","persona":"any","source":"respect"},
  {"id":"mc-069","cat":"talk-it-through","type":"spot","hook":"Spot the two things that make this conversation go badly.","scene":[{"id":"a","text":"Honesty about what you want and don't","trick":false},{"id":"b","text":"Listening to the other person","trick":false},{"id":"c","text":"Pressuring for a 'yes'","trick":true},{"id":"d","text":"Mocking them for raising protection","trick":true},{"id":"e","text":"Agreeing a plan you both like","trick":false}],"why":"Pressuring for a yes and mocking the topic break the talk; honesty, listening and agreeing help.","relearn":"Honesty and listening make the talk work; pressure and mockery break it.","persona":"any","source":"communication"},
  {"id":"mc-070","cat":"talk-it-through","type":"reflect","hook":"Lensy: being able to talk this through, with a partner and a doctor, is a real adult skill. Feel ready to build it?","prompt":"What do you think?","options":["Yes","I'll practise","Ready"],"affirm":"Talking openly about health and boundaries is a skill that protects you for life.","relearn":"Talking it through with partners and doctors is a protective adult skill.","persona":"any","source":"communication"},
  // My future: no pressure, your values
  {"id":"mc-071","cat":"my-future-no-pressure","type":"strike-rewrite","hook":"\"Choosing to wait makes you a prude.\"","myth":{"un":"Choosing to wait makes you a prude.","re":"Waiting is a valid, respected, common choice, and the most certain one.","why":"Labels are just pressure dressed up."},"relearn":"Waiting is valid and respected, not something to be labelled for.","persona":"Sneha","source":"delaying respected"},
  {"id":"mc-072","cat":"my-future-no-pressure","type":"strike-rewrite","hook":"\"Choosing to be active means you're irresponsible.\"","myth":{"un":"Being sexually active means you're irresponsible.","re":"Active or not, what matters is that the choice is informed, consensual and protected.","why":"Responsibility is about how you decide, not the choice itself."},"relearn":"Responsibility is informed, consensual, protected choice, whatever you decide.","persona":"any","source":"non-judgmental"},
  {"id":"mc-073","cat":"my-future-no-pressure","type":"strike-rewrite","hook":"\"Your future is already decided for you.\"","myth":{"un":"Your future is already decided for you.","re":"Your education, relationships and family choices are yours to shape.","why":"Planning is how you take the wheel."},"relearn":"Your future is yours to shape; planning puts you in the driver's seat.","persona":"Sneha","source":"agency"},
  {"id":"mc-074","cat":"my-future-no-pressure","type":"strike-rewrite","hook":"\"Knowing all this will just make you go and have sex.\"","myth":{"un":"Comprehensive information makes young people have sex.","re":"Good information helps people make safer, more thoughtful choices, including delaying.","why":"Knowledge supports decisions; it doesn't dictate them."},"relearn":"Accurate information leads to safer, more thoughtful choices, not pressure to act.","persona":"Counsellor","source":"CSE evidence"},
  {"id":"mc-075","cat":"my-future-no-pressure","type":"strike-rewrite","hook":"\"Real adults just figure this out without help.\"","myth":{"un":"Mature people don't need information or to ask.","re":"Seeking accurate information and asking is exactly what maturity looks like.","why":"Owning your choices means informing them."},"relearn":"Getting informed and asking is what real maturity looks like.","persona":"Arjun","source":"maturity"},
  {"id":"mc-076","cat":"my-future-no-pressure","type":"reflect","hook":"Lensy: picture the life you want. How do these choices serve it?","prompt":"Pick what matters to you.","options":["My education / goals","Healthy relationships","Being ready on my terms","All of it"],"affirm":"These choices are tools for the future you're building, on your terms.","relearn":"Reproductive choices are tools for the future and life you want.","persona":"Sneha","source":"values / future"},
  {"id":"mc-077","cat":"my-future-no-pressure","type":"reflect","hook":"Lensy: 'no pressure in any direction' is the whole spirit here. Does that feel respectful?","prompt":"What do you think?","options":["Yes","Respectful","My call"],"affirm":"No pressure either way, just full information and your own free choice.","relearn":"The spirit is no pressure in any direction, just info and your free choice.","persona":"any","source":"pressure-free"},
  {"id":"mc-078","cat":"my-future-no-pressure","type":"spot","hook":"Spot the two pressure lines (so you can refuse them).","scene":[{"id":"a","text":"\"Everyone's doing it, don't be a baby\"","trick":true},{"id":"b","text":"\"Here's the full info, it's your call\"","trick":false},{"id":"c","text":"\"If you really loved me you would\"","trick":true},{"id":"d","text":"\"No rush at all, decide when you're ready\"","trick":false},{"id":"e","text":"\"Whatever you choose is okay with me\"","trick":false}],"why":"'Everyone's doing it' and 'if you loved me' are pressure; the rest give you space.","relearn":"Spot pressure lines like 'everyone's doing it' and 'if you loved me' and refuse them.","persona":"Vijay","source":"spot pressure"},
  {"id":"mc-079","cat":"my-future-no-pressure","type":"spot","hook":"Spot the two lines that pressure your choice instead of supporting it.","scene":[{"id":"a","text":"Giving you accurate facts","trick":false},{"id":"b","text":"Shaming whichever choice you make","trick":true},{"id":"c","text":"Letting you decide on your timeline","trick":false},{"id":"d","text":"Guilt-tripping you for waiting","trick":true},{"id":"e","text":"Backing whatever you pick","trick":false}],"why":"Shaming and guilt-tripping are pressure; facts, space and backing your choice are support.","relearn":"Real support gives facts and space; shaming or guilt-tripping a choice is pressure.","persona":"any","source":"pressure-free"},
  {"id":"mc-080","cat":"my-future-no-pressure","type":"spot","hook":"Spot the two signs a decision isn't really your own.","scene":[{"id":"a","text":"You could explain your reasons by your values","trick":false},{"id":"b","text":"You're mainly avoiding someone's disappointment","trick":true},{"id":"c","text":"You'd choose the same with no one watching","trick":false},{"id":"d","text":"You're doing it to stop the gossip","trick":true},{"id":"e","text":"It fits what you actually want","trick":false}],"why":"Avoiding disappointment or silencing gossip means it isn't yours; reasoned, unobserved choice means it is.","relearn":"A choice isn't yours if it's mainly to avoid disappointment or stop gossip; pause and re-decide.","persona":"any","source":"autonomy"},
  {"id":"mc-081","cat":"my-future-no-pressure","type":"sort","hook":"Sort: respects your autonomy, or undermines it?","items":[{"id":"a","text":"Full, accurate information"},{"id":"b","text":"Scare tactics"},{"id":"c","text":"Your free, owned choice"},{"id":"d","text":"Guilt and labels"},{"id":"e","text":"Space and time to decide"},{"id":"f","text":"Rushing you for an answer"}],"bins":[{"id":"respect","label":"Respects autonomy","valence":"pos"},{"id":"under","label":"Undermines it","valence":"neg"}],"key":{"a":"respect","b":"under","c":"respect","d":"under","e":"respect","f":"under"},"relearn":"Information, free choice and time respect autonomy; scares, guilt, labels and rushing undermine it.","persona":"any","source":"autonomy"},
  {"id":"mc-082","cat":"my-future-no-pressure","type":"sort","hook":"Sort: a healthy basis for a choice, or a poor one?","items":[{"id":"a","text":"Accurate facts"},{"id":"b","text":"Your own values"},{"id":"c","text":"Fear of being judged"},{"id":"d","text":"A rumour"},{"id":"e","text":"Time to think"},{"id":"f","text":"Wanting to please someone"}],"bins":[{"id":"good","label":"Healthy basis","valence":"pos"},{"id":"poor","label":"Poor basis","valence":"neg"}],"key":{"a":"good","b":"good","c":"poor","d":"poor","e":"good","f":"poor"},"relearn":"Decide from facts, your values and time; not fear, rumour or pleasing someone else.","persona":"any","source":"decision basis"},
  {"id":"mc-083","cat":"my-future-no-pressure","type":"sort","hook":"Sort: a respected choice, or a forced one?","items":[{"id":"a","text":"Deciding to wait"},{"id":"b","text":"Being coerced into sex"},{"id":"c","text":"Freely choosing your method"},{"id":"d","text":"Being shamed into a decision"},{"id":"e","text":"Choosing your own timeline"},{"id":"f","text":"Being rushed into 'yes'"}],"bins":[{"id":"respected","label":"Respected choice","valence":"pos"},{"id":"forced","label":"Forced / wrong","valence":"neg"}],"key":{"a":"respected","b":"forced","c":"respected","d":"forced","e":"respected","f":"forced"},"relearn":"Waiting, free choice and your own timeline are respected; coercion, shaming and rushing are not.","persona":"any","source":"autonomy"},
  {"id":"mc-084","cat":"my-future-no-pressure","type":"reflect","hook":"Lensy: biggest take-away from My Choices, My Future?","prompt":"Pick your motto.","options":["My choices, my information","No pressure, any direction","Delaying is fully valid","Decide by my values"],"affirm":"Full information, zero pressure, and a choice that's genuinely yours, that's the whole point.","relearn":"Your choices, full information, no pressure, decided by your own values.","persona":"any","source":"consolidation"},
  {"id":"mc-900","cat":"access-and-rights","type":"branch","hook":"You want your options but worry clinic staff might tell your parents.","options":[{"text":"Ask at an Adolescent-Friendly Clinic, where confidentiality is part of the service","consequence":"You get private, professional information.","outcome":"private","best":true},{"text":"Search random forums so no one finds out","consequence":"AFHCs are built to be confidential; forums mislead."}],"debrief":"Adolescent-friendly clinics are designed to be private; that's their point.","relearn":"AFHC / Ujala clinics give confidential info; staff won't tell your family.","persona":"Arjun","source":"confidentiality (RKSK)"},
  {"id":"mc-901","cat":"access-and-rights","type":"branch","hook":"You're 16 and a much older person is pushing you toward a sexual relationship.","options":[{"text":"Step back and tell a trusted adult or call Childline 1098","consequence":"You get protection and support.","outcome":"protected","best":true},{"text":"Go along because they say it's normal","consequence":"This is exploitation, not a relationship; a trusted adult can protect you."}],"debrief":"An older person pressuring a minor is exploitation, never your fault; reach for help.","relearn":"Older-person pressure on a minor: step back, tell a trusted adult or Childline 1098.","persona":"Counsellor","source":"safeguarding"},
  {"id":"mc-902","cat":"access-and-rights","type":"branch","hook":"You need emergency contraception but feel awkward walking into a pharmacy.","options":[{"text":"Ask the pharmacist plainly; it's a routine request they handle often","consequence":"You get it quickly, when timing matters most.","outcome":"acted","best":true},{"text":"Wait days hoping the worry passes","consequence":"EC works best soon after; a pharmacist handles this routinely."}],"debrief":"A pharmacist is there to help; asking is normal and timing matters.","relearn":"Pharmacies stock emergency contraception; asking plainly is routine.","persona":"any","source":"access (pharmacy)"},
  {"id":"mc-903","cat":"access-and-rights","type":"branch","hook":"A clinic visit feels intimidating and you almost turn back at the door.","options":[{"text":"Go in and say you'd like to ask about your options privately","consequence":"The visit is calmer and more helpful than the dread suggested.","outcome":"asked","best":true},{"text":"Leave and tell yourself it's not allowed","consequence":"These services exist for you; a simple opener is all it takes."}],"debrief":"The hardest part is the door; a clinician is there to inform, not judge.","relearn":"Clinicians inform and help, not judge; a simple ask starts the visit.","persona":"Vijay","source":"self-advocacy"},
  {"id":"mc-904","cat":"access-and-rights","type":"branch","hook":"You're not sure whether the clinic keeps your visit confidential.","options":[{"text":"Ask directly whether what you share stays private","consequence":"You get a clear answer and decide with full information.","outcome":"informed","best":true},{"text":"Assume the worst and share nothing useful","consequence":"You're allowed to ask about confidentiality before you share."}],"debrief":"Asking plainly about privacy is your right and a normal first question.","relearn":"Ask up front what stays private; a clinician will explain it, including the one legal limit.","persona":"any","source":"confidentiality"},
  {"id":"mc-905","cat":"access-and-rights","type":"branch","hook":"A friend confides that an adult is coercing them and begs you to keep it secret.","options":[{"text":"Help them reach a trusted adult or Childline 1098 together","consequence":"Your friend gets real protection, not just a kept secret.","outcome":"helped","best":true},{"text":"Promise total silence and do nothing","consequence":"Coercion is a safeguarding matter; a trusted adult can actually help."}],"debrief":"Some secrets are too heavy to hold alone; safeguarding help protects your friend.","relearn":"If a friend is coerced, help them reach a trusted adult or Childline 1098.","persona":"any","source":"peer safeguarding"},
  {"id":"mc-906","cat":"access-and-rights","type":"branch","hook":"You assume the info needs a parent's signature, so you never ask.","options":[{"text":"Visit an adolescent-friendly service, which provides it confidentially","consequence":"You get information you have a right to.","outcome":"accessed","best":true},{"text":"Stay uninformed, sure permission is required","consequence":"No parent's permission is needed; services provide it."}],"debrief":"Information is your right; adolescent services give it confidentially.","relearn":"You don't need a parent's permission for contraception information.","persona":"Sneha","source":"rights / access"},
  {"id":"mc-907","cat":"access-and-rights","type":"branch","hook":"You know the facts but have no idea where to actually go in your town.","options":[{"text":"Find your nearest AFHC / Ujala clinic or ask a doctor where to go","consequence":"Knowledge becomes something you can actually act on.","outcome":"located","best":true},{"text":"Decide it's all theoretical and drop it","consequence":"Knowing where to go is part of the right; a clinic or doctor can point you."}],"debrief":"Knowledge only protects when you know where to go and how to ask.","relearn":"Knowing the place and the words to use is part of the right itself.","persona":"Counsellor","source":"access (knowing where)"},
  {"id":"mc-908","cat":"access-and-rights","type":"branch","hook":"You feel you should only ask a clinic once you're already having sex.","options":[{"text":"Ask now; getting informed early is exactly what services are for","consequence":"You decide from facts, not after a scare.","outcome":"prepared","best":true},{"text":"Wait until something goes wrong to ask","consequence":"Services are for getting informed in advance, not only in a crisis."}],"debrief":"Asking before, not after, is what these services are designed for.","relearn":"You can use adolescent-friendly services to get informed in advance.","persona":"any","source":"access timing"},
  {"id":"mc-909","cat":"access-and-rights","type":"branch","hook":"Your partner says clinics will gossip, so you should both just avoid them.","options":[{"text":"Point out that confidentiality is part of the service and go anyway","consequence":"You both get accurate, private guidance.","outcome":"informed","best":true},{"text":"Agree to stay away and rely on rumours","consequence":"Confidentiality is built into these services; rumours mislead."}],"debrief":"Fear of gossip shouldn't cost you private, accurate care.","relearn":"Confidentiality is built into adolescent services; don't let rumour block care.","persona":"Vijay","source":"confidentiality"},
  {"id":"mc-910","cat":"access-and-rights","type":"branch","hook":"You're worried a clinician will lecture you about your relationship.","options":[{"text":"Go anyway; their job is to inform and support, not to moralise","consequence":"You get respectful, useful care.","outcome":"respected","best":true},{"text":"Avoid care to dodge a lecture you're imagining","consequence":"Clinicians are there to help, not judge your relationship."}],"debrief":"Care is about your health, not a verdict on your life.","relearn":"A clinician's role is to inform and support, not judge your relationship.","persona":"Arjun","source":"non-judgment"},
  {"id":"mc-911","cat":"access-and-rights","type":"branch","hook":"You can't decide between an adolescent clinic and asking around your hostel.","options":[{"text":"Choose the AFHC / Ujala clinic for accurate, confidential guidance","consequence":"You get reliable information from people trained for it.","outcome":"reliable","best":true},{"text":"Trust hostel gossip because it's easier","consequence":"Trained services give accurate, private answers; gossip doesn't."}],"debrief":"For real answers, go to the trained, confidential service, not the rumour mill.","relearn":"For accurate, private guidance, choose a clinic over hostel rumour.","persona":"any","source":"reliable access"},
  {"id":"mc-912","cat":"access-and-rights","type":"match","hook":"Match the need to the right place to go (India).","pairs":[{"left":"Confidential adolescent SRH guidance","right":"AFHC / Ujala clinic"},{"left":"A prescription method like the pill","right":"A doctor or family-planning service"},{"left":"Condoms or emergency contraception","right":"A pharmacy"},{"left":"Coercion by an older person","right":"Childline 1098 / a trusted adult"},{"left":"A general health worry alongside this","right":"Your regular doctor"}],"relearn":"Different needs route to clinics, doctors, pharmacies, or Childline 1098.","persona":"Counsellor","source":"access routes"},
  {"id":"mc-913","cat":"access-and-rights","type":"match","hook":"Match your right to what backs it up.","pairs":[{"left":"To decide if and when to have children","right":"Your reproductive rights"},{"left":"To private care","right":"Confidentiality of the service"},{"left":"To be free from sexual pressure","right":"Protection from coercion"},{"left":"To accurate information","right":"Adolescent-friendly services"},{"left":"To take your time deciding","right":"Your own timeline"}],"relearn":"Your choices, privacy, safety and information are real, backed rights.","persona":"any","source":"rights"},
  {"id":"mc-914","cat":"access-and-rights","type":"match","hook":"Match the clinic question to what it gets you.","pairs":[{"left":"\"Is this kept confidential?\"","right":"Clarity on your privacy"},{"left":"\"What are my options?\"","right":"The full method picture"},{"left":"\"Where do I get this?\"","right":"A real access point"},{"left":"\"Can you explain how it works?\"","right":"Accurate understanding"},{"left":"\"Is this routine to ask?\"","right":"Reassurance it's normal"}],"relearn":"Plain questions get you privacy, options, access and understanding.","persona":"any","source":"asking well"},
  {"id":"mc-915","cat":"access-and-rights","type":"match","hook":"Match the situation to the right first step.","pairs":[{"left":"Need EC after a split condom","right":"Pharmacy, soon"},{"left":"Want to compare methods","right":"A doctor or AFHC clinic"},{"left":"An adult is exploiting you","right":"Tell a trusted adult / Childline 1098"},{"left":"Unsure if you're even allowed to ask","right":"Adolescent-friendly services"},{"left":"A friend needs the same info","right":"Point them to a clinic"}],"relearn":"Each situation has a clear, India-grounded first step.","persona":"Counsellor","source":"first steps"},
  {"id":"mc-916","cat":"access-and-rights","type":"match","hook":"Match the worry to the reassuring fact.","pairs":[{"left":"\"They'll judge me\"","right":"Clinicians inform, not judge"},{"left":"\"They'll tell my parents\"","right":"The service is confidential"},{"left":"\"I'm too young to ask\"","right":"Services exist for your age"},{"left":"\"I need permission first\"","right":"No permission needed for info"},{"left":"\"It's weird to ask\"","right":"Asking is routine care"}],"relearn":"Common worries each meet a calm, true fact about your rights.","persona":"Sneha","source":"myth-reassurance"},
  {"id":"mc-917","cat":"access-and-rights","type":"match","hook":"Match who helps with what.","pairs":[{"left":"A pharmacist","right":"Condoms and EC over the counter"},{"left":"A doctor","right":"Prescriptions and method advice"},{"left":"An AFHC counsellor","right":"Confidential SRH counselling"},{"left":"A trusted adult","right":"Support if you're pressured"},{"left":"Childline","right":"Help in a coercion crisis"}],"relearn":"Pharmacist, doctor, counsellor, trusted adult, Childline each have a role.","persona":"any","source":"who helps"},
  {"id":"mc-918","cat":"access-and-rights","type":"match","hook":"Match the right to what it protects you from.","pairs":[{"left":"Right to confidential care","right":"Being exposed without consent"},{"left":"Right to accurate information","right":"Being misled by rumour"},{"left":"Right to decide freely","right":"Being pressured into a choice"},{"left":"Right to safety","right":"Coercion and exploitation"},{"left":"Right to ask","right":"Staying unnecessarily in the dark"}],"relearn":"Each right shields you from a specific harm: exposure, rumour, pressure, coercion.","persona":"any","source":"rights as protection"},
  {"id":"mc-919","cat":"access-and-rights","type":"match","hook":"Match the assertive opener to the moment it fits.","pairs":[{"left":"\"I'd like to ask about my options.\"","right":"Starting a clinic visit"},{"left":"\"Does this stay private?\"","right":"Before you share details"},{"left":"\"Where can I get this?\"","right":"Finding an access point"},{"left":"\"I'm not comfortable, please stop.\"","right":"Facing pressure"},{"left":"\"Can you help me find a clinic?\"","right":"Asking a trusted adult"}],"relearn":"The right opener fits the moment: visiting, sharing, locating, or refusing.","persona":"Arjun","source":"scripts"},
  {"id":"mc-920","cat":"access-and-rights","type":"role-play","hook":"You want to start a clinic visit but your nerves are loud.","setup":"Keep it simple and direct. Say:","yourLine":[{"text":"\"I'd like to talk about my contraception options, privately. Can you help?\"","best":true},{"text":"Mumble that you're fine and edge toward the door"}],"relearn":"A simple, direct ask is all it takes to start; clinicians are there to help.","persona":"Vijay","source":"self-advocacy"},
  {"id":"mc-921","cat":"access-and-rights","type":"role-play","hook":"You want to confirm the visit is confidential before you open up.","setup":"Ask plainly, first. Say:","yourLine":[{"text":"\"Before we start, is everything I share here kept confidential?\"","best":true},{"text":"Stay quiet and just hope it stays private"}],"relearn":"Ask what stays private before you share; they'll explain, including the one legal limit.","persona":"any","source":"confidentiality"},
  {"id":"mc-922","cat":"access-and-rights","type":"role-play","hook":"A friend doesn't know confidential services exist. Point them the right way.","setup":"Share what you know, plainly. Say:","yourLine":[{"text":"\"There are adolescent-friendly clinics for this, confidential, and a doctor can help too.\"","best":true},{"text":"\"No idea, you're on your own with that.\""}],"relearn":"Knowing services exist lets you guide a friend to confidential help.","persona":"Sneha","source":"peer support"},
  {"id":"mc-923","cat":"access-and-rights","type":"role-play","hook":"You need to ask the pharmacist for emergency contraception.","setup":"Ask it plainly; they handle it often. Say:","yourLine":[{"text":"\"I'd like emergency contraception, please. Can you tell me how to take it?\"","best":true},{"text":"Hover, lose your nerve, and buy something else"}],"relearn":"Asking a pharmacist for EC plainly is a routine, valid request.","persona":"any","source":"pharmacy"},
  {"id":"mc-924","cat":"access-and-rights","type":"role-play","hook":"An adult is pressuring you and you need to name it to a trusted teacher.","setup":"Say it clearly to someone you trust. Say:","yourLine":[{"text":"\"An older person is pressuring me into something I don't want. I need help.\"","best":true},{"text":"Change the subject and carry it alone"}],"relearn":"Naming the pressure to a trusted adult is how you get protected.","persona":"Counsellor","source":"safeguarding"},
  {"id":"mc-925","cat":"access-and-rights","type":"role-play","hook":"You want to ask a question you find embarrassing without chickening out.","setup":"Name the awkwardness and ask anyway. Say:","yourLine":[{"text":"\"This feels awkward to ask, but I really want to understand my options.\"","best":true},{"text":"Decide it's too embarrassing and leave it"}],"relearn":"Naming the awkwardness and asking anyway gets you the answers.","persona":"Arjun","source":"clinician communication"},
  {"id":"mc-926","cat":"access-and-rights","type":"role-play","hook":"A receptionist asks why you're there and you freeze.","setup":"Keep it brief and unbothered. Say:","yourLine":[{"text":"\"I have a health question I'd like to discuss with the clinician.\"","best":true},{"text":"Go red and say you'll come back another time"}],"relearn":"A brief, calm reason is all a receptionist needs; you owe no detail.","persona":"any","source":"access nerves"},
  {"id":"mc-927","cat":"access-and-rights","type":"role-play","hook":"You want to ask a doctor whether what you discuss reaches your family.","setup":"Ask the privacy question directly. Say:","yourLine":[{"text":"\"Will anything I tell you today be shared with my family?\"","best":true},{"text":"Wonder silently and never find out"}],"relearn":"You can ask a doctor directly who your information will and won't reach.","persona":"any","source":"confidentiality"},
  {"id":"mc-928","cat":"access-and-rights","type":"role-play","hook":"A friend is too scared to call for help about an exploitative adult.","setup":"Offer to do it with them. Say:","yourLine":[{"text":"\"You're not alone in this. Let's call Childline 1098 together right now.\"","best":true},{"text":"\"Maybe it'll sort itself out, don't worry.\""}],"relearn":"Offering to reach Childline 1098 together helps a scared friend act.","persona":"any","source":"peer safeguarding"},
  {"id":"mc-929","cat":"access-and-rights","type":"role-play","hook":"You want to book a clinic visit but worry about being asked your age.","setup":"State your need calmly; your age is fine. Say:","yourLine":[{"text":"\"I'd like to see someone about contraception. These services are for my age, right?\"","best":true},{"text":"Hang up before anyone answers"}],"relearn":"Adolescent-friendly services are for your age; you can say so plainly.","persona":"Vijay","source":"access for adolescents"},
  {"id":"mc-930","cat":"access-and-rights","type":"role-play","hook":"A clinician starts to rush you and you still have questions.","setup":"Hold your space, politely. Say:","yourLine":[{"text":"\"Before I go, I have two more questions I'd really like answered.\"","best":true},{"text":"Nod and leave with your questions unasked"}],"relearn":"It's your visit; you can politely ask for the time to finish your questions.","persona":"any","source":"self-advocacy"},
  {"id":"mc-931","cat":"access-and-rights","type":"role-play","hook":"You're guiding a nervous friend to actually walk into a clinic.","setup":"Reassure and stay with them. Say:","yourLine":[{"text":"\"I'll come with you. They do this every day, and they'll explain what stays private.\"","best":true},{"text":"\"You should probably just figure it out yourself.\""}],"relearn":"Going with a friend and naming the privacy makes the first visit doable.","persona":"Sneha","source":"peer support"},
  {"id":"mc-932","cat":"access-and-rights","type":"strike-rewrite","hook":"\"You need a parent's permission for any contraception information.\"","myth":{"un":"You can't get contraception information without a parent's permission.","re":"Adolescent-friendly services offer confidential information and counselling.","why":"Confidentiality is a core part of how these services work."},"relearn":"Confidential adolescent services exist; you can seek information privately.","persona":"any","source":"confidentiality (RKSK)"},
  {"id":"mc-933","cat":"access-and-rights","type":"strike-rewrite","hook":"\"A clinic will tell your parents everything you say.\"","myth":{"un":"A clinic will report everything you say to your parents.","re":"Confidentiality is part of adolescent-friendly care; you can ask how it works.","why":"Privacy is what lets young people seek help at all."},"relearn":"Adolescent care is confidential; you can ask how your privacy is handled.","persona":"Arjun","source":"confidentiality"},
  {"id":"mc-934","cat":"access-and-rights","type":"strike-rewrite","hook":"\"Asking a clinician about contraception means they'll judge you.\"","myth":{"un":"A clinician will judge you for asking about contraception.","re":"Clinicians are there to inform and help; asking is routine care.","why":"This is exactly the kind of question services are for."},"relearn":"Clinicians help, not judge; asking is normal, smart self-care.","persona":"any","source":"non-judgment"},
  {"id":"mc-935","cat":"access-and-rights","type":"strike-rewrite","hook":"\"You're too young to be allowed to ask about any of this.\"","myth":{"un":"You're too young to be allowed to ask about contraception.","re":"Adolescent-friendly services exist precisely for young people your age.","why":"They were created so under-18s can get supportive guidance."},"relearn":"Adolescent-friendly services are made for your age; you're allowed to ask.","persona":"Vijay","source":"access for adolescents"},
  {"id":"mc-936","cat":"access-and-rights","type":"strike-rewrite","hook":"\"If someone pressures you into sex, you brought it on yourself.\"","myth":{"un":"If an adult pressures you into sex, it's somehow your fault.","re":"Coercion or exploitation is never your fault; it's a safeguarding matter.","why":"Responsibility sits with the person applying the pressure."},"relearn":"Coercion is never your fault; tell a trusted adult or Childline 1098.","persona":"Counsellor","source":"safeguarding"},
  {"id":"mc-937","cat":"access-and-rights","type":"strike-rewrite","hook":"\"Knowing where to go doesn't really matter if you know the facts.\"","myth":{"un":"Knowing the facts is enough; where to go doesn't matter.","re":"Knowing the place and the words to use is part of the right itself.","why":"Information only protects when you can act on it."},"relearn":"Knowing where to go and what to say turns facts into real protection.","persona":"any","source":"access (knowing where)"},
  {"id":"mc-938","cat":"access-and-rights","type":"strike-rewrite","hook":"\"Confidential teen clinics are made up; no such thing exists in India.\"","myth":{"un":"Confidential adolescent clinics don't really exist in India.","re":"Adolescent-Friendly Health Clinics (Ujala) offer confidential SRH care.","why":"They're a real public service set up for young people."},"relearn":"AFHC / Ujala clinics are real and confidential SRH services in India.","persona":"any","source":"AFHC reality"},
  {"id":"mc-939","cat":"access-and-rights","type":"strike-rewrite","hook":"\"You should only see a clinic once there's already a problem.\"","myth":{"un":"You should only go to a clinic once something has gone wrong.","re":"Getting informed early is exactly what these services are for.","why":"Deciding from facts beforehand beats reacting to a scare."},"relearn":"You can use services to get informed in advance, not only in a crisis.","persona":"any","source":"access timing"},
  {"id":"mc-940","cat":"access-and-rights","type":"sort","hook":"Sort: a safe, real way to access care, or not?","items":[{"id":"a","text":"An AFHC / Ujala clinic"},{"id":"b","text":"A licensed doctor"},{"id":"c","text":"An unverified online 'cure'"},{"id":"d","text":"A pharmacy for condoms"},{"id":"e","text":"A stranger selling 'pills' on chat"},{"id":"f","text":"A trusted adult's guidance"}],"bins":[{"id":"safe","label":"Safe / real","valence":"pos"},{"id":"no","label":"Not safe","valence":"neg"}],"key":{"a":"safe","b":"safe","c":"no","d":"safe","e":"no","f":"safe"},"relearn":"Clinics, doctors, pharmacies and trusted adults are safe; online 'cures' and chat sellers aren't.","persona":"any","source":"safe access"},
  {"id":"mc-941","cat":"access-and-rights","type":"sort","hook":"Sort: part of your rights, or not?","items":[{"id":"a","text":"Confidential care"},{"id":"b","text":"Deciding whether and when"},{"id":"c","text":"Being coerced into sex"},{"id":"d","text":"Accurate information"},{"id":"e","text":"Being shamed for asking"},{"id":"f","text":"Taking your own time"}],"bins":[{"id":"right","label":"Your right","valence":"pos"},{"id":"no","label":"A violation","valence":"neg"}],"key":{"a":"right","b":"right","c":"no","d":"right","e":"no","f":"right"},"relearn":"Confidential care, free choice, accurate info and your own pace are rights; coercion and shaming aren't.","persona":"any","source":"rights"},
  {"id":"mc-942","cat":"access-and-rights","type":"sort","hook":"Sort: where do you go for each?","items":[{"id":"a","text":"Condoms"},{"id":"b","text":"Emergency contraception"},{"id":"c","text":"A pill prescription"},{"id":"d","text":"Confidential counselling"},{"id":"e","text":"Method comparison advice"},{"id":"f","text":"Help with an exploitative adult"}],"bins":[{"id":"pharm","label":"Pharmacy","valence":"neutral"},{"id":"clinic","label":"Doctor / AFHC clinic","valence":"neutral"},{"id":"line","label":"Trusted adult / Childline","valence":"tell"}],"key":{"a":"pharm","b":"pharm","c":"clinic","d":"clinic","e":"clinic","f":"line"},"relearn":"Pharmacy for condoms/EC, clinic for prescriptions and advice, Childline for coercion.","persona":"Counsellor","source":"access routes"},
  {"id":"mc-943","cat":"access-and-rights","type":"sort","hook":"Sort: respects your confidentiality, or breaks it?","items":[{"id":"a","text":"A clinician asking before sharing anything"},{"id":"b","text":"A service that explains its privacy"},{"id":"c","text":"Someone posting your visit online"},{"id":"d","text":"A counsellor keeping your session private"},{"id":"e","text":"A clinic gossiping about patients"},{"id":"f","text":"Being told who your info reaches"}],"bins":[{"id":"keeps","label":"Respects privacy","valence":"pos"},{"id":"breaks","label":"Breaks privacy","valence":"neg"}],"key":{"a":"keeps","b":"keeps","c":"breaks","d":"keeps","e":"breaks","f":"keeps"},"relearn":"Asking first, explaining privacy and keeping sessions private respect you; gossip and exposure don't.","persona":"any","source":"confidentiality"},
  {"id":"mc-944","cat":"access-and-rights","type":"sort","hook":"Sort: a green light to act on, or a red flag to step back from?","items":[{"id":"a","text":"A clinic that answers your questions"},{"id":"b","text":"An adult pushing you to keep a secret"},{"id":"c","text":"A pharmacist explaining how EC works"},{"id":"d","text":"A 'cure' that demands money up front"},{"id":"e","text":"A counsellor offering confidential help"},{"id":"f","text":"Someone saying real clinics will betray you"}],"bins":[{"id":"go","label":"Green light","valence":"pos"},{"id":"stop","label":"Red flag","valence":"uhoh"}],"key":{"a":"go","b":"stop","c":"go","d":"stop","e":"go","f":"stop"},"relearn":"Clinics and pharmacists that explain things are green lights; secrecy-pushers and paid 'cures' are red flags.","persona":"any","source":"access discernment"},
  {"id":"mc-945","cat":"access-and-rights","type":"sort","hook":"Sort: a real right, or a myth about your rights?","items":[{"id":"a","text":"You can ask without a parent's permission"},{"id":"b","text":"Clinics must report you to family"},{"id":"c","text":"Adolescent services are confidential"},{"id":"d","text":"You're too young to be allowed to ask"},{"id":"e","text":"Asking is routine care, not shameful"},{"id":"f","text":"A doctor will always judge you"}],"bins":[{"id":"true","label":"True right","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"},"relearn":"Asking freely, private care and routine checks are real; 'clinics tell your family' and 'too young to ask' are myths.","persona":"Sneha","source":"rights myths"},
  {"id":"mc-946","cat":"access-and-rights","type":"sort","hook":"Sort: who handles which request?","items":[{"id":"a","text":"Buying condoms over the counter"},{"id":"b","text":"Getting a method prescribed"},{"id":"c","text":"Confidential SRH counselling"},{"id":"d","text":"EC the morning after"},{"id":"e","text":"Comparing all the methods"},{"id":"f","text":"Support when pressured by an adult"}],"bins":[{"id":"pharm","label":"Pharmacy","valence":"neutral"},{"id":"clinic","label":"Doctor / AFHC","valence":"neutral"},{"id":"adult","label":"Trusted adult / Childline","valence":"tell"}],"key":{"a":"pharm","b":"clinic","c":"clinic","d":"pharm","e":"clinic","f":"adult"},"relearn":"Pharmacy, doctor/AFHC, or a trusted adult/Childline each handle different needs.","persona":"any","source":"who handles what"},
  {"id":"mc-947","cat":"access-and-rights","type":"sort","hook":"Sort: makes asking easier, or shuts it down?","items":[{"id":"a","text":"A service that promises confidentiality"},{"id":"b","text":"A clinician who answers plainly"},{"id":"c","text":"A friend who mocks you for asking"},{"id":"d","text":"Knowing it's routine to ask"},{"id":"e","text":"A rumour that clinics betray you"},{"id":"f","text":"Being told you're too young to ask"}],"bins":[{"id":"helps","label":"Makes it easier","valence":"pos"},{"id":"blocks","label":"Shuts it down","valence":"neg"}],"key":{"a":"helps","b":"helps","c":"blocks","d":"helps","e":"blocks","f":"blocks"},"relearn":"Confidentiality and plain answers open the door; mockery and rumour slam it shut.","persona":"any","source":"access enablers"},
  {"id":"mc-948","cat":"access-and-rights","type":"reflect","hook":"Lensy: knowing where to go and the words to use is part of your right. Feel that's yours?","prompt":"What do you think?","options":["Yes, it's mine","I know where to go now","Good to know"],"affirm":"Knowing the services and the words turns information into something you can actually use.","relearn":"Knowing where to access services turns knowledge into real protection.","persona":"any","source":"access"},
  {"id":"mc-949","cat":"access-and-rights","type":"reflect","hook":"Lensy: which access fact feels most useful to carry with you?","prompt":"Pick what matters to you.","options":["Clinics are confidential","I don't need permission to ask","Help exists if I'm pressured","Asking is routine care"],"affirm":"Whichever you carry, it's a real right that's there whenever you need it.","relearn":"Confidentiality, no-permission info, safeguarding and routine care are all yours.","persona":"any","source":"rights"},
  {"id":"mc-950","cat":"access-and-rights","type":"reflect","hook":"Lensy: imagine you needed care tomorrow. Where would you start?","prompt":"What's your first move?","options":["An AFHC / Ujala clinic","Ask a doctor","A pharmacy","Ask a trusted adult to help"],"affirm":"Any of these is a real, valid first step; you already know how to begin.","relearn":"You have several real first steps: clinic, doctor, pharmacy, or trusted adult.","persona":"any","source":"access"},
  {"id":"mc-951","cat":"access-and-rights","type":"reflect","hook":"Lensy: how does it feel to know confidentiality is part of the service?","prompt":"What do you think?","options":["Reassuring","Makes asking easier","I'd still ask to confirm"],"affirm":"Knowing your privacy is built in, and that you can confirm it, makes asking far easier.","relearn":"Confidentiality is built into adolescent services; you can also confirm it.","persona":"any","source":"confidentiality"},
  {"id":"mc-952","cat":"access-and-rights","type":"reflect","hook":"Lensy: if a friend was scared to seek help, what would you offer them?","prompt":"Pick your move.","options":["Go with them","Share where to go","Just listen first","Help them call for support"],"affirm":"Any of these is real support; being the person who helps a friend act matters.","relearn":"Going along, sharing routes, listening or helping call are all real support.","persona":"any","source":"peer support"},
  {"id":"mc-953","cat":"access-and-rights","type":"reflect","hook":"Lensy: knowing exploitation is never your fault, who could you tell if you needed to?","prompt":"Pick who you'd reach.","options":["A trusted teacher","A trusted family member","Childline 1098","A doctor or counsellor"],"affirm":"Whoever you'd reach, naming it is the brave, right move, and never your fault.","relearn":"You can tell a trusted adult, doctor or Childline; exploitation is never your fault.","persona":"any","source":"safeguarding"},
  {"id":"mc-954","cat":"access-and-rights","type":"reflect","hook":"Lensy: what would make a clinic feel safe enough for you to ask freely?","prompt":"Pick what matters most.","options":["Clear confidentiality","No judgement","Plain answers","Time to ask everything"],"affirm":"You deserve all of these, and adolescent-friendly services aim to give them.","relearn":"You can expect confidentiality, no judgement, plain answers and time to ask.","persona":"any","source":"what good care feels like"},
  {"id":"mc-955","cat":"access-and-rights","type":"spot","hook":"Spot the two red flags in how someone is 'offering help'.","scene":[{"id":"a","text":"\"The clinic is free and keeps it private.\"","trick":false},{"id":"b","text":"\"Don't tell anyone we talked, keep it our secret.\"","trick":true},{"id":"c","text":"\"A doctor can explain your options.\"","trick":false},{"id":"d","text":"\"Pay me first and I'll get you 'pills'.\"","trick":true},{"id":"e","text":"\"You can ask a trusted adult too.\"","trick":false}],"why":"Demanding secrecy and money up front are the red flags; real services are private and don't work like that.","relearn":"Secrecy-pushing and pay-first 'pills' are red flags; real help is open and confidential.","persona":"any","source":"spot bad access"},
  {"id":"mc-956","cat":"access-and-rights","type":"spot","hook":"Spot the two lines that are myths about your rights.","scene":[{"id":"a","text":"You can ask without a parent's permission.","trick":false},{"id":"b","text":"Clinics are required to report you to your family.","trick":true},{"id":"c","text":"Adolescent services are confidential.","trick":false},{"id":"d","text":"You're too young to be allowed to ask anything.","trick":true},{"id":"e","text":"Asking a clinician is routine care.","trick":false}],"why":"Clinics don't tell family, and you're never too young to ask.","relearn":"Clinics don't tell your family. But if they learn someone under 18 is having sex or being abused, the law says they tell the police.","persona":"any","source":"spot rights myths"},
  {"id":"mc-957","cat":"access-and-rights","type":"spot","hook":"Spot the two lines that pressure or trap you (not real help).","scene":[{"id":"a","text":"\"Take your time deciding; there's no rush.\"","trick":false},{"id":"b","text":"\"If you tell anyone, you'll get in trouble.\"","trick":true},{"id":"c","text":"\"You can bring a trusted adult along.\"","trick":false},{"id":"d","text":"\"A real relationship means keeping it hidden.\"","trick":true},{"id":"e","text":"\"The counsellor won't judge you.\"","trick":false}],"why":"Threats about telling and 'keep it hidden' are coercion; the others respect you.","relearn":"Threats for telling and 'keep it hidden' are traps, not help; real support is open.","persona":"any","source":"spot coercion"},
  {"id":"mc-958","cat":"access-and-rights","type":"spot","hook":"Spot the two false 'facts' a rumour is spreading about clinics.","scene":[{"id":"a","text":"Adolescent clinics offer confidential counselling.","trick":false},{"id":"b","text":"Clinics charge huge fees and shame you.","trick":true},{"id":"c","text":"A pharmacist can give you EC.","trick":false},{"id":"d","text":"You must bring a parent to even enter.","trick":true},{"id":"e","text":"Asking about options is routine.","trick":false}],"why":"The 'huge fees and shame' and 'must bring a parent' lines are false; the rest are true.","relearn":"Spot the rumours: clinics aren't about fees and shame, and you needn't bring a parent.","persona":"Sneha","source":"spot clinic rumours"},
  {"id":"mc-959","cat":"access-and-rights","type":"spot","hook":"Spot the two moves that undermine your right to decide.","scene":[{"id":"a","text":"A clinician laying out all your options.","trick":false},{"id":"b","text":"Someone deciding for you 'to save trouble'.","trick":true},{"id":"c","text":"Being given time to think.","trick":false},{"id":"d","text":"Being rushed to 'just decide now'.","trick":true},{"id":"e","text":"Your questions being answered plainly.","trick":false}],"why":"Deciding for you and rushing you both strip your choice; the others support it.","relearn":"Spot the choice-strippers: deciding for you and rushing you undermine your right.","persona":"any","source":"spot autonomy"},
  {"id":"mc-960","cat":"access-and-rights","type":"spot","hook":"Spot the two unsafe 'access points' hiding among the real ones.","scene":[{"id":"a","text":"An AFHC / Ujala clinic","trick":false},{"id":"b","text":"A stranger in a chat selling 'pills'","trick":true},{"id":"c","text":"A licensed pharmacy","trick":false},{"id":"d","text":"An unverified miracle 'cure' ad","trick":true},{"id":"e","text":"A registered doctor","trick":false}],"why":"The chat seller and the miracle 'cure' are unsafe; clinics, pharmacies and doctors are real.","relearn":"Spot the fakes: chat 'pill' sellers and miracle 'cures' aren't real access points.","persona":"any","source":"spot fake access"},
  {"id":"mc-961","cat":"access-and-rights","type":"spot","hook":"Spot the two lines that wrongly block you from asking for help.","scene":[{"id":"a","text":"\"Adolescent services are made for your age.\"","trick":false},{"id":"b","text":"\"You'll be punished just for asking.\"","trick":true},{"id":"c","text":"\"A counsellor keeps it confidential.\"","trick":false},{"id":"d","text":"\"It's shameful to even want this info.\"","trick":true},{"id":"e","text":"\"You can ask a trusted adult to help.\"","trick":false}],"why":"'You'll be punished' and 'it's shameful' are false barriers; the rest are real and supportive.","relearn":"Spot the false barriers: you won't be punished for asking, and it's not shameful.","persona":"any","source":"spot false barriers"},
  {"id":"mc-962","cat":"access-and-rights","type":"spot","hook":"Spot the two replies that aren't real confidentiality.","scene":[{"id":"a","text":"\"What you share here stays between us.\"","trick":false},{"id":"b","text":"\"I'll just mention it to your cousin.\"","trick":true},{"id":"c","text":"\"You can ask how your privacy works.\"","trick":false},{"id":"d","text":"\"I'll post about your case later.\"","trick":true},{"id":"e","text":"\"Only the care team sees your notes.\"","trick":false}],"why":"Telling your cousin and posting your case break confidentiality; the others honour it.","relearn":"Spot the privacy breaks: passing it to relatives or posting it isn't confidential.","persona":"any","source":"spot privacy breaks"},
  {"id":"mc-990","cat":"decide-it","type":"branch","persona":"Sneha","source":"decision skill / family pressure","relearn":"Ask for time and facts; a real choice isn't made on the spot.","hook":"Decide It. At a wedding, an aunt corners you to 'fix' your marriage this year. You feel rushed.","options":[{"text":"Say you'll decide your own future in your own time, and mean it","consequence":"You hold your timeline calmly.","best":true,"outcome":"own-timeline"},{"text":"Nod and let her start the arrangements","consequence":"Whether and when is your right; you can take the time you need."}],"debrief":"A real choice isn't rushed by someone else's deadline; the timeline is yours."},
  {"id":"mc-991","cat":"decide-it","type":"branch","persona":"Vijay","source":"decision skill / facts first","relearn":"Gather facts from a clinician before deciding, not from a forwarded video.","hook":"Decide It. A WhatsApp forward claims one method is 'dangerous'. You're about to drop it.","options":[{"text":"Check with a doctor or AFHC clinic before you decide","consequence":"Your choice rests on real facts, not a forward.","best":true,"outcome":"informed"},{"text":"Believe the forward and switch blindly","consequence":"Facts come from a clinician and reliable sources, not rumour in a forward."}],"debrief":"Gather the facts from a real source first; a forward is not evidence."},
  {"id":"mc-992","cat":"decide-it","type":"branch","persona":"any","source":"decision skill / values","relearn":"List what actually matters to you, then choose; your values are the compass.","hook":"Decide It. Two valid options feel equal and you're stuck. How do you break the tie?","options":[{"text":"Weigh each against what matters most to you, then choose","consequence":"Your own values settle the tie.","best":true,"outcome":"values"},{"text":"Flip a coin and forget about it","consequence":"When options are both fine, your own values are how you choose between them."}],"debrief":"Check your values: the choice that fits them best is yours to make."},
  {"id":"mc-993","cat":"decide-it","type":"branch","persona":"any","source":"decision skill / own it","relearn":"Owning a choice means standing by your reasons, even if it's unpopular.","hook":"Decide It. You've decided to wait. A friend mocks it. Do you cave?","options":[{"text":"Stand by your reasoned choice; you don't owe anyone an apology","consequence":"You own a choice you made for good reasons.","best":true,"outcome":"owned"},{"text":"Change it just to stop the teasing","consequence":"Owning your choice means holding it when it's yours and reasoned, not unpopular."}],"debrief":"A choice you reasoned and own holds up; teasing isn't a reason to drop it."},
  {"id":"mc-994","cat":"decide-it","type":"branch","persona":"Arjun","source":"decision skill / consent floor","relearn":"Consent is non-negotiable; check the other person genuinely wants this too.","hook":"Decide It. You want to, but you're not sure your partner truly does. What now?","options":[{"text":"Pause and check they genuinely want this, freely","consequence":"You keep consent as the non-negotiable floor.","best":true,"outcome":"consent"},{"text":"Assume it's fine and carry on","consequence":"Consent is non-negotiable; a real choice checks the other person wants it too."}],"debrief":"Beyond your own values, consent is the floor: check it's a genuine, free yes."},
  {"id":"mc-995","cat":"decide-it","type":"branch","persona":"any","source":"decision skill / EC window","relearn":"After unprotected sex, EC works best within 5 days; act in the window.","hook":"Decide It. You had unprotected sex two days ago and don't want a pregnancy now.","options":[{"text":"Get emergency contraception soon, it works best within 5 days","consequence":"You act inside the window EC needs.","best":true,"outcome":"ec"},{"text":"Wait and see if a period comes","consequence":"After unprotected sex, EC within 5 days is the backup; sooner is better."}],"debrief":"EC is the informed backup after unprotected sex; the 5-day window matters."},
  {"id":"mc-996","cat":"decide-it","type":"branch","persona":"Sneha","source":"decision skill / re-decide for self","relearn":"If a choice is mostly to please someone, pause and re-decide from your values.","hook":"Decide It. You realise you said yes to a plan mainly so a partner wouldn't sulk.","options":[{"text":"Pause and re-decide it from what you actually want","consequence":"You take the choice back as your own.","best":true,"outcome":"self-owned"},{"text":"Go through with it to keep them happy","consequence":"Choosing mainly to please someone isn't your choice; pause and re-decide."}],"debrief":"If you're deciding to avoid someone's mood, re-decide from your own values."},
  {"id":"mc-997","cat":"decide-it","type":"branch","persona":"Vijay","source":"decision skill / method fit","relearn":"Fit the method to your life; if one doesn't suit you, ask about another.","hook":"Decide It. The pill's daily timing keeps clashing with your shifts. What's the move?","options":[{"text":"Ask a clinician about a method that needs no daily action","consequence":"You match the method to how you actually live.","best":true,"outcome":"fit"},{"text":"Keep missing doses and hope","consequence":"The best method is the one you'll use consistently; fit it to your real life."}],"debrief":"Forgetting doses is a signal to fit the method to your life, not blame yourself."},
  {"id":"mc-998","cat":"decide-it","type":"branch","persona":"Counsellor","source":"decision skill / POCSO","relearn":"Under 18 with a much older person pushing this: step back, tell a trusted adult.","hook":"Decide It. You're 16 and an adult keeps pressuring you toward a sexual relationship.","options":[{"text":"Step back and tell a trusted adult; the law protects you here","consequence":"You stay safe and supported.","best":true,"outcome":"protected"},{"text":"Go along to feel grown-up","consequence":"Under 18, the age of consent (18) protects you; an older person's pressure is a red flag."}],"debrief":"Under 18 plus an older person's pressure routes to safeguarding, never your fault."},
  {"id":"mc-999","cat":"decide-it","type":"branch","persona":"any","source":"decision skill / dual protection","relearn":"For both pregnancy and STIs, condoms are the dual-protection choice.","hook":"Decide It. You want to avoid both an STI and a pregnancy. Which plan covers both?","options":[{"text":"Use condoms, optionally plus another method for extra cover","consequence":"You get STI protection and strong pregnancy cover.","best":true,"outcome":"dual"},{"text":"Rely on the pill alone","consequence":"Only condoms cover STIs; pair them with another method for extra pregnancy cover."}],"debrief":"Both kinds of protection means condoms in the plan; the pill alone won't do STIs."},
  {"id":"mc-1000","cat":"decide-it","type":"branch","persona":"Sneha","source":"decision skill / not rushed","relearn":"A real choice isn't rushed; 'decide right now' pressure is a reason to slow down.","hook":"Decide It. A partner says 'decide tonight or we're over'. You feel cornered.","options":[{"text":"Tell them a real choice isn't rushed; you'll decide on your own time","consequence":"You refuse to be stampeded.","best":true,"outcome":"unrushed"},{"text":"Decide on the spot to keep them","consequence":"'Decide right now' is pressure; a real choice gets the time it needs."}],"debrief":"Ultimatums rush you; you're allowed the time a real decision needs."},
  {"id":"mc-1001","cat":"decide-it","type":"branch","persona":"any","source":"decision skill / boundary not distrust","relearn":"Protection is about health, not trust; keep the boundary.","hook":"Decide It. A partner says wanting a condom 'means you think they're dirty'.","options":[{"text":"Keep the boundary; protection is about health, not trust","consequence":"You hold a fair, health-smart standard.","best":true,"outcome":"boundary"},{"text":"Drop it so they're not offended","consequence":"'It means you don't trust me' is manipulation; protection is health, not an insult."}],"debrief":"Protection isn't distrust; a caring partner respects the boundary, you keep it."},
  {"id":"mc-1002","cat":"decide-it","type":"branch","persona":"Arjun","source":"decision skill / inclusive facts","relearn":"Get facts that fit you from a clinician; don't decide from a stereotype.","hook":"Decide It. Online posts give conflicting 'rules' that don't seem to fit your life.","options":[{"text":"Ask a clinician for facts that actually fit your situation","consequence":"Your choice rests on facts that apply to you.","best":true,"outcome":"informed"},{"text":"Pick whichever post sounds loudest","consequence":"Reliable facts come from a clinician, fitted to you, not the loudest post online."}],"debrief":"Gather facts that fit your real situation; a stereotype online isn't your fact base."},
  {"id":"mc-1003","cat":"decide-it","type":"branch","persona":"Vijay","source":"decision skill / law floor","relearn":"Beyond your values, safety and the law always hold; they're not negotiable.","hook":"Decide It. A choice feels tempting but would cross a clear safety line. Now what?","options":[{"text":"Don't cross it; safety and the law are the non-negotiable floor","consequence":"You keep the line that protects you.","best":true,"outcome":"non-negotiables"},{"text":"Risk it because you want to","consequence":"Beyond personal values, consent, safety and the law always hold."}],"debrief":"Wants vary, but safety and the law are the floor under every choice."},
  {"id":"mc-1004","cat":"decide-it","type":"branch","persona":"any","source":"decision skill / spacing","relearn":"Spacing is a real, health-relevant choice; plan it, don't leave it to chance.","hook":"Decide It. You and a partner have one child and are deciding about a second.","options":[{"text":"Talk it through and plan the timing together","consequence":"You treat spacing as a real, shared choice.","best":true,"outcome":"planned"},{"text":"Leave it entirely to chance","consequence":"Spacing supports the health of parent and child; it's part of planning, not luck."}],"debrief":"When and how far apart is a genuine choice; plan it together."},
  {"id":"mc-1005","cat":"decide-it","type":"branch","persona":"Sneha","source":"decision skill / career fork","relearn":"Family planning is a tool for the life you want; your education is yours to build.","hook":"Decide It. You got a college seat far away; relatives say marry first instead.","options":[{"text":"Take the seat; planning is a tool for the future you want","consequence":"You build the future you chose.","best":true,"outcome":"autonomy"},{"text":"Skip college because they expect marriage","consequence":"Your education and future are yours to build; family planning serves that."}],"debrief":"Family input is fine, but the choice between college and marriage is yours."},
  {"id":"mc-1006","cat":"decide-it","type":"branch","persona":"any","source":"decision skill / facts vs fear","relearn":"Decide from facts, not from a scary rumour designed to frighten you.","hook":"Decide It. A rumour says a method 'causes cancer'. It's frightening you off it.","options":[{"text":"Check the claim with a doctor before you let fear decide","consequence":"Facts, not fear, settle it.","best":true,"outcome":"informed"},{"text":"Drop the method out of fear alone","consequence":"Decisions rest on verified facts from a clinician, not a fear-driven rumour."}],"debrief":"Fear-based rumours aren't facts; verify with a doctor, then decide."},
  {"id":"mc-1007","cat":"decide-it","type":"branch","persona":"Arjun","source":"decision skill / own it after","relearn":"Owning a choice includes handling the outcome calmly; that's part of deciding well.","hook":"Decide It. You made a careful choice, but it didn't go to plan. How do you respond?","options":[{"text":"Own it, learn what you can, and adjust the next step","consequence":"You stay the author of your choices.","best":true,"outcome":"owned"},{"text":"Decide it was all someone else's fault","consequence":"Owning a choice means standing by it and adjusting, not pinning it on others."}],"debrief":"Deciding well includes owning the outcome and adjusting; that's the skill."},
  {"id":"mc-1008","cat":"decide-it","type":"branch","persona":"Vijay","source":"decision skill / access route","relearn":"Knowing where to go is part of deciding; pick the real service, not a quick fix.","hook":"Decide It. You've decided you want a method. Where do you actually go for it?","options":[{"text":"Go to a doctor or AFHC clinic for the right method","consequence":"You act on the choice through a real service.","best":true,"outcome":"access"},{"text":"Order an unverified pill online","consequence":"A decision only protects if you act on it; go to a clinic or doctor, not a quick fix."}],"debrief":"Knowing the real route, a clinic or doctor, turns the choice into action."},
  {"id":"mc-1009","cat":"decide-it","type":"branch","persona":"any","source":"decision skill / no single right","relearn":"Beyond the floor, your reasoned choice is valid even if a friend chose differently.","hook":"Decide It. A friend made the opposite choice and insists theirs is the 'right' one.","options":[{"text":"Respect that both are valid; decide by your own values","consequence":"You keep your choice without judging theirs.","best":true,"outcome":"non-judgmental"},{"text":"Assume one of you must be wrong","consequence":"Beyond consent, safety and law there's no single 'right' choice; both can be valid."}],"debrief":"Different reasoned choices can both be right; yours rests on your values."},
  {"id":"mc-1010","cat":"decide-it","type":"branch","persona":"Sneha","source":"decision skill / privacy","relearn":"You can decide privately; you don't owe everyone an explanation.","hook":"Decide It. People keep demanding to know your reproductive plans. You feel exposed.","options":[{"text":"Keep your choice private; you decide who, if anyone, to tell","consequence":"You hold your privacy as part of the choice.","best":true,"outcome":"private"},{"text":"Explain yourself to everyone who asks","consequence":"Your choice is yours; privacy is part of it, and you decide who to tell."}],"debrief":"You can decide privately; no one is owed your reproductive plans."},
  {"id":"mc-1011","cat":"decide-it","type":"branch","persona":"any","source":"decision skill / delaying is valid","relearn":"Delaying is a full, certain choice; it doesn't need anyone's approval.","hook":"Decide It. You've thought it through and want to wait. You're second-guessing it.","options":[{"text":"Trust your reasoned choice; waiting is valid and the most certain","consequence":"You back your own decision.","best":true,"outcome":"valid"},{"text":"Abandon it because others might judge","consequence":"Delaying is a valid, respected, certain choice; a reasoned decision to wait stands."}],"debrief":"A reasoned choice to wait is fully valid; it needs no one's approval."},
  {"id":"mc-1012","cat":"decide-it","type":"branch","persona":"Counsellor","source":"decision skill / safeguarding","relearn":"If a choice is being forced, it isn't a choice; route coercion to a trusted adult.","hook":"Decide It. Someone is threatening you to get a 'yes'. This isn't a free decision.","options":[{"text":"Tell a trusted adult or doctor; a forced 'yes' isn't a choice","consequence":"You get protection, not pressure.","best":true,"outcome":"protected"},{"text":"Give the 'yes' to make the threat stop","consequence":"A threatened 'yes' is coercion, a child-protection matter; tell a trusted adult."}],"debrief":"Coercion removes choice; route it to a trusted adult or doctor, never your fault."},
  {"id":"mc-1013","cat":"decide-it","type":"branch","persona":"Vijay","source":"decision skill / both partners decide","relearn":"A shared decision is made together; one person can't decide protection for both.","hook":"Decide It. A partner says protection is 'your problem to sort out'. Is it?","options":[{"text":"Say it's a shared decision you make together","consequence":"You keep it a joint, fair choice.","best":true,"outcome":"shared"},{"text":"Accept that it's all on you","consequence":"Protection is something partners agree on together, not one person's burden."}],"debrief":"A real decision here is shared; both of you weigh in and agree."},
  {"id":"mc-1014","cat":"decide-it","type":"branch","persona":"any","source":"decision skill / values over image","relearn":"Decide by your values, not by how a choice looks to others.","hook":"Decide It. You're tempted to choose what looks impressive to friends, not what fits you.","options":[{"text":"Choose what fits your values, not what looks impressive","consequence":"You decide for yourself, not the audience.","best":true,"outcome":"values"},{"text":"Pick the option that looks coolest","consequence":"A values-based choice is reasoned for you, not performed for an image."}],"debrief":"Image isn't a value; decide for your real life, not the audience."},
  {"id":"mc-1015","cat":"decide-it","type":"branch","persona":"Arjun","source":"decision skill / ask without shame","relearn":"Asking is what maturity looks like; gather facts before you decide.","hook":"Decide It. You don't have enough information yet and feel embarrassed to ask.","options":[{"text":"Ask a clinician anyway; you need facts to decide well","consequence":"You get the facts your choice needs.","best":true,"outcome":"informed"},{"text":"Decide blind to avoid the awkwardness","consequence":"Seeking accurate information and asking is exactly what maturity looks like."}],"debrief":"Gather the facts first; asking isn't a weakness, it's how you decide well."},
  {"id":"mc-1016","cat":"decide-it","type":"branch","persona":"Sneha","source":"decision skill / pressure to prove love","relearn":"'If you loved me' is pressure, not a reason; your readiness decides.","hook":"Decide It. A partner frames sex as the only way to 'prove' your love.","options":[{"text":"Name it as pressure; love isn't proven by giving in","consequence":"You keep the choice your own.","best":true,"outcome":"own-pace"},{"text":"Give in to prove yourself","consequence":"'If you loved me you would' is manipulation; readiness is yours, not a test."}],"debrief":"Love isn't a test you pass by giving in; your readiness decides, free of pressure."},
  {"id":"mc-1017","cat":"decide-it","type":"branch","persona":"any","source":"decision skill / one fact changes it","relearn":"A decision can change when a real fact comes in; updating isn't weakness.","hook":"Decide It. New, verified information changes the picture after you'd half-decided.","options":[{"text":"Update your choice to fit the new, verified facts","consequence":"Your decision stays grounded in reality.","best":true,"outcome":"informed"},{"text":"Ignore it because you'd already decided","consequence":"A good decision updates when verified facts change the picture; that's deciding well."}],"debrief":"Updating on real new facts is part of the skill, not a failure of nerve."},
  {"id":"mc-1018","cat":"decide-it","type":"branch","persona":"Vijay","source":"decision skill / cost vs safety","relearn":"Don't trade safety for a cheaper shortcut; real services are worth it.","hook":"Decide It. A friend offers a 'cheaper' unverified method instead of seeing a doctor.","options":[{"text":"Stick with a real method from a clinic or pharmacy","consequence":"You keep safety over a risky shortcut.","best":true,"outcome":"safe"},{"text":"Take the unverified shortcut to save money","consequence":"Safety is non-negotiable; a verified method from a real service beats a risky deal."}],"debrief":"A cheaper unverified shortcut isn't a saving if it isn't safe; use a real service."},
  {"id":"mc-1019","cat":"decide-it","type":"branch","persona":"any","source":"decision skill / consent can change","relearn":"Consent is ongoing; you can change your mind at any point, and so can a partner.","hook":"Decide It. Partway through, you realise you don't want to continue.","options":[{"text":"Stop; consent is ongoing and you can change your mind","consequence":"You keep consent as a live, non-negotiable thing.","best":true,"outcome":"consent"},{"text":"Push through because you'd agreed earlier","consequence":"Consent is ongoing, not a one-time yes; you can stop at any point."}],"debrief":"Changing your mind is your right; consent stays live the whole way through."},
  {"id":"mc-1020","cat":"decide-it","type":"branch","persona":"Counsellor","source":"decision skill / trusted adult","relearn":"When a decision is too big to carry alone, bring in a trusted adult or doctor.","hook":"Decide It. A choice feels too heavy to make entirely by yourself.","options":[{"text":"Talk it through with a trusted adult or doctor first","consequence":"You decide with real support.","best":true,"outcome":"supported"},{"text":"Bottle it up and decide alone under stress","consequence":"Deciding well can include support; a trusted adult or doctor helps you weigh it."}],"debrief":"Some choices are easier with support; a trusted adult or doctor can help you decide."},
  {"id":"mc-1021","cat":"decide-it","type":"branch","persona":"Arjun","source":"decision skill / your timeline","relearn":"Your timeline is yours; 'everyone your age' is pressure, not a fact.","hook":"Decide It. Classmates imply you're 'behind' for not being sexually active.","options":[{"text":"Trust your own timeline; 'everyone' isn't a fact or a reason","consequence":"You decide by your pace, not a scoreboard.","best":true,"outcome":"own-pace"},{"text":"Rush to catch up with them","consequence":"'Everyone your age' is pressure dressed as fact; your timeline is your own."}],"debrief":"There's no scoreboard; your readiness and timeline decide, not classmates."},
  {"id":"mc-1022","cat":"decide-it","type":"reflect","persona":"any","source":"decision skill","relearn":"The four steps, facts, values, free choice, ownership, work for any big decision.","hook":"Lensy: which of the four decision steps feels easiest for you right now?","prompt":"Pick one.","options":["Gathering facts","Knowing my values","Choosing freely","Owning it"],"affirm":"Whichever you picked, naming it is how the skill becomes yours."},
  {"id":"mc-1023","cat":"decide-it","type":"reflect","persona":"Sneha","source":"values","relearn":"Your values are the compass when a choice is genuinely hard.","hook":"Lensy: when a choice is hard, what value do you most lean on?","prompt":"Pick what guides you.","options":["My health","My future goals","Being honest with myself","My peace of mind"],"affirm":"Leaning on a value you name makes a hard choice clearer."},
  {"id":"mc-1024","cat":"decide-it","type":"reflect","persona":"any","source":"decision skill","relearn":"A good decision is one you can stand behind, whatever it is.","hook":"Lensy: a choice you can explain to yourself calmly, does that feel like a good sign?","prompt":"What do you think?","options":["Yes","A good sign","That's the test"],"affirm":"If you can explain it to yourself by your values, you've decided well."},
  {"id":"mc-1025","cat":"decide-it","type":"reflect","persona":"Arjun","source":"autonomy","relearn":"Beyond the non-negotiables, no single 'right' choice exists; yours is valid.","hook":"Lensy: knowing there's no single 'right' answer here, does deciding feel less scary?","prompt":"What do you think?","options":["Yes","Less pressure","It's mine to make"],"affirm":"Without one 'correct' answer to find, you're free to choose by your own values."},
  {"id":"mc-1026","cat":"decide-it","type":"reflect","persona":"any","source":"unrushed choice","relearn":"A real choice isn't rushed; taking time is allowed.","hook":"Lensy: do you give yourself permission to take the time a choice needs?","prompt":"What do you think?","options":["Yes","I'm working on it","I will now"],"affirm":"Time isn't indecision; a real choice deserves the space you give it."},
  {"id":"mc-1027","cat":"decide-it","type":"reflect","persona":"Vijay","source":"facts first","relearn":"Decisions rest on facts from a clinician, not rumour.","hook":"Lensy: where do you most trust to get real facts for a choice like this?","prompt":"Pick your source.","options":["A doctor","An AFHC clinic","A reliable health site","A trusted adult"],"affirm":"Choosing a real, reliable source is the first step of deciding well."},
  {"id":"mc-1028","cat":"decide-it","type":"reflect","persona":"any","source":"self-owned","relearn":"If you're choosing to please someone, pausing to re-decide is healthy.","hook":"Lensy: can you tell the difference between your choice and pleasing someone?","prompt":"What do you think?","options":["Usually","I'm learning to","I'll watch for it"],"affirm":"Noticing whose choice it really is keeps your decisions your own."},
  {"id":"mc-1029","cat":"decide-it","type":"reflect","persona":"Sneha","source":"autonomy / future","relearn":"Your future is yours to shape; these choices are tools for it.","hook":"Lensy: when you picture your future, who's holding the pen?","prompt":"What do you think?","options":["Me","Increasingly me","I want it to be me"],"affirm":"These choices are how you take the pen for the future you want."},
  {"id":"mc-1030","cat":"decide-it","type":"reflect","persona":"any","source":"non-negotiables","relearn":"Consent, safety and the law are the floor under every choice.","hook":"Lensy: the floor here, consent, safety, the law, does that feel steadying?","prompt":"What do you think?","options":["Yes","Steadying","Good to know it holds"],"affirm":"Knowing the floor never moves makes the rest feel safe to decide."},
  {"id":"mc-1031","cat":"decide-it","type":"reflect","persona":"Arjun","source":"maturity","relearn":"Asking and getting informed is what maturity looks like.","hook":"Lensy: does it feel mature, rather than awkward, to ask before deciding?","prompt":"What do you think?","options":["Yes","Reframed it","I'll ask"],"affirm":"Asking before you decide is exactly what real maturity looks like."},
  {"id":"mc-1032","cat":"decide-it","type":"reflect","persona":"any","source":"pressure-free","relearn":"No pressure in any direction, including no pressure to wait or to rush.","hook":"Lensy: a choice made with zero pressure either way, does that sound like real freedom?","prompt":"What do you think?","options":["Yes","Real freedom","That's the goal"],"affirm":"No pressure either way leaves the choice simply, genuinely yours."},
  {"id":"mc-1033","cat":"decide-it","type":"reflect","persona":"Vijay","source":"values / partner","relearn":"A shared decision is reasoned together by both people's values.","hook":"Lensy: in a shared choice, does it matter that both of you actually agree?","prompt":"What do you think?","options":["Yes","Both of us","That's fair"],"affirm":"A choice you both reason and agree on is one you can both own."},
  {"id":"mc-1034","cat":"decide-it","type":"reflect","persona":"any","source":"delaying respected","relearn":"Delaying is valid, respected and the most certain choice.","hook":"Lensy: if you chose to wait, would you feel you'd decided well?","prompt":"What do you think?","options":["Yes","Absolutely","It's a real choice"],"affirm":"Choosing to wait is deciding well; it's valid, certain and fully yours."},
  {"id":"mc-1035","cat":"decide-it","type":"reflect","persona":"Sneha","source":"owned","relearn":"Owning a choice means standing by your reasons.","hook":"Lensy: could you stand by a choice even if it surprised people?","prompt":"What do you think?","options":["Yes","I think so","I'm getting there"],"affirm":"A choice you can stand behind, reasoned and yours, is one you truly own."},
  {"id":"mc-1036","cat":"decide-it","type":"reflect","persona":"any","source":"decision skill","relearn":"Deciding well, informed and free, is the win, whatever you choose.","hook":"Lensy: does it help to know the win is deciding well, not picking one 'correct' option?","prompt":"What do you think?","options":["Yes","Takes the pressure off","The process is the win"],"affirm":"The skill is the win; whatever you choose, deciding it well is the point."},
  {"id":"mc-1037","cat":"decide-it","type":"reflect","persona":"Arjun","source":"autonomy","relearn":"Your choice holds with no one watching; that's the sign it's yours.","hook":"Lensy: would you make the same choice with no one watching?","prompt":"What do you think?","options":["Yes","I'd hope so","That's a good test"],"affirm":"A choice that holds unobserved is the clearest sign it's genuinely yours."},
  {"id":"mc-1038","cat":"decide-it","type":"spot","persona":"any","source":"spot pressure / decide-it","relearn":"Catch the two pressure lines; the others respect that the choice is yours.","hook":"Catch the two pressure lines; the others respect that the choice is yours.","scene":[{"id":"a","text":"\"Here's the full info, it's your call\"","trick":false},{"id":"b","text":"\"Everyone's doing it, don't be a baby\"","trick":true},{"id":"c","text":"\"Take your time, there's no rush\"","trick":false},{"id":"d","text":"\"Decide now or never\"","trick":true},{"id":"e","text":"\"Whatever you choose is fine with me\"","trick":false}],"why":"'Everyone's doing it' and 'decide now or never' are pressure; the rest leave the choice to you."},
  {"id":"mc-1039","cat":"decide-it","type":"spot","persona":"Vijay","source":"spot manipulation / consent floor","relearn":"Catch the two manipulations; the others are honest, pressure-free lines.","hook":"Catch the two manipulations; the others are honest, pressure-free lines.","scene":[{"id":"a","text":"\"Let's agree on protection together\"","trick":false},{"id":"b","text":"\"Wanting a condom means you don't trust me\"","trick":true},{"id":"c","text":"\"I want to check you actually want this\"","trick":false},{"id":"d","text":"\"Just this once without protection won't matter\"","trick":true},{"id":"e","text":"\"We can stop any time you want\"","trick":false}],"why":"'It means you don't trust me' and 'just this once won't matter' are manipulations; the rest are honest."},
  {"id":"mc-1040","cat":"decide-it","type":"spot","persona":"any","source":"spot rushed choice / decide-it","relearn":"Catch the two signs a choice is being rushed; the others mean it's unrushed.","hook":"Catch the two signs a choice is being rushed; the others mean it's unrushed.","scene":[{"id":"a","text":"You weighed it against your values","trick":false},{"id":"b","text":"\"Answer me right this second\"","trick":true},{"id":"c","text":"You gave yourself a day to think","trick":false},{"id":"d","text":"\"There's no time to think about it\"","trick":true},{"id":"e","text":"You checked the facts before choosing","trick":false}],"why":"An ultimatum and 'no time to think' rush you; the rest show a choice with room to breathe."},
  {"id":"mc-1041","cat":"decide-it","type":"spot","persona":"any","source":"spot not-your-choice / decide-it","relearn":"Catch the two signs a choice isn't really yours; the others mean it is.","hook":"Catch the two signs a choice isn't really yours; the others mean it is.","scene":[{"id":"a","text":"You can explain it by your own values","trick":false},{"id":"b","text":"You're mainly avoiding someone's anger","trick":true},{"id":"c","text":"You'd choose the same alone","trick":false},{"id":"d","text":"You're copying a friend to fit in","trick":true},{"id":"e","text":"You gathered the facts yourself","trick":false}],"why":"Avoiding disappointment and copying a friend aren't your reasons; the rest show an owned choice."},
  {"id":"mc-1042","cat":"decide-it","type":"spot","persona":"Counsellor","source":"spot exploitation / POCSO","relearn":"Secrecy demands and an older person's pressure are the red flags to catch.","hook":"Catch the two red flags an adult is exploiting a minor; the rest are safe and supportive.","scene":[{"id":"a","text":"A doctor offering confidential advice","trick":false},{"id":"b","text":"An older adult saying 'keep this our secret'","trick":true},{"id":"c","text":"A trusted adult you can tell anything","trick":false},{"id":"d","text":"A much older person pushing you toward sex","trick":true},{"id":"e","text":"A clinic that explains your rights","trick":false}],"why":"Secrecy demands and age-pressure from a much older adult are red flags; the rest are safe support."},
  {"id":"mc-1043","cat":"decide-it","type":"spot","persona":"any","source":"spot poor basis / decision basis","relearn":"Catch the two poor reasons to decide; the others are healthy bases for a choice.","hook":"Catch the two poor reasons to decide; the others are healthy bases for a choice.","scene":[{"id":"a","text":"Accurate facts from a clinician","trick":false},{"id":"b","text":"Fear of being judged","trick":true},{"id":"c","text":"Your own honest values","trick":false},{"id":"d","text":"A scary rumour you heard","trick":true},{"id":"e","text":"Checking everyone genuinely consents","trick":false}],"why":"Fear of judgement and a rumour are poor reasons; facts, values and consent are healthy ones."},
  {"id":"mc-1044","cat":"decide-it","type":"spot","persona":"any","source":"spot fake-respect / pressure-free","relearn":"Catch the two lines that only pretend to respect your choice; the rest truly do.","hook":"Catch the two lines that only pretend to respect your choice; the rest truly do.","scene":[{"id":"a","text":"\"It's completely your decision\"","trick":false},{"id":"b","text":"\"Fine, but you'll regret saying no\"","trick":true},{"id":"c","text":"\"I'll back whatever you choose\"","trick":false},{"id":"d","text":"\"A real adult would've said yes\"","trick":true},{"id":"e","text":"\"Take all the time you need\"","trick":false}],"why":"Guilt-tripping and 'real adults would' fake respect while pressuring; the rest leave the choice yours."},
  {"id":"mc-1045","cat":"decide-it","type":"sort","persona":"any","source":"decision steps","relearn":"Sort the steps of deciding well from the things that derail a choice.","hook":"Sort: part of deciding well, or what derails a choice?","items":[{"id":"a","text":"Gathering real facts"},{"id":"b","text":"Checking your own values"},{"id":"c","text":"Acting on a rumour"},{"id":"d","text":"Choosing freely"},{"id":"e","text":"Owning the outcome"},{"id":"f","text":"Letting panic pick"}],"bins":[{"id":"good","label":"Deciding well","valence":"pos"},{"id":"bad","label":"Derails it","valence":"neg"}],"key":{"a":"good","b":"good","c":"bad","d":"good","e":"good","f":"bad"}},
  {"id":"mc-1046","cat":"decide-it","type":"sort","persona":"any","source":"non-negotiables vs values","relearn":"Sort the fixed floor from the parts that are your personal call.","hook":"Sort: a fixed non-negotiable, or your own personal call?","items":[{"id":"a","text":"Consent"},{"id":"b","text":"Whether you wait"},{"id":"c","text":"Safety"},{"id":"d","text":"Which method fits you"},{"id":"e","text":"The law"},{"id":"f","text":"Your own timeline"}],"bins":[{"id":"fixed","label":"Always holds","valence":"pos"},{"id":"yours","label":"Your call","valence":"neutral"}],"key":{"a":"fixed","b":"yours","c":"fixed","d":"yours","e":"fixed","f":"yours"}},
  {"id":"mc-1047","cat":"decide-it","type":"sort","persona":"Vijay","source":"facts vs rumour","relearn":"Sort reliable sources of facts from unreliable ones for a real decision.","hook":"Sort: a reliable source to decide from, or not?","items":[{"id":"a","text":"A doctor"},{"id":"b","text":"A forwarded video"},{"id":"c","text":"An AFHC clinic"},{"id":"d","text":"A loud rumour"},{"id":"e","text":"A reliable health site"},{"id":"f","text":"'My cousin said so'"}],"bins":[{"id":"ok","label":"Reliable","valence":"pos"},{"id":"no","label":"Unreliable","valence":"neg"}],"key":{"a":"ok","b":"no","c":"ok","d":"no","e":"ok","f":"no"}},
  {"id":"mc-1048","cat":"decide-it","type":"sort","persona":"any","source":"respects vs pressures","relearn":"Sort what respects your choice from what pressures it.","hook":"Sort: respects your choice, or pressures it?","items":[{"id":"a","text":"'It's your call'"},{"id":"b","text":"'Decide right now'"},{"id":"c","text":"Giving you full facts"},{"id":"d","text":"'Everyone's doing it'"},{"id":"e","text":"'Take your time'"},{"id":"f","text":"'If you loved me you would'"}],"bins":[{"id":"respect","label":"Respects you","valence":"pos"},{"id":"pressure","label":"Pressures you","valence":"neg"}],"key":{"a":"respect","b":"pressure","c":"respect","d":"pressure","e":"respect","f":"pressure"}},
  {"id":"mc-1049","cat":"decide-it","type":"sort","persona":"any","source":"informed move vs not","relearn":"Sort the informed move from the unsafe one in each situation.","hook":"Sort: an informed move, or a risky one?","items":[{"id":"a","text":"EC within 5 days after a slip"},{"id":"b","text":"Just hoping after unprotected sex"},{"id":"c","text":"Asking a clinician about method fit"},{"id":"d","text":"Sharing one condom by reusing it"},{"id":"e","text":"Pairing condoms for dual protection"},{"id":"f","text":"Skipping protection 'just once'"}],"bins":[{"id":"smart","label":"Informed move","valence":"pos"},{"id":"risky","label":"Risky","valence":"neg"}],"key":{"a":"smart","b":"risky","c":"smart","d":"risky","e":"smart","f":"risky"}},
  {"id":"mc-1050","cat":"decide-it","type":"sort","persona":"Counsellor","source":"safe route vs flag","relearn":"Sort the safe, lawful route from the safeguarding red flag.","hook":"Sort: a safe route, or a red flag to report?","items":[{"id":"a","text":"Telling a trusted adult"},{"id":"b","text":"An adult demanding secrecy"},{"id":"c","text":"Asking a doctor confidentially"},{"id":"d","text":"A much older person pushing sex"},{"id":"e","text":"Calling Childline 1098"},{"id":"f","text":"Being threatened for a 'yes'"}],"bins":[{"id":"safe","label":"Safe route","valence":"tell"},{"id":"flag","label":"Red flag","valence":"uhoh"}],"key":{"a":"safe","b":"flag","c":"safe","d":"flag","e":"safe","f":"flag"}},
  {"id":"mc-1051","cat":"decide-it","type":"sort","persona":"any","source":"owned vs pleasing","relearn":"Sort signs a choice is truly yours from signs you're just pleasing someone.","hook":"Sort: a choice that's truly yours, or one made to please someone?","items":[{"id":"a","text":"You'd choose it unobserved"},{"id":"b","text":"You're avoiding their sulk"},{"id":"c","text":"It fits your values"},{"id":"d","text":"You're scared they'll leave"},{"id":"e","text":"You can explain your reasons"},{"id":"f","text":"You're copying to fit in"}],"bins":[{"id":"yours","label":"Truly yours","valence":"pos"},{"id":"please","label":"Just pleasing","valence":"neg"}],"key":{"a":"yours","b":"please","c":"yours","d":"please","e":"yours","f":"please"}},
  {"id":"mc-1052","cat":"decide-it","type":"sort","persona":"any","source":"healthy vs poor basis","relearn":"Sort a healthy basis for a decision from a poor one.","hook":"Sort: a healthy basis for deciding, or a poor one?","items":[{"id":"a","text":"Accurate facts"},{"id":"b","text":"Fear of judgement"},{"id":"c","text":"Your own values"},{"id":"d","text":"A scare rumour"},{"id":"e","text":"Genuine consent"},{"id":"f","text":"What looks impressive"}],"bins":[{"id":"good","label":"Healthy basis","valence":"pos"},{"id":"poor","label":"Poor basis","valence":"neg"}],"key":{"a":"good","b":"poor","c":"good","d":"poor","e":"good","f":"poor"}},
  {"id":"mc-1053","cat":"decide-it","type":"strike-rewrite","persona":"any","source":"decision skill","relearn":"Beyond consent, safety and law, there's no single 'right' choice, only your reasoned one.","hook":"\"There's one 'right' choice here and you have to find it.\"","myth":{"un":"There's one 'right' choice here and you must find it.","re":"Beyond consent, safety and law, there's no single 'right' choice, only your reasoned one.","why":"Real decisions rest on plural, legitimate values."}},
  {"id":"mc-1054","cat":"decide-it","type":"strike-rewrite","persona":"Sneha","source":"unrushed choice","relearn":"A real choice isn't rushed; taking the time you need is part of deciding well.","hook":"\"Take too long to decide and you've basically failed.\"","myth":{"un":"Taking time to decide means you've failed.","re":"A real choice isn't rushed; taking the time you need is part of deciding well.","why":"Urgency is usually pressure, not a deadline."}},
  {"id":"mc-1055","cat":"decide-it","type":"strike-rewrite","persona":"Vijay","source":"facts first","relearn":"Gather real facts from a clinician first; then weigh them with your values.","hook":"\"A gut feeling is enough to decide this on.\"","myth":{"un":"A gut feeling alone is enough to decide this.","re":"Gather real facts from a clinician first; then weigh them with your values.","why":"Facts ground the choice; feelings alone can miss the picture."}},
  {"id":"mc-1056","cat":"decide-it","type":"strike-rewrite","persona":"any","source":"boundary not distrust","relearn":"Protection is about health, not trust; keeping the boundary is reasonable.","hook":"\"Asking for protection means you don't trust your partner.\"","myth":{"un":"Asking for protection means you don't trust your partner.","re":"Protection is about health, not trust; keeping the boundary is reasonable.","why":"It's a manipulation line, not a real reason to drop protection."}},
  {"id":"mc-1057","cat":"decide-it","type":"strike-rewrite","persona":"Arjun","source":"maturity","relearn":"Asking for facts is exactly what maturity and a sound decision look like.","hook":"\"Needing to ask before deciding means you're not ready.\"","myth":{"un":"Needing to ask before deciding means you're not ready.","re":"Asking for facts is exactly what maturity and a sound decision look like.","why":"Informed choices are stronger, not weaker."}},
  {"id":"mc-1058","cat":"decide-it","type":"strike-rewrite","persona":"any","source":"self-owned","relearn":"Updating on new, verified facts is part of deciding well, not weakness.","hook":"\"Once you've decided, changing your mind makes you weak.\"","myth":{"un":"Changing your mind once you've decided makes you weak.","re":"Updating on new, verified facts is part of deciding well, not weakness.","why":"A good decision can adapt when the facts change."}},
  {"id":"mc-1059","cat":"decide-it","type":"strike-rewrite","persona":"Counsellor","source":"POCSO","relearn":"Under 18, an older person pressuring you is exploitation; it's never your fault.","hook":"\"If you 'chose' it, an older person's pressure isn't really their fault.\"","myth":{"un":"If you went along, an older person's pressure isn't their fault.","re":"Under 18, an older person pressuring you is exploitation; it's never your fault.","why":"The law protects you; coercion is the adult's wrong, not yours."}},
  {"id":"mc-1060","cat":"decide-it","type":"strike-rewrite","persona":"any","source":"delaying respected","relearn":"Choosing to wait is an active, valid choice, and the most certain one.","hook":"\"Deciding to wait isn't really a decision, it's just doing nothing.\"","myth":{"un":"Deciding to wait isn't a real decision, just doing nothing.","re":"Choosing to wait is an active, valid choice, and the most certain one.","why":"Waiting reasoned by your values is deciding, not avoiding."}},
  {"id":"mc-1061","cat":"decide-it","type":"role-play","persona":"Sneha","source":"decision skill / asserting time","relearn":"You can ask for time out loud; a real choice isn't rushed.","hook":"Someone wants your decision instantly.","setup":"Someone wants your decision instantly. Buy yourself the time you need. Say:","yourLine":[{"text":"\"I'll give you an answer once I've thought it through properly.\"","best":true},{"text":"Blurt out a yes to end the pressure"}]},
  {"id":"mc-1062","cat":"decide-it","type":"role-play","persona":"Vijay","source":"decision skill / facts first","relearn":"Saying you want to check the facts first is a strong, mature move.","hook":"Before deciding on a method, you want real information.","setup":"Before deciding on a method, you want real information. Say:","yourLine":[{"text":"\"I want to ask a doctor about my options before I decide.\"","best":true},{"text":"Decide on whatever a friend swears by"}]},
  {"id":"mc-1063","cat":"decide-it","type":"role-play","persona":"any","source":"decision skill / re-decide for self","relearn":"You can name out loud that a choice has to be yours, not to please someone.","hook":"You notice you're about to choose just to keep a partner happy.","setup":"You notice you're about to choose just to keep a partner happy. Say:","yourLine":[{"text":"\"I need this to be my decision, not just what makes you happy.\"","best":true},{"text":"Go along to avoid upsetting them"}]},
  {"id":"mc-1064","cat":"decide-it","type":"role-play","persona":"Arjun","source":"decision skill / own it","relearn":"Owning your choice out loud, without apology, is part of deciding well.","hook":"A friend questions a choice you reasoned carefully.","setup":"A friend questions a choice you reasoned carefully. Stand by it. Say:","yourLine":[{"text":"\"I thought it through and it's right for me; I'm okay with that.\"","best":true},{"text":"Backtrack so they'll stop asking"}]},
  {"id":"mc-1065","cat":"decide-it","type":"role-play","persona":"any","source":"decision skill / consent check","relearn":"Checking your partner genuinely wants this is part of a sound decision.","hook":"Before going further, you want to be sure it's a real, free yes.","setup":"Before going further, you want to be sure it's a real, free yes. Say:","yourLine":[{"text":"\"Do you actually want this too? We only carry on if we both do.\"","best":true},{"text":"Assume the earlier yes still stands"}]},
  {"id":"mc-1066","cat":"decide-it","type":"role-play","persona":"Sneha","source":"decision skill / family timeline","relearn":"You can hold your own timeline respectfully when family pushes.","hook":"Relatives press you to marry before you're ready.","setup":"Relatives press you to marry before you're ready. Say:","yourLine":[{"text":"\"I'll decide about marriage in my own time, and I'd like that respected.\"","best":true},{"text":"Agree to a date just to end it"}]},
  {"id":"mc-1067","cat":"decide-it","type":"role-play","persona":"Vijay","source":"decision skill / safety over shortcut","relearn":"Saying you'll use a real service, not a risky shortcut, is the sound call.","hook":"A friend pushes an unverified 'cheaper' method.","setup":"A friend pushes an unverified 'cheaper' method. Say:","yourLine":[{"text":"\"I'd rather get a proper method from a clinic, even if it costs more.\"","best":true},{"text":"Take the shortcut to save a bit"}]},
  {"id":"mc-1068","cat":"decide-it","type":"role-play","persona":"Counsellor","source":"decision skill / safeguarding","relearn":"Naming pressure to a trusted adult is a strong, protective decision.","hook":"An older person is pressuring you and you feel trapped.","setup":"An older person is pressuring you and you feel trapped. Tell a trusted adult:","yourLine":[{"text":"\"An older person is pressuring me and I need help; this isn't okay.\"","best":true},{"text":"Keep it secret and handle it alone"}]},
  {"id":"mc-1069","cat":"decide-it","type":"match","persona":"any","source":"decision steps","relearn":"Match each decision step to what it means.","hook":"Match each decision step to what it means.","pairs":[{"left":"Gather facts","right":"Ask a clinician, not a rumour"},{"left":"Check values","right":"Weigh what matters to you"},{"left":"Decide freely","right":"Choose with no pressure either way"},{"left":"Own it","right":"Stand by your reasons"},{"left":"Non-negotiables","right":"Consent, safety and the law"}]},
  {"id":"mc-1070","cat":"decide-it","type":"match","persona":"any","source":"situation to move","relearn":"Match each situation to the informed move.","hook":"Match each situation to the informed move.","pairs":[{"left":"A condom split last night","right":"Consider EC within 5 days"},{"left":"You keep forgetting the pill","right":"Ask about a no-daily method"},{"left":"Want STI and pregnancy cover","right":"Use condoms in the plan"},{"left":"Pushed to 'decide right now'","right":"Take the time you need"},{"left":"An older adult pressuring you","right":"Tell a trusted adult"}]},
  {"id":"mc-1071","cat":"decide-it","type":"match","persona":"Vijay","source":"pressure line to truth","relearn":"Match each pressure line to the truth that answers it.","hook":"Match each pressure line to the truth that answers it.","pairs":[{"left":"'You don't trust me'","right":"Protection is about health"},{"left":"'Everyone's doing it'","right":"Your timeline is your own"},{"left":"'If you loved me'","right":"Love isn't proven by giving in"},{"left":"'Decide right now'","right":"A real choice isn't rushed"},{"left":"'Waiting is for prudes'","right":"Waiting is valid and certain"}]},
  {"id":"mc-1072","cat":"decide-it","type":"match","persona":"any","source":"right to its backing","relearn":"Match each right to what backs it.","hook":"Match each right to what backs it.","pairs":[{"left":"To decide if and when","right":"Reproductive rights"},{"left":"To private care","right":"Confidentiality"},{"left":"To be free of coercion","right":"The law's protection (under 18)"},{"left":"To accurate facts","right":"Adolescent-friendly services"},{"left":"To take your time","right":"No-pressure principle"}]},
  {"id":"mc-1073","cat":"decide-it","type":"match","persona":"any","source":"good vs poor basis","relearn":"Match each basis to whether it's healthy or poor for deciding.","hook":"Match each basis to whether it's healthy or poor for deciding.","pairs":[{"left":"Accurate facts","right":"Healthy basis"},{"left":"Your own values","right":"Sound basis"},{"left":"Fear of judgement","right":"Poor basis"},{"left":"A scare rumour","right":"Unreliable basis"},{"left":"What looks impressive","right":"Not your real reason"}]},
  {"id":"mc-1074","cat":"decide-it","type":"match","persona":"Counsellor","source":"need to where to go","relearn":"Match each need to where to go in India.","hook":"Match each need to where to go in India.","pairs":[{"left":"Confidential adolescent care","right":"AFHC / Ujala clinic"},{"left":"A method or prescription","right":"A doctor"},{"left":"Condoms or EC pills","right":"A pharmacy"},{"left":"Help with coercion","right":"Childline 1098"},{"left":"Guidance when you're unsure","right":"A trusted adult"}]},
  {"id":"mc-1075","cat":"decide-it","type":"match","persona":"any","source":"step to a slip","relearn":"Match each common slip to the decision step it skips.","hook":"Match each common slip to the decision step it skips.","pairs":[{"left":"Acting on a forward","right":"Skipped gathering facts"},{"left":"Choosing to please a partner","right":"Skipped your own values"},{"left":"Giving in to an ultimatum","right":"Skipped choosing freely"},{"left":"Blaming someone for the outcome","right":"Skipped owning it"},{"left":"Ignoring a clear safety line","right":"Skipped the non-negotiables"}]},
  {"id":"mc-1076","cat":"decide-it","type":"match","persona":"any","source":"sign to what it shows","relearn":"Match each sign to what it shows about a choice.","hook":"Match each sign to what it shows about a choice.","pairs":[{"left":"You'd choose it unobserved","right":"It's truly yours"},{"left":"You can explain your reasons","right":"It's reasoned, not random"},{"left":"You checked real facts","right":"It's informed"},{"left":"Both partners agreed","right":"It's a shared decision"},{"left":"No one was pressured","right":"It's freely made"}]},
  {"id":"mc-1080","cat":"if-when-whether","type":"reflect","hook":"Lensy: you get to decide whether marriage is even part of your plan at all. Sit with that.","prompt":"What do you think?","options":["That's freeing","My plan, my call","Good to know"],"affirm":"Marriage, children, neither: all of it is yours to choose on your own timeline.","relearn":"Whether marriage is part of your life is your own choice to make.","persona":"Sneha","source":"reproductive rights / autonomy"},
  {"id":"mc-1081","cat":"if-when-whether","type":"reflect","hook":"Lensy: 'when' is yours too: finishing studies first, working a few years, no fixed rush. Fair?","prompt":"What do you think?","options":["Yes, no rush","On my timeline","Reassuring"],"affirm":"There's no deadline set by anyone else; you set the pace that fits your life.","relearn":"When to have children, if ever, is yours to time on your own life plan.","persona":"any","source":"timeline / autonomy"},
  {"id":"mc-1082","cat":"if-when-whether","type":"reflect","hook":"Lensy: planning your own future is a strength, not selfishness. How does that land?","prompt":"What do you think?","options":["It's a strength","Not selfish","I'll own it"],"affirm":"Building the life you want is mature and yours by right, never something to apologise for.","relearn":"Planning your own future is a strength, not selfishness.","persona":"Sneha","source":"autonomy / self-worth"},
  {"id":"mc-1083","cat":"if-when-whether","type":"reflect","hook":"Lensy: relatives may share their hopes for you. Their hopes, your decision. Agree?","prompt":"What do you think?","options":["Their hopes, my call","Yes","I can hear them out"],"affirm":"You can listen kindly and still keep the decision firmly your own.","relearn":"You can hear family's hopes and still keep the decision yours.","persona":"any","source":"family input vs decision"},
  {"id":"mc-1084","cat":"if-when-whether","type":"reflect","hook":"Lensy: choosing 'not now' about sex isn't a phase you owe anyone an exit from. Sit with it.","prompt":"What do you think?","options":["Not now is fine","It's my call","I don't owe a timeline"],"affirm":"'Not now' is a complete, respected answer. You owe no one a date to change it.","relearn":"'Not now' is a full, valid answer you owe no one an explanation for.","persona":"any","source":"delaying respected"},
  {"id":"mc-1085","cat":"if-when-whether","type":"reflect","hook":"Lensy: a friend marries young by choice; you want to wait. Both can be right. Fair?","prompt":"What do you think?","options":["Both valid","Different paths","Yes"],"affirm":"Different paths, both freely chosen. There's no single right life here.","relearn":"Different freely-made choices can both be right; there's no one right life.","persona":"Vijay","source":"plural legitimate values"},
  {"id":"mc-1086","cat":"if-when-whether","type":"reflect","hook":"Lensy: spacing children, if you have them, to suit health and life is a real choice too. Agree?","prompt":"What do you think?","options":["Yes","Good to plan","My choice"],"affirm":"How far apart, and whether at all, are yours to plan. It supports everyone's health.","relearn":"Spacing children, if you have them, is a real planning choice that supports health.","persona":"Counsellor","source":"spacing / health"},
  {"id":"mc-1087","cat":"if-when-whether","type":"reflect","hook":"Lensy: wanting a career first doesn't mean you've rejected family forever. How's that feel?","prompt":"What do you think?","options":["Just an order","Both can come","My sequence"],"affirm":"You get to sequence your life. Career now needn't close any door later.","relearn":"Choosing a career first doesn't rule out family later; you set the order.","persona":"Sneha","source":"sequencing life choices"},
  {"id":"mc-1088","cat":"if-when-whether","type":"reflect","hook":"Lensy: being out and queer, your choices about partnership and family are equally yours. Agree?","prompt":"What do you think?","options":["Equally mine","Yes","Good to hear"],"affirm":"Whatever shape your future family takes, the choice is wholly yours and equally valid.","relearn":"Your choices about partnership and family are yours and equally valid.","persona":"Arjun","source":"inclusive / autonomy"},
  {"id":"mc-1089","cat":"if-when-whether","type":"reflect","hook":"Lensy: nobody can shame you into a 'yes' about sex, marriage or babies. How's that sit?","prompt":"What do you think?","options":["Shame isn't a yes","My free yes","Reassuring"],"affirm":"A real yes is freely given. Shame, guilt or pressure can never make one for you.","relearn":"Shame or pressure can't make a real 'yes'; only you can, freely.","persona":"any","source":"free consent / pressure-free"},
  {"id":"mc-1090","cat":"if-when-whether","type":"reflect","hook":"Lensy: changing your mind later about if or when is allowed. Your plan can grow with you. Fair?","prompt":"What do you think?","options":["I can change it","Plans grow","Yes"],"affirm":"Your plan isn't a contract. You can revisit if, when and whether as you grow.","relearn":"You can change your mind later; your plan grows with you.","persona":"any","source":"evolving choices"},
  {"id":"mc-1091","cat":"if-when-whether","type":"reflect","hook":"Lensy: 'whether' includes the freedom to never want children, and that's whole and fine. Agree?","prompt":"What do you think?","options":["Whole and fine","Yes","My call"],"affirm":"Choosing never to have children is a complete, respected life, fully your right.","relearn":"Choosing not to have children at all is a valid, respected choice.","persona":"any","source":"whether / no children"},
  {"id":"mc-1092","cat":"if-when-whether","type":"reflect","hook":"Lensy: knowing family planning is a tool you choose, not a rule, who holds your future now?","prompt":"What do you think?","options":["I do","Me, clearly","It's mine"],"affirm":"You do: knowing it's a tool you pick puts your future in your own hands.","relearn":"Family planning is a tool you choose; your future stays in your hands.","persona":"Vijay","source":"family planning as a tool"},
  {"id":"mc-1093","cat":"if-when-whether","type":"reflect","hook":"Lensy: if you feel pressure to 'settle down' before you're ready, naming it is the first step. Fair?","prompt":"What do you think?","options":["Name it","Yes","I see it now"],"affirm":"Naming pressure for what it is keeps the choice yours, on your timeline.","relearn":"Naming 'settle down' pressure keeps the choice yours.","persona":"Sneha","source":"reading pressure"},
  {"id":"mc-1094","cat":"if-when-whether","type":"reflect","hook":"Lensy: your worth isn't measured by being married or a parent by a certain age. How's that land?","prompt":"What do you think?","options":["Worth isn't a date","Reassuring","Yes"],"affirm":"Your worth was never tied to a timeline someone else drew for you.","relearn":"Your worth isn't measured by marrying or parenting by any age.","persona":"any","source":"self-worth / no deadline"},
  {"id":"mc-1095","cat":"if-when-whether","type":"reflect","hook":"Lensy: 'when others want it' and 'when I want it' aren't the same. Whose 'when' decides? Sit with it.","prompt":"What do you think?","options":["Mine","My when","Clear now"],"affirm":"Your 'when' is the one that counts. Others' timing doesn't override yours.","relearn":"The 'when' that decides is yours, not what others want for you.","persona":"any","source":"timeline / autonomy"},
  {"id":"mc-1096","cat":"if-when-whether","type":"reflect","hook":"Lensy: deciding freely also means it's okay to feel unsure for now. Unsure is allowed. Agree?","prompt":"What do you think?","options":["Unsure is okay","Yes","No rush to know"],"affirm":"You don't need every answer today; 'unsure for now' is a fine, free place to be.","relearn":"Being unsure for now is okay; you needn't decide if or when today.","persona":"any","source":"no-rush / autonomy"},
  {"id":"mc-1097","cat":"if-when-whether","type":"strike-rewrite","hook":"\"If you wait too long to marry, no one will want you.\"","myth":{"un":"Wait too long to marry and no one will want you.","re":"Whether and when to marry is your timeline; worth isn't a shrinking window.","why":"That line is pressure dressed as a deadline, not a fact about you."},"relearn":"Marrying is your timeline; your worth isn't a shrinking window.","persona":"Sneha","source":"against marriage-deadline pressure"},
  {"id":"mc-1098","cat":"if-when-whether","type":"strike-rewrite","hook":"\"A married woman's real job is to have children quickly.\"","myth":{"un":"A married woman's real job is to have children quickly.","re":"Whether and when to have children stays the couple's free choice, hers included.","why":"No one owes anyone a child on a schedule; the choice is the couple's."},"relearn":"Whether and when to have children is the couple's free choice.","persona":"any","source":"against forced-childbearing norm"},
  {"id":"mc-1099","cat":"if-when-whether","type":"strike-rewrite","hook":"\"Planning when to have kids is going against nature.\"","myth":{"un":"Planning when to have children is going against nature.","re":"Planning if, when and how is a healthy, normal way to choose your family.","why":"Choosing thoughtfully is responsible planning, not a transgression."},"relearn":"Planning if and when to have children is healthy and normal.","persona":"Counsellor","source":"family planning framing"},
  {"id":"mc-1100","cat":"if-when-whether","type":"strike-rewrite","hook":"\"Wanting to study instead of marry means you've forgotten your duty.\"","myth":{"un":"Wanting to study instead of marry means you've forgotten your duty.","re":"Your education and future are yours to build; the timeline is yours to set.","why":"Building your future is a right, not a betrayal of anyone."},"relearn":"Your education and future are yours; the timeline is yours to set.","persona":"Sneha","source":"education vs early marriage"},
  {"id":"mc-1101","cat":"if-when-whether","type":"strike-rewrite","hook":"\"Once you're engaged, you've lost the right to say 'not yet'.\"","myth":{"un":"Once engaged, you've lost the right to say 'not yet'.","re":"You keep the right to your own pace about sex and timing, engaged or not.","why":"An engagement is not consent; readiness stays yours throughout."},"relearn":"Engagement doesn't end your right to say 'not yet'; readiness stays yours.","persona":"any","source":"readiness / consent"},
  {"id":"mc-1102","cat":"if-when-whether","type":"strike-rewrite","hook":"\"A real man should want a big family as soon as possible.\"","myth":{"un":"A real man should want a big family as soon as possible.","re":"Whether and when to have children is a free choice for men too, not a test.","why":"Manhood isn't proven by fast fatherhood; the choice is genuinely his."},"relearn":"Whether and when to have children is a free choice for men too.","persona":"Vijay","source":"against masculinity pressure"},
  {"id":"mc-1103","cat":"if-when-whether","type":"strike-rewrite","hook":"\"Couples who delay children are just being selfish.\"","myth":{"un":"Couples who delay children are just being selfish.","re":"Choosing when, or whether, to have children is thoughtful, not selfish.","why":"Deciding on your own timeline harms no one; it's a respected choice."},"relearn":"Delaying or choosing when to have children is thoughtful, not selfish.","persona":"any","source":"delaying respected"},
  {"id":"mc-1104","cat":"if-when-whether","type":"strike-rewrite","hook":"\"You should have a baby to save a shaky relationship.\"","myth":{"un":"Have a baby to save a shaky relationship.","re":"A child is never a fix for a relationship; if and when stay a free, calm choice.","why":"Choosing to have a child is its own decision, not a repair tool."},"relearn":"A child is never a relationship fix; if and when stay a free choice.","persona":"Counsellor","source":"against pressure framing"},
  {"id":"mc-1105","cat":"if-when-whether","type":"strike-rewrite","hook":"\"If you don't have kids right away, something's wrong with you.\"","myth":{"un":"If you don't have kids right away, something's wrong with you.","re":"Waiting, or not wanting children, is common and healthy. Nothing's wrong.","why":"There's no 'correct' timeline you're failing; the choice is yours."},"relearn":"Waiting or not wanting children is healthy; nothing's wrong with you.","persona":"any","source":"delaying respected"},
  {"id":"mc-1106","cat":"if-when-whether","type":"strike-rewrite","hook":"\"Two people of the same sex can't really plan a family, so why bother.\"","myth":{"un":"Same-sex couples can't really plan a family, so why bother.","re":"Everyone's choices about partnership and family are theirs to make and plan.","why":"Family takes many shapes; the right to choose belongs to all."},"relearn":"Everyone's choices about partnership and family are theirs to plan.","persona":"Arjun","source":"inclusive / autonomy"},
  {"id":"mc-1107","cat":"if-when-whether","type":"strike-rewrite","hook":"\"A girl who talks about her own timeline is being too modern.\"","myth":{"un":"A girl who talks about her own timeline is being too modern.","re":"Choosing your own timeline is a plain right, not a trend to be shamed for.","why":"Owning your future is normal and fair, whatever decade it is."},"relearn":"Choosing your own timeline is a right, not something to be shamed for.","persona":"Sneha","source":"against shaming autonomy"},
  {"id":"mc-1109","cat":"if-when-whether","type":"strike-rewrite","hook":"\"Planning your family means you don't trust God's plan.\"","myth":{"un":"Planning your family means you don't trust fate.","re":"Choosing if, when and how is a personal right that can sit with any belief.","why":"Thoughtful planning and faith aren't enemies; the choice stays yours."},"relearn":"Choosing if, when and how is a right that can sit with any belief.","persona":"any","source":"family planning framing"},
  {"id":"mc-1110","cat":"if-when-whether","type":"strike-rewrite","hook":"\"Once you marry, your in-laws decide when you'll have kids.\"","myth":{"un":"Once you marry, your in-laws decide when you'll have children.","re":"Family can share views, but the decision stays the couple's to make freely.","why":"Input is welcome; the choice itself belongs to the two people, not others."},"relearn":"Family can share views; the decision stays the couple's to make freely.","persona":"any","source":"family input vs decision"},
  {"id":"mc-1111","cat":"if-when-whether","type":"strike-rewrite","hook":"\"Spacing or limiting children is only for people who can't cope.\"","myth":{"un":"Spacing or limiting children is only for people who can't cope.","re":"Spacing and limiting are positive planning choices that support health.","why":"It's a thoughtful tool for any family, not a sign of weakness."},"relearn":"Spacing and limiting children are positive choices that support health.","persona":"Counsellor","source":"spacing / health"},
  {"id":"mc-1112","cat":"if-when-whether","type":"strike-rewrite","hook":"\"A boy doesn't get a say in 'when'. That's the girl's worry.\"","myth":{"un":"A boy doesn't get a say in 'when'. That's the girl's worry.","re":"If and when is a shared decision both partners make together, freely.","why":"Both people's timelines and choices count in the decision."},"relearn":"If and when is a shared decision both partners make together.","persona":"Vijay","source":"shared decision"},
  {"id":"mc-1113","cat":"if-when-whether","type":"strike-rewrite","hook":"\"Choosing to wait just means you're scared, not mature.\"","myth":{"un":"Choosing to wait just means you're scared, not mature.","re":"Deciding to wait can be the most thoughtful, mature choice there is.","why":"Maturity is choosing on your own values, including the value of waiting."},"relearn":"Choosing to wait can be the most mature, thoughtful choice.","persona":"any","source":"delaying respected"},
  {"id":"mc-1114","cat":"if-when-whether","type":"strike-rewrite","hook":"\"If you don't decide about marriage now, you'll miss your only chance.\"","myth":{"un":"Decide about marriage now or miss your only chance.","re":"There's no single window; whether and when stay yours, with no rush.","why":"'Now or never' is pressure, not truth. A real choice isn't rushed."},"relearn":"Whether and when to marry stay yours, with no 'now or never' rush.","persona":"Sneha","source":"against rushed-decision pressure"},
  {"id":"mc-1115","cat":"if-when-whether","type":"sort","hook":"Sort: whose decision is each of these, really?","items":[{"id":"a","text":"Whether you have children"},{"id":"b","text":"When you have them"},{"id":"c","text":"Whether you marry at all"},{"id":"d","text":"Being forced to decide today"},{"id":"e","text":"Being shamed into a 'yes'"},{"id":"f","text":"Whether you delay sex for now"}],"bins":[{"id":"yours","label":"Yours to decide","valence":"pos"},{"id":"notok","label":"Not theirs to force","valence":"neg"}],"key":{"a":"yours","b":"yours","c":"yours","d":"notok","e":"notok","f":"yours"},"relearn":"Whether, when, marrying and delaying are yours; forcing and shaming aren't theirs to do.","persona":"any","source":"reproductive rights"},
  {"id":"mc-1116","cat":"if-when-whether","type":"sort","hook":"Sort: which lines respect your choice, and which pressure it?","items":[{"id":"a","text":"\"Take all the time you need to decide\""},{"id":"b","text":"\"Everyone's married by now, hurry up\""},{"id":"c","text":"\"It's your future, your call\""},{"id":"d","text":"\"Prove you love me. Let's not wait\""},{"id":"e","text":"\"I'll support whatever you choose\""},{"id":"f","text":"\"A girl your age should be married\""}],"bins":[{"id":"respect","label":"Respects you","valence":"pos"},{"id":"pressure","label":"Pressures you","valence":"uhoh"}],"key":{"a":"respect","b":"pressure","c":"respect","d":"pressure","e":"respect","f":"pressure"},"relearn":"Respect gives time and space; pressure rushes, guilts or sets a deadline.","persona":"any","source":"reading pressure"},
  {"id":"mc-1117","cat":"if-when-whether","type":"sort","hook":"Sort: a free choice, or pressure pretending to be a choice?","items":[{"id":"a","text":"Deciding after gathering the facts"},{"id":"b","text":"Saying yes so relatives stop nagging"},{"id":"c","text":"Choosing on your own values"},{"id":"d","text":"Agreeing because you're scared to refuse"},{"id":"e","text":"Picking your own timeline"},{"id":"f","text":"Going along to avoid a fight"}],"bins":[{"id":"free","label":"A free choice","valence":"pos"},{"id":"pressure","label":"Pressure in disguise","valence":"uhoh"}],"key":{"a":"free","b":"pressure","c":"free","d":"pressure","e":"free","f":"pressure"},"relearn":"A free choice comes from facts and your values; the rest is pressure in disguise.","persona":"any","source":"free choice vs pressure"},
  {"id":"mc-1118","cat":"if-when-whether","type":"sort","hook":"Sort: what's a positive use of family planning, and what's a myth about it?","items":[{"id":"a","text":"Choosing when, if ever, to have children"},{"id":"b","text":"\"It's only for stopping babies\""},{"id":"c","text":"Spacing children to support health"},{"id":"d","text":"\"It means going against nature\""},{"id":"e","text":"Building the family life you want"},{"id":"f","text":"\"It's a sign your marriage failed\""}],"bins":[{"id":"true","label":"Positive truth","valence":"pos"},{"id":"myth","label":"A myth","valence":"neg"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"},"relearn":"Family planning positively chooses if, when and how; the rest are myths.","persona":"Counsellor","source":"family planning framing"},
  {"id":"mc-1119","cat":"if-when-whether","type":"sort","hook":"Sort: which belong to you, and which are simply not your job to satisfy?","items":[{"id":"a","text":"Your own timeline for marriage"},{"id":"b","text":"A relative's wish for grandchildren"},{"id":"c","text":"Your choice about having children"},{"id":"d","text":"Neighbours' opinions on your pace"},{"id":"e","text":"Your readiness about sex"},{"id":"f","text":"Society's deadline for 'settling down'"}],"bins":[{"id":"yours","label":"Yours to own","valence":"pos"},{"id":"not","label":"Not yours to satisfy","valence":"uhoh"}],"key":{"a":"yours","b":"not","c":"yours","d":"not","e":"yours","f":"not"},"relearn":"Your timeline, choices and readiness are yours; others' wishes aren't your job.","persona":"Sneha","source":"autonomy vs others' expectations"},
  {"id":"mc-1120","cat":"if-when-whether","type":"sort","hook":"Sort: which of these is a healthy, respected choice, and which is a red flag?","items":[{"id":"a","text":"Deciding to wait until you feel ready"},{"id":"b","text":"A partner shaming you for waiting"},{"id":"c","text":"Talking it over calmly together"},{"id":"d","text":"A partner refusing to take 'not yet'"},{"id":"e","text":"Choosing your own pace freely"},{"id":"f","text":"Being threatened to give a 'yes'"}],"bins":[{"id":"healthy","label":"Healthy choice","valence":"pos"},{"id":"flag","label":"A red flag","valence":"neg"}],"key":{"a":"healthy","b":"flag","c":"healthy","d":"flag","e":"healthy","f":"flag"},"relearn":"Waiting, talking and choosing freely are healthy; shame, refusal and threats are red flags.","persona":"any","source":"red-flag reading"},
  {"id":"mc-1121","cat":"if-when-whether","type":"sort","hook":"Sort: who actually gets the final say on each one?","items":[{"id":"a","text":"Whether Sneha continues her studies"},{"id":"b","text":"When Vijay feels ready to be a parent"},{"id":"c","text":"Whether Arjun has a family one day"},{"id":"d","text":"Whether you delay sex for now"},{"id":"e","text":"A cousin's plan for your wedding date"},{"id":"f","text":"A neighbour's view on your 'right' age"}],"bins":[{"id":"theirs","label":"The person's own call","valence":"pos"},{"id":"outside","label":"An outsider's view","valence":"uhoh"}],"key":{"a":"theirs","b":"theirs","c":"theirs","d":"theirs","e":"outside","f":"outside"},"relearn":"Each person owns their own choice; cousins and neighbours only hold opinions.","persona":"any","source":"autonomy / final say"},
  {"id":"mc-1122","cat":"if-when-whether","type":"sort","hook":"Sort: which respects 'no pressure in any direction', and which nudges you?","items":[{"id":"a","text":"\"Wait or don't. It's genuinely yours\""},{"id":"b","text":"\"Real adults don't wait this long\""},{"id":"c","text":"\"Whatever you pick, I respect it\""},{"id":"d","text":"\"You're a prude if you keep waiting\""},{"id":"e","text":"\"Here are the facts; you decide\""},{"id":"f","text":"\"Hurry up, you're falling behind\""}],"bins":[{"id":"free","label":"No pressure","valence":"pos"},{"id":"nudge","label":"Nudges you","valence":"uhoh"}],"key":{"a":"free","b":"nudge","c":"free","d":"nudge","e":"free","f":"nudge"},"relearn":"No pressure offers facts and respect; nudging shames or rushes you either way.","persona":"any","source":"pressure-free both directions"},
  {"id":"mc-1123","cat":"if-when-whether","type":"sort","hook":"Sort: which of these is genuinely your right, and which is someone overstepping?","items":[{"id":"a","text":"Asking a clinic about your options privately"},{"id":"b","text":"Someone deciding your wedding for you"},{"id":"c","text":"Taking time before you choose"},{"id":"d","text":"Being told you've 'no right' to wait"},{"id":"e","text":"Setting your own family timeline"},{"id":"f","text":"A partner ignoring your 'not ready'"}],"bins":[{"id":"right","label":"Your right","valence":"pos"},{"id":"over","label":"Overstepping","valence":"neg"}],"key":{"a":"right","b":"over","c":"right","d":"over","e":"right","f":"over"},"relearn":"Asking, taking time and setting your timeline are rights; deciding for you is overstepping.","persona":"any","source":"rights vs overstepping"},
  {"id":"mc-1124","cat":"if-when-whether","type":"sort","hook":"Sort: which is a calm fact about choices, and which is a fear-line to ignore?","items":[{"id":"a","text":"\"You can revisit your plan as you grow\""},{"id":"b","text":"\"Miss this window and it's over for you\""},{"id":"c","text":"\"Waiting is common and respected\""},{"id":"d","text":"\"No one decent will want you if you wait\""},{"id":"e","text":"\"Not wanting children is a valid life\""},{"id":"f","text":"\"You'll regret not rushing into it\""}],"bins":[{"id":"calm","label":"Calm fact","valence":"pos"},{"id":"fear","label":"Fear-line","valence":"uhoh"}],"key":{"a":"calm","b":"fear","c":"calm","d":"fear","e":"calm","f":"fear"},"relearn":"Calm facts state your options; fear-lines push you with 'now or never' threats.","persona":"any","source":"against fear framing"},
  {"id":"mc-1125","cat":"if-when-whether","type":"sort","hook":"Sort: which paths are equally valid choices, and which is a non-negotiable?","items":[{"id":"a","text":"Marrying young, freely chosen"},{"id":"b","text":"Studying first, marrying later"},{"id":"c","text":"Choosing never to have children"},{"id":"d","text":"Consent in any relationship"},{"id":"e","text":"Waiting a few years to decide"},{"id":"f","text":"Safety from coercion"}],"bins":[{"id":"valid","label":"All equally valid","valence":"pos"},{"id":"nonneg","label":"Non-negotiable","valence":"tell"}],"key":{"a":"valid","b":"valid","c":"valid","d":"nonneg","e":"valid","f":"nonneg"},"relearn":"Many freely-made paths are equally valid; consent and safety are always non-negotiable.","persona":"any","source":"plural values + non-negotiables"},
  {"id":"mc-1126","cat":"if-when-whether","type":"sort","hook":"Sort: which line owns the decision, and which hands it to someone else?","items":[{"id":"a","text":"\"I'll decide when I'm ready\""},{"id":"b","text":"\"Whatever they want is fine, I guess\""},{"id":"c","text":"\"This is my timeline to set\""},{"id":"d","text":"\"I'll just do what's expected\""},{"id":"e","text":"\"I've thought it through; this is my call\""},{"id":"f","text":"\"It's easier to let them choose\""}],"bins":[{"id":"own","label":"Owns the choice","valence":"pos"},{"id":"hand","label":"Hands it away","valence":"uhoh"}],"key":{"a":"own","b":"hand","c":"own","d":"hand","e":"own","f":"hand"},"relearn":"Owning the choice sounds like 'my call'; handing it away defaults to others.","persona":"Sneha","source":"owning the decision"},
  {"id":"mc-1127","cat":"if-when-whether","type":"branch","hook":"Parents are fixing a wedding date you weren't asked about. You'd rather finish college first.","options":[{"text":"Calmly ask to finish your studies before any date is set","consequence":"You keep your timeline and stay in the talk.","outcome":"autonomy","best":true},{"text":"Say nothing and let the date be fixed","consequence":"Your timeline is yours; voice it before it's fixed."},{"text":"Storm off without explaining","consequence":"A calm, clear ask holds your ground better."}],"debrief":"Family input is fine; the timing stays yours.","relearn":"You can ask to set your own timeline first.","persona":"Sneha","source":"autonomy / family"},
  {"id":"mc-1128","cat":"if-when-whether","type":"branch","hook":"Newly married, relatives keep asking when the 'good news' is coming. You both want to wait.","options":[{"text":"Agree a kind, united 'we'll decide in our own time'","consequence":"You hold the boundary together, warmly.","outcome":"boundary","best":true},{"text":"Promise a baby soon to quiet them","consequence":"Whether and when is yours; you needn't promise."},{"text":"Let each relative pressure you alone","consequence":"A shared line protects the choice that's yours."}],"debrief":"Whether and when to have children stays the couple's free choice.","relearn":"You can hold a united 'in our own time'.","persona":"any","source":"couple boundary"},
  {"id":"mc-1129","cat":"if-when-whether","type":"branch","hook":"A scholarship abroad means delaying the marriage family hoped for. You want the course.","options":[{"text":"Take it and talk it through honestly with family","consequence":"You build your future and keep them in the loop.","outcome":"future","best":true},{"text":"Turn it down to avoid disappointing them","consequence":"Your education is yours; pursue it and still respect them."},{"text":"Accept but hide it from everyone","consequence":"An honest talk serves you better than secrecy."}],"debrief":"Your education and future are yours to build.","relearn":"You can pursue your future and talk it through.","persona":"Sneha","source":"education vs early marriage"},
  {"id":"mc-1130","cat":"if-when-whether","type":"branch","hook":"Friends tease that you're 'the last single one' and should marry the next person who asks.","options":[{"text":"Laugh it off; keep choosing by what matters to you","consequence":"You stay on your own values and timeline.","outcome":"own-values","best":true},{"text":"Rush into a match to stop the teasing","consequence":"'Last' isn't a reason; the choice should fit you."},{"text":"Feel ashamed and withdraw","consequence":"Teasing isn't a verdict; your timeline is still valid."}],"debrief":"There's no deadline; whether and when stay yours.","relearn":"You can choose by your own values, not 'last single one' teasing.","persona":"Vijay","source":"peer pressure"},
  {"id":"mc-1131","cat":"if-when-whether","type":"branch","hook":"Your partner says a baby right after marriage will 'prove' you're serious. You're not sure.","options":[{"text":"Say you'd rather decide together, not to prove anything","consequence":"You keep it a free, shared choice.","outcome":"shared","best":true},{"text":"Agree, to show you're committed","consequence":"A child isn't proof; if and when should be freely chosen."},{"text":"Avoid the topic and hope it passes","consequence":"Naming it kindly serves you both better."}],"debrief":"A child is never proof; if and when stay a free, shared choice.","relearn":"You can ask to decide together, not to prove anything.","persona":"any","source":"against pressure framing"},
  {"id":"mc-1132","cat":"if-when-whether","type":"branch","hook":"You're out and gay; a relative insists you 'must marry a woman and have kids to be normal'.","options":[{"text":"Hold, kindly, that your life and choices are your own","consequence":"You keep your future yours without a fight.","outcome":"autonomy","best":true},{"text":"Agree to a marriage you don't want, for peace","consequence":"Your choices are yours; peace shouldn't cost your life."},{"text":"Cut off the relative on the spot","consequence":"A calm boundary often holds better than a break."}],"debrief":"Choices about partnership and family are yours.","relearn":"You can hold that your choices are your own.","persona":"Arjun","source":"inclusive / autonomy"},
  {"id":"mc-1133","cat":"if-when-whether","type":"branch","hook":"You feel ready to choose your path but fear upsetting everyone. A voice says 'just obey'.","options":[{"text":"Gather facts, check your values, then decide and own it","consequence":"You choose from yourself, not fear.","outcome":"own-it","best":true},{"text":"Obey to keep everyone comfortable","consequence":"Choosing only to please others is worth re-deciding."},{"text":"Freeze and let the deadline decide","consequence":"A real choice isn't rushed; take the time to decide."}],"debrief":"Gather facts, check your values, decide freely, own it.","relearn":"You can decide from your values, not fear.","persona":"any","source":"decision skill"},
  {"id":"mc-1134","cat":"if-when-whether","type":"branch","hook":"A much older person pushes you, under 18, to marry fast. It feels off.","options":[{"text":"Step back; tell a trusted adult or call Childline 1098","consequence":"You get protection and a clear head.","outcome":"safety","best":true},{"text":"Go along because they're older and insistent","consequence":"Pressure on an under-18 is a safeguarding matter."},{"text":"Keep it secret and decide alone","consequence":"You don't have to face this alone."}],"debrief":"An older person pressuring an under-18 routes to safeguarding.","relearn":"Step back; tell a trusted adult.","persona":"Counsellor","source":"safeguarding / under-18"},
  {"id":"mc-1135","cat":"if-when-whether","type":"role-play","hook":"A relative says: \"You're old enough now. Time to think about marriage and babies.\"","setup":"You want to keep your own timeline, kindly but clearly.","yourLine":[{"text":"\"I hear you. Whether and when is my own choice, and I'm not ready for that yet.\"","best":true},{"text":"\"Maybe… I suppose if you all think so.\""},{"text":"\"I don't know, let's not talk about it.\""}],"persona":"Sneha","source":"autonomy / family","relearn":"You can say whether and when is your choice and you're not ready yet."},
  {"id":"mc-1136","cat":"if-when-whether","type":"role-play","hook":"Your partner says: \"If you really loved me, we'd start a family right away.\"","setup":"You want to keep this a free, shared decision.","yourLine":[{"text":"\"I do love you, and if and when we have kids is something we decide together, freely.\"","best":true},{"text":"\"Okay, if that's what proves it to you.\""},{"text":"\"Fine, whatever you want.\""}],"persona":"any","source":"against pressure framing","relearn":"You can keep if and when a free, shared decision, not proof of love."},
  {"id":"mc-1137","cat":"if-when-whether","type":"role-play","hook":"A friend teases: \"Still waiting? Everyone our age has moved on. You're so behind.\"","setup":"You want to hold your pace without getting defensive.","yourLine":[{"text":"\"I'm on my own timeline, and waiting is a choice I'm happy with.\"","best":true},{"text":"\"Yeah… maybe I am behind.\""},{"text":"\"Stop, you're making me feel bad.\""}],"persona":"Vijay","source":"peer pressure","relearn":"You can hold your own timeline; waiting is a choice you can be happy with."},
  {"id":"mc-1138","cat":"if-when-whether","type":"role-play","hook":"Your mother asks gently: \"Have you thought about when you'd want to marry, beta?\"","setup":"You want to answer honestly and keep the decision yours.","yourLine":[{"text":"\"I have, Ma. I'd like to finish my studies first, then decide in my own time.\"","best":true},{"text":"\"Whenever you think is best, Ma.\""},{"text":"\"Please don't ask me that.\""}],"persona":"Sneha","source":"education vs early marriage","relearn":"You can answer honestly and keep the decision and timing yours."},
  {"id":"mc-1139","cat":"if-when-whether","type":"role-play","hook":"At a clinic, you want to ask about choosing if and when to have children one day.","setup":"You want to ask plainly, without embarrassment.","yourLine":[{"text":"\"I'd like to understand my options for if and when I choose to have children.\"","best":true},{"text":"\"Sorry, this is probably a silly thing to ask…\""},{"text":"\"Never mind, forget I asked.\""}],"persona":"Arjun","source":"asking a clinician","relearn":"You can ask a clinician plainly about your options, without embarrassment."},
  {"id":"mc-1140","cat":"if-when-whether","type":"role-play","hook":"Relatives keep pressing you and your partner: \"So, when's the good news?\"","setup":"You want a kind, united line that holds the boundary.","yourLine":[{"text":"\"We'll decide that in our own time. Thanks for caring about us.\"","best":true},{"text":"\"Soon, soon, don't worry.\""},{"text":"\"Why does everyone keep asking us this?\""}],"persona":"any","source":"couple boundary","relearn":"You and your partner can hold a kind, united 'in our own time'."},
  {"id":"mc-1141","cat":"if-when-whether","type":"role-play","hook":"A cousin says: \"A real man would want a houseful of kids by now. What's wrong with you?\"","setup":"You want to push back calmly on the pressure.","yourLine":[{"text":"\"Whether and when to have kids is my choice. There's nothing wrong with deciding for myself.\"","best":true},{"text":"\"I guess I should want that, huh.\""},{"text":"\"Mind your own business.\""}],"persona":"Vijay","source":"against masculinity pressure","relearn":"You can say whether and when is your choice; nothing's wrong with deciding."},
  {"id":"mc-1142","cat":"if-when-whether","type":"role-play","hook":"Someone says: \"You're queer, so just marry quietly and have kids to keep the family happy.\"","setup":"You want to hold your own truth, kindly but firmly.","yourLine":[{"text":"\"My choices about partnership and family are mine. I won't live a life to keep up appearances.\"","best":true},{"text":"\"Maybe that's just easier for everyone.\""},{"text":"\"You don't get to say that to me.\""}],"persona":"Arjun","source":"inclusive / autonomy","relearn":"You can hold that your choices about partnership and family are yours."},
  {"id":"mc-1143","cat":"if-when-whether","type":"match","hook":"Match each pressure-line to the calm truth that answers it.","pairs":[{"left":"\"You're too old to be single\"","right":"My timeline is mine, not a deadline"},{"left":"\"A baby proves you're serious\"","right":"If and when is a free, shared choice"},{"left":"\"Family planning is unnatural\"","right":"It's a healthy way to choose"},{"left":"\"Waiting means something's wrong\"","right":"Waiting is common and respected"},{"left":"\"Your in-laws decide when\"","right":"The decision stays the couple's"}],"persona":"any","source":"pressure vs truth","relearn":"Each pressure-line meets a calm truth: your timeline, free choice, healthy planning."},
  {"id":"mc-1144","cat":"if-when-whether","type":"match","hook":"Match each choice to whose right it is.","pairs":[{"left":"Whether to have children","right":"Yours, on your own timeline"},{"left":"When to have them","right":"The couple's, decided together"},{"left":"A relative's hope for grandkids","right":"Their wish, not your duty"},{"left":"Whether to delay sex for now","right":"Your readiness, fully respected"},{"left":"Coercion by an older person","right":"A safeguarding matter, never your fault"}],"persona":"any","source":"whose right","relearn":"Whether, when and delaying are yours; coercion is a safeguarding matter."},
  {"id":"mc-1145","cat":"if-when-whether","type":"match","hook":"Match each life path to why it's a valid, free choice.","pairs":[{"left":"Studying first, marrying later","right":"Your future is yours to sequence"},{"left":"Choosing never to have children","right":"A complete, respected life"},{"left":"Marrying young, freely chosen","right":"Valid when it's truly your call"},{"left":"Spacing children apart","right":"Supports parent and child health"},{"left":"Waiting until you feel ready","right":"Readiness is yours to judge"}],"persona":"any","source":"plural valid paths","relearn":"Many freely-made paths are valid: studying first, waiting, or choosing no children."},
  {"id":"mc-1146","cat":"if-when-whether","type":"match","hook":"Match each person to the choice that's theirs to own.","pairs":[{"left":"Sneha, weighing studies vs marriage","right":"Her own timeline to set"},{"left":"Vijay, unsure he's ready to parent","right":"His readiness to decide freely"},{"left":"Arjun, planning his future family","right":"His path, equally valid"},{"left":"A newly-married couple","right":"If and when, decided together"},{"left":"An under-18 being pushed by an adult","right":"Protection: tell a trusted adult"}],"persona":"any","source":"autonomy / persons","relearn":"Each person owns their own choice; an under-18 under pressure gets protection."},
  {"id":"mc-1147","cat":"if-when-whether","type":"match","hook":"Match each word, like whether, when or how, to what it really means for you.","pairs":[{"left":"Whether","right":"Children or not: your free choice"},{"left":"When","right":"The timing, on your own life plan"},{"left":"How","right":"The methods and path you pick"},{"left":"Freely","right":"No pressure in any direction"},{"left":"Own it","right":"Stand by the choice you made"}],"persona":"any","source":"whether-when-how","relearn":"Whether, when and how are yours, chosen freely and owned."},
  {"id":"mc-1148","cat":"if-when-whether","type":"match","hook":"Match each respectful response to the situation it fits.","pairs":[{"left":"A relative shares wedding hopes","right":"Listen kindly; keep the decision yours"},{"left":"A partner pushes for a baby now","right":"Ask to decide together, freely"},{"left":"Friends tease you for waiting","right":"Hold your pace; waiting is valid"},{"left":"You're unsure what you want","right":"Take your time; unsure is okay"},{"left":"An older person pressures an under-18","right":"Step back; tell a trusted adult"}],"persona":"Counsellor","source":"respectful responses","relearn":"Listen, ask, hold your pace, take your time; pressure on an under-18 routes to an adult."},
  {"id":"mc-1149","cat":"if-when-whether","type":"match","hook":"Match each myth to the right it tries to deny.","pairs":[{"left":"\"No one wants you if you wait\"","right":"Your right to your own timeline"},{"left":"\"Same-sex couples can't plan a family\"","right":"Everyone's right to plan their family"},{"left":"\"A boy gets no say in when\"","right":"Both partners' right to decide together"},{"left":"\"You must have kids to be normal\"","right":"Your right to choose whether at all"},{"left":"\"Decide right now or never\"","right":"Your right to an unrushed choice"}],"persona":"any","source":"myths vs rights","relearn":"Each myth denies a right: your timeline, planning, deciding together."},
  {"id":"mc-1150","cat":"if-when-whether","type":"match","hook":"Match each value to the non-negotiable or free choice it sits with.","pairs":[{"left":"Consent in any relationship","right":"Always required, no exceptions"},{"left":"Safety from coercion","right":"Protected: tell a trusted adult"},{"left":"Whether you marry","right":"A free choice beyond the basics"},{"left":"When you have children","right":"Yours to time, no single right way"},{"left":"Whether you delay","right":"Valid, respected, and certain"}],"persona":"any","source":"values + non-negotiables","relearn":"Consent and safety are always required; whether and when stay free choices."},
  {"id":"mc-1151","cat":"if-when-whether","type":"spot","hook":"Spot the two lines that pressure your choice (not the ones that respect it).","scene":[{"id":"a","text":"\"Take all the time you need to decide\"","trick":false},{"id":"b","text":"\"You're falling behind. Just marry already\"","trick":true},{"id":"c","text":"\"Whatever you choose, I'll respect it\"","trick":false},{"id":"d","text":"\"If you wait any longer, no one will want you\"","trick":true},{"id":"e","text":"\"It's your future and your call\"","trick":false}],"why":"'Falling behind' and 'no one will want you' push you with deadlines and fear; the others give space.","relearn":"Pressure rushes or scares you; respect offers time and your own call.","persona":"any","source":"reading pressure"},
  {"id":"mc-1152","cat":"if-when-whether","type":"spot","hook":"Spot the two myths about if, when and whether (the rest are true).","scene":[{"id":"a","text":"Waiting is a common, respected choice","trick":false},{"id":"b","text":"\"Family planning means your marriage failed\"","trick":true},{"id":"c","text":"Spacing children can support health","trick":false},{"id":"d","text":"\"You must have kids to be a real woman\"","trick":true},{"id":"e","text":"Whether and when is your own right","trick":false}],"why":"'Marriage failed' and 'real woman' are shaming myths; the others are plain truths about your choices.","relearn":"Spot the shaming myths; whether, when and waiting are your respected rights.","persona":"any","source":"myth-spotting"},
  {"id":"mc-1153","cat":"if-when-whether","type":"spot","hook":"Spot the two lines that assume your 'yes' instead of asking for it.","scene":[{"id":"a","text":"\"Are you actually ready, or do you want to wait?\"","trick":false},{"id":"b","text":"\"Obviously we'll have kids straight after the wedding\"","trick":true},{"id":"c","text":"\"How do you feel about the timing?\"","trick":false},{"id":"d","text":"\"You don't get a say. It's already decided\"","trick":true},{"id":"e","text":"\"We'll choose when it's right for us both\"","trick":false}],"why":"'Obviously' and 'already decided' assume your yes and remove your say; the others genuinely ask.","relearn":"A real choice is asked for, not assumed; your say can't be skipped.","persona":"any","source":"assumed-yes spotting"},
  {"id":"mc-1154","cat":"if-when-whether","type":"spot","hook":"Spot the two fear-lines meant to rush your decision (the rest are calm facts).","scene":[{"id":"a","text":"You can revisit your plan as life changes","trick":false},{"id":"b","text":"\"Miss this chance and you'll regret it forever\"","trick":true},{"id":"c","text":"Not wanting children is a valid life","trick":false},{"id":"d","text":"\"It's now or you'll be alone for good\"","trick":true},{"id":"e","text":"Waiting until you're ready is respected","trick":false}],"why":"'Regret forever' and 'now or alone' are fear-lines; a real choice isn't rushed by threats.","relearn":"Spot the fear-lines; a real choice is unrushed and stays yours.","persona":"any","source":"against fear framing"},
  {"id":"mc-1155","cat":"if-when-whether","type":"spot","hook":"Spot the two lines that hand your decision to someone else (not the ones that own it).","scene":[{"id":"a","text":"\"I'll decide when I'm genuinely ready\"","trick":false},{"id":"b","text":"\"I'll just do whatever my family expects\"","trick":true},{"id":"c","text":"\"This is my timeline to set\"","trick":false},{"id":"d","text":"\"It's easier to let them choose for me\"","trick":true},{"id":"e","text":"\"I've thought it through; this is my call\"","trick":false}],"why":"'Whatever they expect' and 'let them choose' give your decision away; the others own it.","relearn":"Owning your choice sounds like 'my call'; handing it away defaults to others.","persona":"Sneha","source":"owning the decision"},
  {"id":"mc-1156","cat":"if-when-whether","type":"spot","hook":"Spot the two pressure-lines a partner might use about timing (the rest respect you).","scene":[{"id":"a","text":"\"Let's only do this when we both want to\"","trick":false},{"id":"b","text":"\"If you loved me you'd want kids now\"","trick":true},{"id":"c","text":"\"Your readiness matters as much as mine\"","trick":false},{"id":"d","text":"\"Everyone our age has a baby already\"","trick":true},{"id":"e","text":"\"There's no rush; we decide together\"","trick":false}],"why":"'If you loved me' and 'everyone already' are guilt and comparison; the others keep it mutual.","relearn":"Spot the guilt-trips; timing is a free, mutual choice, never proof of love.","persona":"any","source":"partner pressure spotting"},
  {"id":"mc-1157","cat":"if-when-whether","type":"spot","hook":"Spot the two lines that overstep your right (not the ones that honour it).","scene":[{"id":"a","text":"\"It's your body and your future to plan\"","trick":false},{"id":"b","text":"\"We've already fixed your wedding date\"","trick":true},{"id":"c","text":"\"Ask the clinic privately whenever you like\"","trick":false},{"id":"d","text":"\"You have no right to wait this long\"","trick":true},{"id":"e","text":"\"Take the time you need to decide\"","trick":false}],"why":"'Already fixed' and 'no right to wait' override your choice; the others respect it.","relearn":"Spot the overstepping lines; whether and when are yours to decide and time.","persona":"any","source":"rights vs overstepping"},
  {"id":"mc-1158","cat":"if-when-whether","type":"spot","hook":"Spot the two red flags an older person uses on an under-18 (rest are safe).","scene":[{"id":"a","text":"\"Talk to a trusted adult about any of this\"","trick":false},{"id":"b","text":"\"You're mature, so marry me and keep it secret\"","trick":true},{"id":"c","text":"\"A clinic can answer your questions privately\"","trick":false},{"id":"d","text":"\"Don't tell anyone. They'd just ruin it\"","trick":true},{"id":"e","text":"\"There's no rush; waiting is completely fine\"","trick":false}],"why":"'Keep it secret' and 'don't tell anyone' isolate you: red flags to step back from.","relearn":"Secrecy from an older person is a red flag; tell an adult or Childline 1098.","persona":"Counsellor","source":"safeguarding spotting"},
  {"id":"mc-1170","cat":"my-future-no-pressure","type":"strike-rewrite","hook":"\"If you wait too long, no one will want you.\"","myth":{"un":"If you wait, no one will want you.","re":"Waiting is a valid, respected, common choice, and the most certain one.","why":"Your worth was never a deadline."},"relearn":"Waiting is fully valid and respected; it is not a thing you 'run out of time' for.","persona":"Sneha","source":"delaying respected"},
  {"id":"mc-1171","cat":"my-future-no-pressure","type":"strike-rewrite","hook":"\"You're 17 now, so you should have it all figured out.\"","myth":{"un":"By 17 you should already have it all figured out.","re":"Asking and getting accurate information is exactly what maturity looks like.","why":"Owning a choice means informing it, at any age."},"relearn":"Asking is what maturity looks like; no one has it all figured out.","persona":"Arjun","source":"maturity"},
  {"id":"mc-1172","cat":"my-future-no-pressure","type":"strike-rewrite","hook":"\"Good kids don't go looking up this stuff.\"","myth":{"un":"Looking up this information makes you a 'bad' kid.","re":"Seeking accurate facts helps you make safer, more thoughtful choices, including waiting.","why":"Information supports your decision; it doesn't make it for you."},"relearn":"Looking things up is responsible; good information leads to safer, calmer choices.","persona":"any","source":"CSE evidence"},
  {"id":"mc-1173","cat":"my-future-no-pressure","type":"strike-rewrite","hook":"\"Once you've waited this long, it'd be weird to start a relationship.\"","myth":{"un":"Waiting this long makes a relationship 'weird' later.","re":"Your relationships and timeline are yours to shape whenever feels right to you.","why":"There's no clock that decides this for you."},"relearn":"Your timeline is yours; starting whenever feels right is normal, not 'weird'.","persona":"any","source":"agency"},
  {"id":"mc-1174","cat":"my-future-no-pressure","type":"strike-rewrite","hook":"\"A boyfriend would distract you from board exams anyway.\"","myth":{"un":"A relationship must distract you from your goals.","re":"Your education and your relationships are both yours to shape on your own terms.","why":"Your future isn't decided for you by other people's fears."},"relearn":"You get to shape both your goals and your relationships; neither cancels the other.","persona":"Sneha","source":"agency"},
  {"id":"mc-1175","cat":"my-future-no-pressure","type":"strike-rewrite","hook":"\"Everyone in your hostel is hooking up, so you're behind.\"","myth":{"un":"Everyone else is doing it, so you're 'behind'.","re":"Being active or not isn't what makes someone mature; an informed, consensual choice is.","why":"'Everyone' is pressure dressed as a fact."},"relearn":"There's no race; what counts is your own informed, consensual choice, at your pace.","persona":"Vijay","source":"non-judgmental"},
  {"id":"mc-1176","cat":"my-future-no-pressure","type":"strike-rewrite","hook":"\"Talking about protection just means you're planning to be irresponsible.\"","myth":{"un":"Learning about protection means you plan to be reckless.","re":"Knowing your options helps you make calmer, safer choices, whatever you decide.","why":"Information is preparation, not a push."},"relearn":"Knowing your options is preparation; it doesn't push you toward anything.","persona":"Vijay","source":"CSE evidence"},
  {"id":"mc-1177","cat":"my-future-no-pressure","type":"strike-rewrite","hook":"\"You're gay, so the 'whether and when' stuff isn't for you.\"","myth":{"un":"These choices about your future aren't for you.","re":"Your future, relationships and family choices are yours to shape, same as anyone's.","why":"Everyone gets to plan the life they want."},"relearn":"Your future and family choices are yours to shape, fully and equally.","persona":"Arjun","source":"inclusive / agency"},
  {"id":"mc-1178","cat":"my-future-no-pressure","type":"strike-rewrite","hook":"\"If you really cared about your family, you'd settle down now.\"","myth":{"un":"Caring about your family means settling down right now.","re":"Whether and when are yours to choose; family input is welcome but the call is yours.","why":"Love isn't a reason to hand over your timeline."},"relearn":"You can love your family and still keep whether and when as your own free choice.","persona":"Sneha","source":"autonomy / family"},
  {"id":"mc-1179","cat":"my-future-no-pressure","type":"strike-rewrite","hook":"\"Asking a counsellor about all this just shows you can't think for yourself.\"","myth":{"un":"Asking for guidance shows you can't think for yourself.","re":"Gathering facts from a clinic or trusted adult is part of deciding well for yourself.","why":"You still make the call; you just make it informed."},"relearn":"Asking gathers the facts; you still decide. That's thinking for yourself.","persona":"Counsellor","source":"maturity"},
  {"id":"mc-1180","cat":"my-future-no-pressure","type":"strike-rewrite","hook":"\"Saying no this time means you've shut the door forever.\"","myth":{"un":"Saying no now means you can never say yes later.","re":"Readiness can change; a 'no for now' keeps every future choice open and yours.","why":"A boundary today doesn't bind your tomorrow."},"relearn":"'No for now' is complete in itself and keeps future choices fully yours.","persona":"any","source":"delaying respected"},
  {"id":"mc-1181","cat":"my-future-no-pressure","type":"strike-rewrite","hook":"\"A modern young person isn't shy about these things.\"","myth":{"un":"A 'modern' person is never cautious about this.","re":"Caution and waiting are valid, respected choices, not a sign of being old-fashioned.","why":"There's no pressure toward 'modern' either, the choice is just yours."},"relearn":"Waiting isn't old-fashioned; no label, modern or otherwise, decides this for you.","persona":"any","source":"pressure-free"},
  {"id":"mc-1182","cat":"my-future-no-pressure","type":"strike-rewrite","hook":"\"If you don't decide right now, you'll regret it.\"","myth":{"un":"Decide right this second or you'll regret it.","re":"A real choice isn't rushed; taking the time you need is part of owning it.","why":"Urgency is a pressure tactic, not a fact."},"relearn":"You can take the time you need; 'decide now' is pressure, not a real deadline.","persona":"any","source":"decision skill"},
  {"id":"mc-1183","cat":"my-future-no-pressure","type":"strike-rewrite","hook":"\"Wanting to focus on your career means you're cold or selfish.\"","myth":{"un":"Choosing your career first makes you cold or selfish.","re":"Your future is yours to shape; building your education and goals is a fair, full choice.","why":"There's no single 'right' life you owe anyone."},"relearn":"Choosing to build your career first is a valid, whole life choice, not selfishness.","persona":"Sneha","source":"agency"},
  {"id":"mc-1184","cat":"my-future-no-pressure","type":"strike-rewrite","hook":"\"You only learn about contraception so you can go misbehave.\"","myth":{"un":"You learn about this only to go 'misbehave'.","re":"Clear information helps people make safer, more thoughtful choices, including waiting.","why":"Knowing more leads to calmer decisions, not riskier ones."},"relearn":"Information leads to safer, more thoughtful choices; it never pushes anyone to act.","persona":"Counsellor","source":"CSE evidence"},
  {"id":"mc-1185","cat":"my-future-no-pressure","type":"strike-rewrite","hook":"\"Being a virgin at your age is something to be ashamed of.\"","myth":{"un":"Not having had sex yet is something to be ashamed of.","re":"Waiting is a respected, common choice and nothing to be labelled or shamed for.","why":"Shame is just pressure with a meaner face."},"relearn":"There's nothing to be ashamed of in waiting; it's a respected, ordinary choice.","persona":"any","source":"delaying respected"},
  {"id":"mc-1186","cat":"my-future-no-pressure","type":"strike-rewrite","hook":"\"A real man wouldn't overthink protection, he'd just go for it.\"","myth":{"un":"A 'real man' wouldn't bother thinking about protection.","re":"Thinking it through and choosing protection is exactly what a responsible choice looks like.","why":"Macho 'just go for it' lines are pressure, not maturity."},"relearn":"Thinking it through is the mature move; 'just go for it' is pressure, not manhood.","persona":"Vijay","source":"non-judgmental"},
  {"id":"mc-1187","cat":"my-future-no-pressure","type":"strike-rewrite","hook":"\"Your life basically follows the same script as everyone else's.\"","myth":{"un":"Your life just follows the same script as everyone's.","re":"Your education, relationships and family choices are yours to shape, your own way.","why":"There's no single script you're required to follow."},"relearn":"There's no fixed script; your future is yours to shape on your own terms.","persona":"any","source":"agency"},
  {"id":"mc-1188","cat":"my-future-no-pressure","type":"strike-rewrite","hook":"\"Caring this much about doing it 'right' just means you're uptight.\"","myth":{"un":"Wanting to get this right just makes you uptight.","re":"Wanting an informed, consensual, thought-through choice is care, not being uptight.","why":"Doing it on your terms is the whole point here."},"relearn":"Wanting it informed and on your terms is care, not being uptight.","persona":"any","source":"pressure-free"},
  {"id":"mc-1189","cat":"my-future-no-pressure","type":"reflect","hook":"Lensy: think about a choice that's truly yours. What makes it feel that way?","prompt":"Pick what fits you.","options":["I have the full facts","It matches my values","No one is rushing me","I can own the outcome"],"affirm":"A choice you can stand behind, with facts, values and no rush, is genuinely your own.","relearn":"A choice feels yours when it rests on facts, your values, and no pressure.","persona":"any","source":"autonomy"},
  {"id":"mc-1190","cat":"my-future-no-pressure","type":"reflect","hook":"Lensy: when someone pushes 'everyone's doing it', what helps you stay steady?","prompt":"What grounds you?","options":["My own pace","What I actually want","Remembering it's pressure","My plans for myself"],"affirm":"Naming the push and returning to what you want is how you stay the author of your choice.","relearn":"Returning to your own pace and wants is how you stand steady against pressure.","persona":"Vijay","source":"pressure-free"},
  {"id":"mc-1191","cat":"my-future-no-pressure","type":"reflect","hook":"Lensy: picture your next few years. Which part feels most yours to shape?","prompt":"Pick one to sit with.","options":["My studies / work","Who I'm close to","Whether and when","All of it, my way"],"affirm":"Every part of that future is yours to shape, on your own timeline, no pressure either way.","relearn":"Your studies, your relationships and your timeline are all yours to shape.","persona":"Sneha","source":"values / future"},
  {"id":"mc-1192","cat":"my-future-no-pressure","type":"reflect","hook":"Lensy: how does it feel to know waiting is fully respected, not just 'allowed'?","prompt":"What comes up?","options":["Relieved","More in control","Less judged","It's just mine"],"affirm":"Waiting isn't a fallback you're tolerated for, it's a full, respected, certain choice.","relearn":"Waiting is a fully respected choice in its own right, not just tolerated.","persona":"any","source":"delaying respected"},
  {"id":"mc-1193","cat":"my-future-no-pressure","type":"reflect","hook":"Lensy: who in your life respects your choices without nudging you either way?","prompt":"Bring them to mind.","options":["A friend","A trusted adult","A counsellor / clinic","I'm finding them"],"affirm":"People who give you facts and space, and no push, are the ones worth leaning on.","relearn":"The people worth leaning on give you information and space, never a push.","persona":"any","source":"pressure-free"},
  {"id":"mc-1194","cat":"my-future-no-pressure","type":"reflect","hook":"Lensy: being out at home, what would 'my future, my terms' look like for you?","prompt":"Picture it.","options":["Honest relationships","Asking without shame","My own timeline","A life that fits me"],"affirm":"Your future on your terms is yours to picture and build, fully and without apology.","relearn":"Your future on your own terms is yours to build, honestly and without apology.","persona":"Arjun","source":"inclusive / agency"},
  {"id":"mc-1195","cat":"my-future-no-pressure","type":"reflect","hook":"Lensy: when a decision is rushed, what do you usually wish you'd done?","prompt":"What helps next time?","options":["Slowed down","Gathered facts","Checked my values","Asked someone I trust"],"affirm":"Giving yourself time and facts is how a choice stays calm, clear and truly yours.","relearn":"Slowing down and gathering facts keeps a choice calm, clear and your own.","persona":"any","source":"decision skill"},
  {"id":"mc-1196","cat":"my-future-no-pressure","type":"reflect","hook":"Lensy: what does 'maturity' actually mean to you in all this?","prompt":"Pick your version.","options":["Asking when unsure","Owning my choices","Respecting others' pace","Deciding by my values"],"affirm":"Maturity here is owning informed choices and respecting that others' pace is theirs too.","relearn":"Maturity is owning informed choices and respecting that others' pace is theirs.","persona":"Counsellor","source":"maturity"},
  {"id":"mc-1197","cat":"my-future-no-pressure","type":"reflect","hook":"Lensy: imagine choosing with no one watching and no one to please. What changes?","prompt":"Notice the shift.","options":["It gets clearer","I feel calmer","I trust myself more","The choice is mine"],"affirm":"The choice you'd make unobserved, for your own reasons, is the one that's really yours.","relearn":"The choice you'd make with no one to please is the clearest sign it's yours.","persona":"any","source":"autonomy"},
  {"id":"mc-1198","cat":"my-future-no-pressure","type":"reflect","hook":"Lensy: a friend is being shamed for waiting. What would you want them to hear?","prompt":"Pick your message.","options":["Your pace is fine","Waiting is respected","Don't owe anyone","I've got your back"],"affirm":"Backing a friend's right to wait is how we keep this pressure-free for each other.","relearn":"Backing a friend's right to wait keeps the space pressure-free for everyone.","persona":"any","source":"pressure-free"},
  {"id":"mc-1199","cat":"my-future-no-pressure","type":"reflect","hook":"Lensy: take the whole node in. What's the one idea you want to keep?","prompt":"Pick your keeper.","options":["My choices, my info","No pressure, any way","Waiting is fully valid","Decide by my values"],"affirm":"Whatever you keep, it lands the same: your information, no pressure, your free choice.","relearn":"Your information, no pressure in any direction, and a choice that's genuinely yours.","persona":"any","source":"consolidation"},
  {"id":"mc-1200","cat":"my-future-no-pressure","type":"spot","hook":"Spot the two pressure lines (so you can refuse them).","scene":[{"id":"a","text":"\"If you loved me you wouldn't make me wait\"","trick":true},{"id":"b","text":"\"Whatever you decide, I'm fine with it\"","trick":false},{"id":"c","text":"\"Take your time, no rush at all\"","trick":false},{"id":"d","text":"\"Everyone our age has done it already\"","trick":true},{"id":"e","text":"\"I'd never push you on this\"","trick":false}],"why":"'If you loved me' and 'everyone's done it' are pressure; the rest give you space.","relearn":"'If you loved me' and 'everyone's doing it' are pressure lines to name and refuse.","persona":"Vijay","source":"spot pressure"},
  {"id":"mc-1201","cat":"my-future-no-pressure","type":"spot","hook":"Spot the two lines that try to rush your decision.","scene":[{"id":"a","text":"\"Decide right now or the moment's gone\"","trick":true},{"id":"b","text":"\"There's no hurry, think it over\"","trick":false},{"id":"c","text":"\"You can change your mind anytime\"","trick":false},{"id":"d","text":"\"It's now or never, honestly\"","trick":true},{"id":"e","text":"\"Sleep on it if you want\"","trick":false}],"why":"'Right now' and 'now or never' are rush tactics; a real choice isn't hurried.","relearn":"'Decide now' and 'now or never' are rush tactics; a real choice isn't hurried.","persona":"any","source":"decision skill"},
  {"id":"mc-1202","cat":"my-future-no-pressure","type":"spot","hook":"Spot the two lines that shame your choice.","scene":[{"id":"a","text":"\"Only a prude would still be waiting\"","trick":true},{"id":"b","text":"\"Your timeline is completely your call\"","trick":false},{"id":"c","text":"\"What a frigid, boring thing to say\"","trick":true},{"id":"d","text":"\"Either way is genuinely okay\"","trick":false},{"id":"e","text":"\"I respect whatever you pick\"","trick":false}],"why":"'Prude' and 'frigid' are shame labels, just pressure; the rest leave the choice yours.","relearn":"Shame labels like 'prude' are pressure in disguise; name them and let them go.","persona":"Sneha","source":"delaying respected"},
  {"id":"mc-1203","cat":"my-future-no-pressure","type":"spot","hook":"Spot the two lines that try to decide your future for you.","scene":[{"id":"a","text":"\"A girl your age should just be thinking marriage\"","trick":true},{"id":"b","text":"\"Whether and when is yours to decide\"","trick":false},{"id":"c","text":"\"Your studies are yours to plan\"","trick":false},{"id":"d","text":"\"Forget the degree, that ship has sailed for you\"","trick":true},{"id":"e","text":"\"I'll back whatever path you choose\"","trick":false}],"why":"'Should be thinking marriage' and 'forget the degree' decide for you; the rest don't.","relearn":"Lines that decide your marriage or studies for you are pressure to name, not advice.","persona":"Sneha","source":"agency"},
  {"id":"mc-1204","cat":"my-future-no-pressure","type":"spot","hook":"Spot the two manipulative lines about protection.","scene":[{"id":"a","text":"\"Wanting protection means you don't trust me\"","trick":true},{"id":"b","text":"\"Let's agree on protection together\"","trick":false},{"id":"c","text":"\"Real partners just skip all that\"","trick":true},{"id":"d","text":"\"Your health matters to me too\"","trick":false},{"id":"e","text":"\"We can talk it through calmly\"","trick":false}],"why":"'You don't trust me' and 'real partners skip it' are manipulation; protection is health, not trust.","relearn":"'You don't trust me' about protection is manipulation; protection is about health.","persona":"Vijay","source":"consent / negotiation"},
  {"id":"mc-1205","cat":"my-future-no-pressure","type":"spot","hook":"Spot the two lines that mock you for seeking information.","scene":[{"id":"a","text":"\"Why are you even reading about this, weirdo\"","trick":true},{"id":"b","text":"\"Good that you're getting the facts first\"","trick":false},{"id":"c","text":"\"Only clueless people need to look this up\"","trick":true},{"id":"d","text":"\"Ask a clinic if you want to be sure\"","trick":false},{"id":"e","text":"\"Knowing your options is smart\"","trick":false}],"why":"Mocking you for getting facts is pressure; seeking accurate information is the mature move.","relearn":"Mocking you for seeking facts is pressure; getting informed is exactly the mature move.","persona":"Arjun","source":"maturity"},
  {"id":"mc-1206","cat":"my-future-no-pressure","type":"spot","hook":"Spot the two lines that push you toward a 'yes' you didn't give.","scene":[{"id":"a","text":"\"You hinted earlier, so it's basically decided\"","trick":true},{"id":"b","text":"\"Only if and when you actually want to\"","trick":false},{"id":"c","text":"\"You came this far, you can't back out now\"","trick":true},{"id":"d","text":"\"You can stop at any point\"","trick":false},{"id":"e","text":"\"Your yes has to be a real yes\"","trick":false}],"why":"'Basically decided' and 'can't back out' assume a yes you didn't give; consent is ongoing.","relearn":"Lines that assume a 'yes' you didn't give are pressure; consent stays ongoing and yours.","persona":"any","source":"consent"},
  {"id":"mc-1207","cat":"my-future-no-pressure","type":"spot","hook":"Spot the two lines that try to make you choose to please others.","scene":[{"id":"a","text":"\"Do it so people stop talking about you\"","trick":true},{"id":"b","text":"\"Choose what's actually right for you\"","trick":false},{"id":"c","text":"\"You'd disappoint everyone if you don't\"","trick":true},{"id":"d","text":"\"This is your call, not theirs\"","trick":false},{"id":"e","text":"\"What do you genuinely want here?\"","trick":false}],"why":"Choosing to silence gossip or avoid disappointing others isn't a free choice; pause and re-decide.","relearn":"If a choice is mainly to please others, pause and re-decide from your own values.","persona":"any","source":"autonomy"},
  {"id":"mc-1208","cat":"my-future-no-pressure","type":"spot","hook":"Spot the two lines that use fear to push a decision.","scene":[{"id":"a","text":"\"Wait and you'll be alone forever\"","trick":true},{"id":"b","text":"\"You have plenty of time to decide\"","trick":false},{"id":"c","text":"\"Say no and you'll lose everyone\"","trick":true},{"id":"d","text":"\"A no now changes nothing about your worth\"","trick":false},{"id":"e","text":"\"Either choice keeps your options open\"","trick":false}],"why":"'Alone forever' and 'lose everyone' are scare tactics; fear isn't a reason to decide.","relearn":"Scare lines like 'alone forever' are pressure; fear is never a sound basis to decide.","persona":"any","source":"pressure-free"},
  {"id":"mc-1209","cat":"my-future-no-pressure","type":"spot","hook":"Spot the two lines that hand your timeline to someone else.","scene":[{"id":"a","text":"\"Your aunt already picked the right year for you\"","trick":true},{"id":"b","text":"\"When is genuinely up to you\"","trick":false},{"id":"c","text":"\"The family decides this, not you\"","trick":true},{"id":"d","text":"\"They can advise; the choice stays yours\"","trick":false},{"id":"e","text":"\"It's your life to plan\"","trick":false}],"why":"'Already picked' and 'family decides, not you' take your timeline; input is fine, the call is yours.","relearn":"Others can advise, but lines that take your timeline are pressure; the call stays yours.","persona":"Sneha","source":"autonomy / family"},
  {"id":"mc-1210","cat":"my-future-no-pressure","type":"spot","hook":"Spot the two lines from an older person to step back from.","scene":[{"id":"a","text":"\"You're mature for your age, so it's fine\"","trick":true},{"id":"b","text":"\"A clinic can answer that confidentially\"","trick":false},{"id":"c","text":"\"Keep this just between us, tell no one\"","trick":true},{"id":"d","text":"\"A trusted adult can help with this\"","trick":false},{"id":"e","text":"\"Talk to someone you trust\"","trick":false}],"why":"'Mature for your age' and 'tell no one' are flags; step back and tell a trusted adult.","relearn":"'Mature for your age' plus secrecy from an older person is a flag; tell someone.","persona":"Counsellor","source":"safeguarding"},
  {"id":"mc-1211","cat":"my-future-no-pressure","type":"sort","hook":"Sort each line: respects your choice, or pressures it?","items":[{"id":"a","text":"\"Here's the full info, it's your call\""},{"id":"b","text":"\"Everyone's doing it, don't be a baby\""},{"id":"c","text":"\"Take all the time you need\""},{"id":"d","text":"\"If you loved me, you would\""},{"id":"e","text":"\"Whatever you decide is okay with me\""},{"id":"f","text":"\"Decide right now or forget it\""}],"bins":[{"id":"respect","label":"Respects you","valence":"pos"},{"id":"pressure","label":"Pressures you","valence":"neg"}],"key":{"a":"respect","b":"pressure","c":"respect","d":"pressure","e":"respect","f":"pressure"},"relearn":"Respect gives facts and space; pressure pushes, rushes, guilts or labels.","persona":"any","source":"pressure-free"},
  {"id":"mc-1212","cat":"my-future-no-pressure","type":"sort","hook":"Sort: a healthy basis for your choice, or a poor one?","items":[{"id":"a","text":"Accurate facts from a clinic"},{"id":"b","text":"Fear of being judged"},{"id":"c","text":"Your own values"},{"id":"d","text":"A rumour from a group chat"},{"id":"e","text":"Time to think it over"},{"id":"f","text":"Wanting to silence gossip"}],"bins":[{"id":"good","label":"Healthy basis","valence":"pos"},{"id":"poor","label":"Poor basis","valence":"neg"}],"key":{"a":"good","b":"poor","c":"good","d":"poor","e":"good","f":"poor"},"relearn":"Decide from facts, your values and time; not fear, rumour or pleasing others.","persona":"any","source":"decision basis"},
  {"id":"mc-1213","cat":"my-future-no-pressure","type":"sort","hook":"Sort: a respected choice, or a forced one?","items":[{"id":"a","text":"Deciding to wait"},{"id":"b","text":"Being coerced into sex"},{"id":"c","text":"Freely choosing your method"},{"id":"d","text":"Being shamed into a 'yes'"},{"id":"e","text":"Choosing your own timeline"},{"id":"f","text":"Being guilt-tripped to please family"}],"bins":[{"id":"respected","label":"Respected choice","valence":"pos"},{"id":"forced","label":"Forced / wrong","valence":"neg"}],"key":{"a":"respected","b":"forced","c":"respected","d":"forced","e":"respected","f":"forced"},"relearn":"Waiting and free choice are respected; coercion, shaming and guilt-tripping are not.","persona":"any","source":"autonomy"},
  {"id":"mc-1214","cat":"my-future-no-pressure","type":"sort","hook":"Sort: a sign a choice is truly yours, or a sign it isn't?","items":[{"id":"a","text":"You can give your own reasons"},{"id":"b","text":"You're avoiding someone's anger"},{"id":"c","text":"You'd choose the same unobserved"},{"id":"d","text":"You're trying to stop the gossip"},{"id":"e","text":"It matches your values"},{"id":"f","text":"You feel rushed into it"}],"bins":[{"id":"yours","label":"Truly yours","valence":"pos"},{"id":"not","label":"Not really yours","valence":"neg"}],"key":{"a":"yours","b":"not","c":"yours","d":"not","e":"yours","f":"not"},"relearn":"A choice is yours when it's reasoned, values-led and holds with no one watching.","persona":"any","source":"autonomy"},
  {"id":"mc-1215","cat":"my-future-no-pressure","type":"sort","hook":"Sort: part of building your own future, or a label others put on you?","items":[{"id":"a","text":"Planning your studies"},{"id":"b","text":"\"Prude\""},{"id":"c","text":"Choosing your own timeline"},{"id":"d","text":"\"Behind everyone else\""},{"id":"e","text":"Deciding by your values"},{"id":"f","text":"\"Too uptight\""}],"bins":[{"id":"yours","label":"Yours to build","valence":"pos"},{"id":"label","label":"Just a label","valence":"neg"}],"key":{"a":"yours","b":"label","c":"yours","d":"label","e":"yours","f":"label"},"relearn":"Plans and values build your future; 'prude' and 'behind' are just pressure labels.","persona":"any","source":"agency"},
  {"id":"mc-1216","cat":"my-future-no-pressure","type":"sort","hook":"Sort: shows real maturity here, or just acts grown-up?","items":[{"id":"a","text":"Asking a clinic when unsure"},{"id":"b","text":"Pretending you know it all"},{"id":"c","text":"Owning your own choice"},{"id":"d","text":"Daring someone to 'prove' themselves"},{"id":"e","text":"Respecting another's pace"},{"id":"f","text":"Mocking someone for waiting"}],"bins":[{"id":"mature","label":"Real maturity","valence":"pos"},{"id":"fake","label":"Just posturing","valence":"neg"}],"key":{"a":"mature","b":"fake","c":"mature","d":"fake","e":"mature","f":"fake"},"relearn":"Maturity is asking, owning your choice and respecting pace; not posturing or mocking.","persona":"Arjun","source":"maturity"},
  {"id":"mc-1217","cat":"my-future-no-pressure","type":"sort","hook":"Sort: information that empowers a choice, or a scare meant to push you?","items":[{"id":"a","text":"\"Here are your real options\""},{"id":"b","text":"\"Wait and you'll regret it forever\""},{"id":"c","text":"\"You decide what fits your life\""},{"id":"d","text":"\"Say no and you'll be alone\""},{"id":"e","text":"\"A clinic explains it calmly\""},{"id":"f","text":"\"Everyone will laugh if you don't\""}],"bins":[{"id":"empower","label":"Empowers you","valence":"pos"},{"id":"scare","label":"Scare tactic","valence":"neg"}],"key":{"a":"empower","b":"scare","c":"empower","d":"scare","e":"empower","f":"scare"},"relearn":"Empowering info gives options and calm; scare lines use fear to push you.","persona":"any","source":"pressure-free"},
  {"id":"mc-1218","cat":"my-future-no-pressure","type":"sort","hook":"Sort: keeps the choice yours, or hands it to someone else?","items":[{"id":"a","text":"\"When is up to you\""},{"id":"b","text":"\"Your family decides this\""},{"id":"c","text":"\"They can advise, you choose\""},{"id":"d","text":"\"Your partner gets the final say\""},{"id":"e","text":"\"It's your life to plan\""},{"id":"f","text":"\"People will choose for you anyway\""}],"bins":[{"id":"yours","label":"Stays yours","valence":"pos"},{"id":"handed","label":"Given away","valence":"neg"}],"key":{"a":"yours","b":"handed","c":"yours","d":"handed","e":"yours","f":"handed"},"relearn":"Others can advise; the decision stays yours to make freely, not handed over.","persona":"Sneha","source":"autonomy / family"},
  {"id":"mc-1219","cat":"my-future-no-pressure","type":"sort","hook":"Sort each into the choice it really is.","items":[{"id":"a","text":"Choosing to wait for now"},{"id":"b","text":"Being pushed to 'prove' love"},{"id":"c","text":"Picking a method that fits you"},{"id":"d","text":"Being rushed to decide today"},{"id":"e","text":"Taking time to think"},{"id":"f","text":"Being told 'everyone's doing it'"}],"bins":[{"id":"free","label":"A free choice","valence":"pos"},{"id":"push","label":"A push","valence":"neg"}],"key":{"a":"free","b":"push","c":"free","d":"push","e":"free","f":"push"},"relearn":"Waiting, fitting a method and taking time are free choices; rushing and 'everyone' are pushes.","persona":"any","source":"pressure-free"},
  {"id":"mc-1220","cat":"my-future-no-pressure","type":"sort","hook":"Sort: supports an inclusive, pressure-free choice, or stigmatises it?","items":[{"id":"a","text":"\"Your relationships are yours to shape\""},{"id":"b","text":"\"That's not for people like you\""},{"id":"c","text":"\"Ask a clinic, no judgement\""},{"id":"d","text":"\"You should be ashamed to ask\""},{"id":"e","text":"\"Your future is yours to plan\""},{"id":"f","text":"\"People like you don't get a say\""}],"bins":[{"id":"support","label":"Supports you","valence":"pos"},{"id":"stigma","label":"Stigma","valence":"neg"}],"key":{"a":"support","b":"stigma","c":"support","d":"stigma","e":"support","f":"stigma"},"relearn":"Everyone's future and questions are valid; 'not for people like you' is stigma, not truth.","persona":"Arjun","source":"inclusive"},
  {"id":"mc-1221","cat":"my-future-no-pressure","type":"role-play","hook":"A friend keeps saying you're 'behind' for not dating yet.","setup":"They tease you again about being 'the only single one'. What do you say?","yourLine":[{"text":"\"I'm on my own timeline, and it's working for me.\"","best":true},{"text":"\"Yeah, I guess I should hurry up.\""}],"relearn":"You can name your own timeline plainly; 'behind' is a label, not a fact.","persona":"Vijay","source":"pressure-free"},
  {"id":"mc-1222","cat":"my-future-no-pressure","type":"role-play","hook":"A partner calls you a prude for wanting to wait.","setup":"They use the word to needle you. How do you hold your line?","yourLine":[{"text":"\"That's a label, not a reason. I'm not ready, and I need that respected.\"","best":true},{"text":"\"Fine, don't call me that, maybe later.\""}],"relearn":"A shame label isn't a reason; you can hold your boundary and ask to be respected.","persona":"Sneha","source":"delaying respected"},
  {"id":"mc-1223","cat":"my-future-no-pressure","type":"role-play","hook":"A relative pushes you to 'settle down' before your studies are done.","setup":"At a family lunch they bring it up again. What's a calm, firm reply?","yourLine":[{"text":"\"I hear you, but whether and when is my call, and I'm building my studies first.\"","best":true},{"text":"\"Maybe you're right, I shouldn't think about my studies.\""}],"relearn":"You can hear family out and still hold that whether and when are your call.","persona":"Sneha","source":"autonomy / family"},
  {"id":"mc-1224","cat":"my-future-no-pressure","type":"role-play","hook":"Someone says 'if you really cared, you wouldn't make me wait'.","setup":"They tie your feelings to giving in. What do you say back?","yourLine":[{"text":"\"Caring doesn't mean a deadline. I'm not ready, and that stands.\"","best":true},{"text":"\"I don't want you to doubt me, so okay.\""}],"relearn":"'If you cared' is guilt, not a reason; caring doesn't override your readiness.","persona":"any","source":"pressure-free"},
  {"id":"mc-1225","cat":"my-future-no-pressure","type":"role-play","hook":"A classmate mocks you for reading up on contraception.","setup":"They laugh and call it weird. How do you respond?","yourLine":[{"text":"\"Knowing my options is smart, not weird. I'd rather be informed.\"","best":true},{"text":"\"Ugh, fine, I'll stop looking it up.\""}],"relearn":"Seeking accurate information is the mature move, not something to be mocked for.","persona":"Arjun","source":"maturity"},
  {"id":"mc-1226","cat":"my-future-no-pressure","type":"role-play","hook":"You're being rushed: 'decide right now or the moment's gone'.","setup":"They want an answer this second. What do you say?","yourLine":[{"text":"\"A real choice isn't rushed. If it can't wait for me to be sure, the answer's no.\"","best":true},{"text":"\"Okay, okay, I'll just say yes then.\""}],"relearn":"You can refuse a rushed deadline; a real choice isn't decided under pressure.","persona":"any","source":"decision skill"},
  {"id":"mc-1227","cat":"my-future-no-pressure","type":"role-play","hook":"A friend is being shamed for waiting, and looks to you.","setup":"The group is piling on. What do you say to back them up?","yourLine":[{"text":"\"Their pace is theirs. Waiting is completely valid, drop it.\"","best":true},{"text":"\"I mean, maybe they are a bit slow about it.\""}],"relearn":"You can back a friend's right to wait; their pace is theirs and fully valid.","persona":"any","source":"pressure-free"},
  {"id":"mc-1228","cat":"my-future-no-pressure","type":"role-play","hook":"An older person says 'you're mature for your age, so this is fine'.","setup":"It feels off. What do you say, and what do you do next?","yourLine":[{"text":"\"No, this isn't okay. I'm going to talk to a trusted adult about it.\"","best":true},{"text":"\"I guess if you think I'm mature, it's fine.\""}],"relearn":"An older person pushing this is a flag; step back and tell a trusted adult.","persona":"Counsellor","source":"safeguarding"},
  {"id":"mc-1229","cat":"my-future-no-pressure","type":"match","hook":"Match each pressure line to what's really going on.","pairs":[{"left":"\"Everyone's doing it\"","right":"Peer pressure dressed as a fact"},{"left":"\"If you loved me, you would\"","right":"Guilt used to override your no"},{"left":"\"Decide right now\"","right":"Rushing a choice that needs time"},{"left":"\"You'd be a prude to wait\"","right":"A shame label, not a reason"},{"left":"\"The family decides this\"","right":"Taking your own timeline away"}],"relearn":"Each pressure line has a tactic behind it; naming it makes it easier to refuse.","persona":"any","source":"spot pressure"},
  {"id":"mc-1230","cat":"my-future-no-pressure","type":"match","hook":"Match each pressure tactic to the steady reply.","pairs":[{"left":"Guilt-trip","right":"\"Caring isn't a deadline\""},{"left":"Rushing","right":"\"A real choice isn't hurried\""},{"left":"Shame label","right":"\"That's a label, not a reason\""},{"left":"'Everyone's doing it'","right":"\"I'm on my own timeline\""},{"left":"Deciding for you","right":"\"Whether and when is my call\""}],"relearn":"Each pressure tactic has a calm, steady line that keeps the choice yours.","persona":"any","source":"pressure-free"},
  {"id":"mc-1231","cat":"my-future-no-pressure","type":"match","hook":"Match each move to whether it respects your autonomy.","pairs":[{"left":"Full, accurate information","right":"Respects your autonomy"},{"left":"Scare tactics","right":"Undermines it with fear"},{"left":"Space to decide","right":"Lets the choice be yours"},{"left":"Guilt and labels","right":"Pushes you off your values"},{"left":"Your free, owned choice","right":"The whole point"}],"relearn":"Information and space respect autonomy; scares, guilt and labels undermine it.","persona":"any","source":"autonomy"},
  {"id":"mc-1232","cat":"my-future-no-pressure","type":"match","hook":"Match each sign to what it tells you about a choice.","pairs":[{"left":"You can explain your reasons","right":"It's grounded in your values"},{"left":"You'd choose it unobserved","right":"It's genuinely yours"},{"left":"You're avoiding disappointment","right":"It's leaning on pleasing others"},{"left":"You feel rushed","right":"It needs more time"},{"left":"It matches what you want","right":"It's worth owning"}],"relearn":"Reasoned, unobserved, values-led choices are yours; rushed or people-pleasing ones aren't yet.","persona":"any","source":"autonomy"},
  {"id":"mc-1233","cat":"my-future-no-pressure","type":"match","hook":"Match each idea to its plain meaning here.","pairs":[{"left":"Autonomy","right":"The choice is genuinely yours"},{"left":"No pressure in any direction","right":"Neither pushed nor shamed"},{"left":"Maturity","right":"Asking and owning your choice"},{"left":"Waiting","right":"A valid, certain option"},{"left":"Informed choice","right":"Decided with real facts"}],"relearn":"Autonomy, no-pressure, maturity, waiting and informed choice each have a plain meaning here.","persona":"any","source":"consolidation"},
  {"id":"mc-1234","cat":"my-future-no-pressure","type":"match","hook":"Match each part of your future to who gets to shape it.","pairs":[{"left":"Your studies and work","right":"Yours to plan"},{"left":"Who you're close to","right":"Yours to choose"},{"left":"Whether and when","right":"Your own timeline"},{"left":"What others want for you","right":"Advice, not a verdict"},{"left":"The final decision","right":"Stays with you"}],"relearn":"Your studies, relationships and timeline are yours to shape; others advise, you decide.","persona":"any","source":"agency"},
  {"id":"mc-1235","cat":"my-future-no-pressure","type":"match","hook":"Match each phrase to whether it's support or pressure.","pairs":[{"left":"\"It's your call\"","right":"Hands you the choice"},{"left":"\"Don't be the last one\"","right":"Pressure"},{"left":"\"Take your time\"","right":"Gives you space"},{"left":"\"You'll regret waiting\"","right":"A scare tactic"},{"left":"\"Either way is fine\"","right":"Reassurance"}],"relearn":"Lines that give you the choice and space are support; rushing and scares are pressure.","persona":"any","source":"pressure-free"},
  {"id":"mc-1236","cat":"my-future-no-pressure","type":"match","hook":"Match each reaction to a choice with what it really is.","pairs":[{"left":"Giving you facts and space","right":"Respect"},{"left":"Shaming your decision","right":"Pressure"},{"left":"Backing whatever you pick","right":"Real support"},{"left":"Making you feel behind","right":"A push"},{"left":"Asking what you want","right":"Care"}],"relearn":"Facts, space and backing your choice are respect; shaming or 'falling behind' is pressure.","persona":"any","source":"pressure-free"},
  {"id":"mc-1237","cat":"my-future-no-pressure","type":"branch","hook":"A partner keeps hinting you're 'behind' for not being ready. What do you do?","options":[{"text":"Hold your pace; 'behind' is pressure, not a fact","consequence":"You keep your readiness as your own to decide.","outcome":"own-pace","best":true},{"text":"Go along so you don't seem behind","consequence":"'Behind' is a pressure label; your pace is yours, and waiting is valid."}],"debrief":"Readiness is personal; 'everyone's ahead' is pressure, not a deadline.","relearn":"Decide by your own readiness; 'you're behind' is a push, not a fact.","persona":"Vijay","source":"pressure-free"},
  {"id":"mc-1238","cat":"my-future-no-pressure","type":"branch","hook":"You notice you're about to say yes mainly to stop the gossip about you. What now?","options":[{"text":"Pause and re-decide from your own values","consequence":"You take the choice back as genuinely your own.","outcome":"self-owned","best":true},{"text":"Go ahead so people stop talking","consequence":"A choice made to silence others isn't yours; pause and decide from your values."}],"debrief":"If you're choosing mainly to please or quiet others, pause and reclaim it.","relearn":"If a choice is mainly to please others, pause and re-decide from your values.","persona":"any","source":"autonomy"},
  {"id":"mc-1239","cat":"my-future-no-pressure","type":"branch","hook":"Family wants you to marry soon; you'd rather finish your studies first. What do you do?","options":[{"text":"Respectfully hold that whether and when are your call","consequence":"You keep ownership of your timeline while hearing them out.","outcome":"autonomy","best":true},{"text":"Drop your plans because they expect it","consequence":"Whether and when stay yours to decide freely, even with family input."}],"debrief":"You can value family and still keep your timeline as your own.","relearn":"You can respect family input while holding whether and when as your choice.","persona":"Sneha","source":"autonomy / family"},
  {"id":"mc-1240","cat":"my-future-no-pressure","type":"branch","hook":"You're unsure and want to choose well, but everyone's offering loud opinions. What helps most?","options":[{"text":"Gather facts, check your values, then decide unhurried","consequence":"Your choice rests on real information and your own values.","outcome":"informed","best":true},{"text":"Just pick whatever the loudest person wants","consequence":"Decide from facts and your values, not whoever is loudest."}],"debrief":"Facts, your values and time are how a choice becomes calmly yours.","relearn":"Gather facts, check your values and take your time; loud opinions aren't a basis.","persona":"any","source":"decision skill"},
  {"id":"mc-1241","cat":"my-future-no-pressure","type":"branch","hook":"A friend is being shamed in a group chat for choosing to wait. What do you do?","options":[{"text":"Back them up: their pace is theirs and waiting is valid","consequence":"You help keep the space pressure-free for everyone.","outcome":"ally","best":true},{"text":"Stay quiet so the group doesn't turn on you","consequence":"Backing a friend's right to wait is how we keep this pressure-free."}],"debrief":"Standing up for a friend's pace protects everyone's right to choose freely.","relearn":"Backing a friend's right to wait keeps the space pressure-free for all.","persona":"any","source":"pressure-free"},
  {"id":"mc-1242","cat":"my-future-no-pressure","type":"branch","hook":"You're being told 'decide tonight or never'. The choice feels too big to rush. What now?","options":[{"text":"Refuse the deadline; a real choice isn't rushed","consequence":"You protect your right to decide unhurried, or to say no.","outcome":"unrushed","best":true},{"text":"Give a quick yes to end the pressure","consequence":"'Now or never' is a tactic; a real choice isn't rushed, take your time."}],"debrief":"Manufactured urgency is pressure; you can always take the time you need.","relearn":"'Decide now or never' is a tactic; a real choice isn't rushed.","persona":"any","source":"decision skill"},
  {"id":"mc-1243","cat":"my-future-no-pressure","type":"branch","hook":"You want to ask a clinic something but worry it makes you look immature. What do you do?","options":[{"text":"Ask anyway; getting the facts is what maturity looks like","consequence":"You make your choice on real, accurate information.","outcome":"informed","best":true},{"text":"Skip it and guess from rumours","consequence":"Asking for accurate facts is mature; rumours leave you guessing."}],"debrief":"Seeking accurate information and asking is exactly what maturity looks like.","relearn":"Asking a clinic is the mature move; it informs your own free choice.","persona":"Arjun","source":"maturity"},
  {"id":"mc-1244","cat":"my-future-no-pressure","type":"branch","hook":"An older person you barely know pushes a relationship and says to keep it secret. What do you do?","options":[{"text":"Step back and tell a trusted adult about it","consequence":"You stay safe and get support from someone you trust.","outcome":"safeguard","best":true},{"text":"Keep it quiet like they asked","consequence":"Pressure plus secrecy from an older person is a flag; tell a trusted adult."}],"debrief":"This is a flag, never your fault. Tell a trusted adult or call Childline 1098.","relearn":"Older-person pressure plus 'keep it secret' is a flag; step back and tell someone.","persona":"Counsellor","source":"safeguarding"},
  {"id":"mc-1245","cat":"my-future-no-pressure","type":"sort","hook":"Sort: a choice that's truly yours, or one that's really someone else's?","items":[{"id":"a","text":"You decided after getting the facts"},{"id":"b","text":"A partner decided and you went along"},{"id":"c","text":"You chose by your own values"},{"id":"d","text":"Friends shamed you into it"},{"id":"e","text":"You took the time you needed"},{"id":"f","text":"Family pressure made the call"}],"bins":[{"id":"yours","label":"Truly yours","valence":"pos"},{"id":"theirs","label":"Really theirs","valence":"neg"}],"key":{"a":"yours","b":"theirs","c":"yours","d":"theirs","e":"yours","f":"theirs"},"relearn":"A choice is yours when you decide it with facts, your values and time; not when others push it.","persona":"any","source":"autonomy"},
  {"id":"mc-1260","cat":"talk-it-through","type":"role-play","hook":"You want to bring up protection before things go further with a partner.","setup":"Calm and direct. Say:","yourLine":[{"text":"\"Before anything, I want us to be clear we'll use protection. Okay?\"","best":true},{"text":"Stay quiet and hope they raise it"}],"relearn":"Naming protection first, clearly, is the mature move.","persona":"Vijay","source":"partner communication"},
  {"id":"mc-1261","cat":"talk-it-through","type":"role-play","hook":"A partner says using a condom 'means you don't trust me'.","setup":"Hold the line, kindly. Say:","yourLine":[{"text":"\"Protection is about health, not trust. It stays, and that's me caring.\"","best":true},{"text":"Apologise and drop it so they aren't upset"}],"relearn":"\"You don't trust me\" is manipulation; protection is a health choice, not a loyalty test.","persona":"any","source":"manipulation lines"},
  {"id":"mc-1262","cat":"talk-it-through","type":"role-play","hook":"You're at a clinic and want to ask about your options without being judged.","setup":"Just ask plainly. Say:","yourLine":[{"text":"\"I'd like to understand my contraception options. Can you walk me through them?\"","best":true},{"text":"Pretend you're only there for something else"}],"relearn":"Clinicians are there to inform, not judge; asking is routine care.","persona":"Arjun","source":"clinician communication"},
  {"id":"mc-1263","cat":"talk-it-through","type":"role-play","hook":"You want to check that what you tell the clinic stays private.","setup":"Ask it straight. Say:","yourLine":[{"text":"\"Before we start, is what I share here kept confidential?\"","best":true},{"text":"Hold back the real question in case it's repeated"}],"relearn":"It's your right to ask plainly what stays private before you share.","persona":"any","source":"confidentiality"},
  {"id":"mc-1264","cat":"talk-it-through","type":"role-play","hook":"A partner keeps changing the subject every time protection comes up.","setup":"Name it gently. Say:","yourLine":[{"text":"\"I notice we keep dodging this. I need us to actually talk it through.\"","best":true},{"text":"Let it slide again and move on"}],"relearn":"Naming the dodge, kindly, brings the talk back on track.","persona":"Sneha","source":"partner communication"},
  {"id":"mc-1265","cat":"talk-it-through","type":"role-play","hook":"You want to tell a partner you'd rather wait, without it sounding like rejection.","setup":"Honest and warm. Say:","yourLine":[{"text":"\"I like you. I'm just not ready yet, and I need that to be okay.\"","best":true},{"text":"Make an excuse so you don't have to say it"}],"relearn":"You can say you'd rather wait warmly and still ask for respect.","persona":"any","source":"boundaries"},
  {"id":"mc-1266","cat":"talk-it-through","type":"role-play","hook":"A doctor uses a term you didn't follow about a method.","setup":"Ask, no embarrassment. Say:","yourLine":[{"text":"\"Sorry, can you explain that in plain words? I want to understand it fully.\"","best":true},{"text":"Nod along and look it up later, unsure"}],"relearn":"Asking a clinician to explain plainly is normal and smart.","persona":"Vijay","source":"clinician communication"},
  {"id":"mc-1267","cat":"talk-it-through","type":"role-play","hook":"A partner wants to agree how you'll both handle protection going forward.","setup":"Make it a shared plan. Say:","yourLine":[{"text":"\"Let's pick a plan we both feel good about, and keep checking it's working.\"","best":true},{"text":"Leave it vague and sort it out later"}],"relearn":"A protection plan you both agree on is the goal, decided together.","persona":"any","source":"shared plan"},
  {"id":"mc-1268","cat":"talk-it-through","type":"role-play","hook":"You want to check, in the moment, that a partner genuinely wants to.","setup":"Ask for real. Say:","yourLine":[{"text":"\"Hey, are you okay with this, and do you actually want to right now?\"","best":true},{"text":"Assume their silence means yes"}],"relearn":"Checking genuine, ongoing consent in the moment is part of caring.","persona":"any","source":"consent (links g31)"},
  {"id":"mc-1269","cat":"talk-it-through","type":"role-play","hook":"A partner says 'we don't need protection, I'll be careful'.","setup":"Don't trade safety for a promise. Say:","yourLine":[{"text":"\"'Being careful' isn't a method. If we do this, we use protection.\"","best":true},{"text":"Take their word for it"}],"relearn":"Vague promises aren't protection; a real method is.","persona":"Vijay","source":"manipulation lines"},
  {"id":"mc-1270","cat":"talk-it-through","type":"role-play","hook":"You want to raise this with a partner but keep waiting for a 'perfect' moment.","setup":"Keep it simple. Say:","yourLine":[{"text":"\"Can we talk for a minute? There's something I want us to sort out honestly.\"","best":true},{"text":"Keep waiting for a perfect moment that never comes"}],"relearn":"A calm, simple opener beats waiting forever for the perfect moment.","persona":"Arjun","source":"communication"},
  {"id":"mc-1271","cat":"talk-it-through","type":"role-play","hook":"A pharmacist seems busy and you feel awkward asking for condoms.","setup":"Just ask, it's routine. Say:","yourLine":[{"text":"\"Could I get a pack of condoms, please?\"","best":true},{"text":"Leave without asking because it feels embarrassing"}],"relearn":"Buying condoms at a pharmacy is ordinary; asking plainly is fine.","persona":"any","source":"access"},
  {"id":"mc-1272","cat":"talk-it-through","type":"role-play","hook":"A partner pushes 'everyone does it, why are you making it a thing'.","setup":"Stay grounded. Say:","yourLine":[{"text":"\"What others do isn't the point. This is what I need to feel okay.\"","best":true},{"text":"Back down so you don't seem uptight"}],"relearn":"\"Everyone does it\" is pressure, not a reason; your needs still count.","persona":"Sneha","source":"pressure"},
  {"id":"mc-1273","cat":"talk-it-through","type":"role-play","hook":"You want to ask a clinician something but worry they'll tell your family.","setup":"Ask about privacy first. Say:","yourLine":[{"text":"\"Is this confidential between us? I'd like to ask freely.\"","best":true},{"text":"Skip the real question to be safe"}],"relearn":"Adolescent-friendly services are confidential; you can ask about that upfront.","persona":"Arjun","source":"confidentiality"},
  {"id":"mc-1274","cat":"talk-it-through","type":"role-play","hook":"A partner agrees to protection but jokes about 'forgetting' it next time.","setup":"Keep it firm, light tone. Say:","yourLine":[{"text":"\"No 'forgetting'. It's every time, or not at all. Deal?\"","best":true},{"text":"Laugh it off and let it slide"}],"relearn":"Protection is every time; a joke about skipping it still needs a clear line.","persona":"any","source":"consistency"},
  {"id":"mc-1275","cat":"talk-it-through","type":"role-play","hook":"You want to support a friend who's nervous to ask a doctor about contraception.","setup":"Reassure them. Say:","yourLine":[{"text":"\"It's routine care, they won't judge you. Want to practise the words first?\"","best":true},{"text":"\"Yeah, it's probably too awkward, just skip it.\""}],"relearn":"Asking a doctor is routine; helping a friend rehearse makes it easier.","persona":"Vijay","source":"peer support"},
  {"id":"mc-1276","cat":"talk-it-through","type":"role-play","hook":"A partner says talking about protection 'kills the mood'.","setup":"Reframe it, warmly. Say:","yourLine":[{"text":"\"A two-minute talk so we both feel safe? That keeps the mood, not breaks it.\"","best":true},{"text":"Skip the talk to keep things smooth"}],"relearn":"A short, caring talk protects both of you; it isn't a mood-killer.","persona":"any","source":"partner communication"},
  {"id":"mc-1277","cat":"talk-it-through","type":"role-play","hook":"You realise mid-conversation you actually don't want to go further tonight.","setup":"Say so, kindly. Say:","yourLine":[{"text":"\"Actually, I've changed my mind for now, and I need you to be okay with that.\"","best":true},{"text":"Go ahead anyway to avoid the awkwardness"}],"relearn":"You can change your mind at any point; consent is ongoing.","persona":"any","source":"consent (links g31)"},
  {"id":"mc-1278","cat":"talk-it-through","type":"role-play","hook":"You want to ask a clinic where to get emergency contraception, just in case.","setup":"Ask directly. Say:","yourLine":[{"text":"\"Where can I get emergency contraception if I ever need it quickly?\"","best":true},{"text":"Decide it's too embarrassing to ask"}],"relearn":"Asking where to get EC is sensible, plain, routine information.","persona":"any","source":"access"},
  {"id":"mc-1279","cat":"talk-it-through","type":"role-play","hook":"A partner gets defensive when you suggest you both get checked for STIs.","setup":"Keep it mutual. Say:","yourLine":[{"text":"\"This isn't about blame. Getting checked together is just looking after each other.\"","best":true},{"text":"Drop it so they don't feel accused"}],"relearn":"Suggesting a check-up together is care, not accusation.","persona":"any","source":"shared plan"},
  {"id":"mc-1280","cat":"talk-it-through","type":"role-play","hook":"You want to tell a partner the boundary is firm even though you like them a lot.","setup":"Both things at once. Say:","yourLine":[{"text":"\"I really care about you, and protection still isn't optional for me.\"","best":true},{"text":"Soften the boundary so they don't doubt your feelings"}],"relearn":"Caring and keeping a boundary go together; the boundary stays.","persona":"Sneha","source":"boundaries"},
  {"id":"mc-1281","cat":"talk-it-through","type":"role-play","hook":"A clinician asks if you have questions and your mind goes blank.","setup":"Give yourself room. Say:","yourLine":[{"text":"\"Can I take a moment? I want to make sure I ask what I came for.\"","best":true},{"text":"Say 'no questions' and leave unsure"}],"relearn":"It's fine to pause and gather your questions with a clinician.","persona":"Vijay","source":"clinician communication"},
  {"id":"mc-1282","cat":"talk-it-through","type":"role-play","hook":"A partner says 'if you loved me you'd do this now'.","setup":"Name the move. Say:","yourLine":[{"text":"\"Love isn't a test you set me. I decide what I'm ready for.\"","best":true},{"text":"Give in to prove how you feel"}],"relearn":"\"If you loved me\" is pressure; love never demands you cross your own line.","persona":"any","source":"manipulation lines"},
  {"id":"mc-1283","cat":"talk-it-through","type":"role-play","hook":"You want to agree with a partner what you'll do if a condom ever splits.","setup":"Plan ahead together. Say:","yourLine":[{"text":"\"If protection ever fails, let's agree we'll sort out EC quickly. Okay?\"","best":true},{"text":"Assume it'll never happen and not discuss it"}],"relearn":"Agreeing a backup plan, like EC if protection fails, is grown-up forethought.","persona":"any","source":"shared plan"},
  {"id":"mc-1284","cat":"talk-it-through","type":"role-play","hook":"A friend keeps quiet at the clinic and lets you do all the asking.","setup":"Hand them the words. Say:","yourLine":[{"text":"\"Your turn, just ask the doctor what you wanted to. They've heard it all.\"","best":true},{"text":"Ask their questions for them so they don't have to"}],"relearn":"Encouraging a friend to ask for themselves builds the skill.","persona":"Vijay","source":"peer support"},
  {"id":"mc-1285","cat":"talk-it-through","type":"role-play","hook":"A partner agrees to talk but only over text, where it gets misread.","setup":"Move it to a calmer space. Say:","yourLine":[{"text":"\"Can we talk in person, somewhere private? This matters more than texting.\"","best":true},{"text":"Keep arguing it out over text"}],"relearn":"A calm, private, face-to-face moment beats a tense text thread.","persona":"Arjun","source":"communication"},
  {"id":"mc-1286","cat":"talk-it-through","type":"role-play","hook":"You want to thank a partner who actually listened and agreed on a plan.","setup":"Acknowledge it. Say:","yourLine":[{"text":"\"Thanks for taking this seriously with me. That's exactly how I hoped we'd do it.\"","best":true},{"text":"Say nothing and just feel relieved"}],"relearn":"Naming it when a partner listens well reinforces respectful talks.","persona":"any","source":"partner communication"},
  {"id":"mc-1287","cat":"talk-it-through","type":"role-play","hook":"A partner says 'let's just figure protection out in the moment'.","setup":"Sort it before, not during. Say:","yourLine":[{"text":"\"I'd rather have this sorted beforehand than scramble in the moment.\"","best":true},{"text":"Agree to wing it later"}],"relearn":"Agreeing protection beforehand beats improvising under pressure.","persona":"Sneha","source":"partner communication"},
  {"id":"mc-1288","cat":"talk-it-through","type":"branch","hook":"A partner flatly refuses to even discuss protection and seems annoyed you asked.","options":[{"text":"Treat refusing the talk as a serious flag and don't proceed unprotected","consequence":"You hold your health and your standards.","outcome":"safe","best":true},{"text":"Let it go so they don't get more annoyed","consequence":"Refusing to even discuss protection is a real flag; don't proceed unprotected."}],"debrief":"A partner who won't discuss protection at all isn't respecting your health.","relearn":"Refusing the protection talk is a serious flag; don't go ahead unprotected.","persona":"any","source":"red flags"},
  {"id":"mc-1289","cat":"talk-it-through","type":"branch","hook":"You want to ask a doctor about contraception but worry it's 'not allowed' at your age.","options":[{"text":"Go to an adolescent-friendly clinic and ask; the info is yours by right","consequence":"You get confidential, judgment-free answers.","outcome":"informed","best":true},{"text":"Skip it, assuming you need a parent's permission","consequence":"You don't need permission; these services give info confidentially."}],"debrief":"You can ask for contraception information confidentially, no permission needed.","relearn":"You can ask a clinician for information, confidentially.","persona":"Arjun","source":"access-and-rights"},
  {"id":"mc-1290","cat":"talk-it-through","type":"branch","hook":"A partner agrees to protection out loud but you sense they don't mean it.","options":[{"text":"Pause and check it's a real yes, not just words to move things along","consequence":"You confirm you're genuinely on the same page.","outcome":"checked","best":true},{"text":"Take the spoken yes and leave it there","consequence":"A real agreement is genuine, not just words; it's fine to check it's real."}],"debrief":"Agreement that feels hollow is worth checking; you want a real yes.","relearn":"Check that a partner's 'yes' to a plan is genuine, not just smoothing things over.","persona":"any","source":"shared plan"},
  {"id":"mc-1291","cat":"talk-it-through","type":"branch","hook":"You froze and didn't ask the doctor your real question. You're now home.","options":[{"text":"Book another visit, or call the clinic, and ask it this time","consequence":"You still get the answer you came for.","outcome":"persist","best":true},{"text":"Decide it's too late and give up on asking","consequence":"You can always go back; clinics expect follow-up questions."}],"debrief":"Freezing once is normal; you can return and ask plainly.","relearn":"If you froze at the clinic, go back and ask; that's normal and welcome.","persona":"Vijay","source":"clinician communication"},
  {"id":"mc-1292","cat":"talk-it-through","type":"branch","hook":"A partner says talking about all this is 'too serious' for where you are.","options":[{"text":"Say a short honest talk is exactly what 'serious enough to do this' means","consequence":"You set a fair, mature standard together.","outcome":"standard","best":true},{"text":"Agree it's too serious and skip the talk","consequence":"If you're close enough to consider this, you're close enough to talk about it."}],"debrief":"Being close enough to act is being close enough to talk it through.","relearn":"If it's serious enough to do, it's serious enough to talk about.","persona":"Sneha","source":"partner communication"},
  {"id":"mc-1293","cat":"talk-it-through","type":"branch","hook":"You want a method but don't know where to even start the conversation about access.","options":[{"text":"Ask at an adolescent-friendly clinic (Ujala) how to get started","consequence":"You reach the right, confidential service.","outcome":"routed","best":true},{"text":"Rely on what a group chat told you","consequence":"A clinic or AFHC gives accurate, confidential guidance; group chats don't."}],"debrief":"For real options and access, an AFHC or doctor is where to start.","relearn":"Start with an adolescent-friendly clinic or doctor, not rumour, for access.","persona":"any","source":"access-and-rights"},
  {"id":"mc-1294","cat":"talk-it-through","type":"branch","hook":"A partner agrees to protection but only if you 'don't make it weird by talking about it'.","options":[{"text":"Say a calm, clear talk is part of the deal; that's not weird","consequence":"You keep the conversation that keeps you both safe.","outcome":"open","best":true},{"text":"Agree to stay silent to keep them comfortable","consequence":"Silencing the talk isn't the goal; a calm conversation is how it works well."}],"debrief":"Talking it through openly is the healthy way, not 'weird'.","relearn":"An open, calm talk is part of doing this well, not something to silence.","persona":"any","source":"comms"},
  {"id":"mc-1295","cat":"talk-it-through","type":"branch","hook":"A friend tells you a partner laughed off their protection request. They feel small.","options":[{"text":"Tell them the request was right, and help them say it once more, firmly","consequence":"They feel backed and ready to hold the line.","outcome":"support","best":true},{"text":"Tell them to just let it go to avoid conflict","consequence":"The request was reasonable; support them to repeat it clearly."}],"debrief":"A reasonable protection request stands; back your friend to restate it.","relearn":"Back a friend whose fair protection request was brushed off.","persona":"Vijay","source":"peer support"},
  {"id":"mc-1296","cat":"talk-it-through","type":"branch","hook":"You want to bring protection up but you're scared they'll think you assume too much.","options":[{"text":"Frame it as 'if we ever do', so it's a plan, not an assumption","consequence":"You open the talk without pressure either way.","outcome":"framed","best":true},{"text":"Say nothing, in case it sounds presumptuous","consequence":"An 'if we ever' framing keeps it pressure-free and still gets it discussed."}],"debrief":"\"If we ever do this\" makes the talk easy and assumes nothing.","relearn":"Frame the protection talk as 'if we ever' so it's a plan, not a demand.","persona":"Arjun","source":"partner communication"},
  {"id":"mc-1297","cat":"talk-it-through","type":"branch","hook":"A partner suddenly says they'd rather not use protection 'this once'.","options":[{"text":"Hold the line: it's every time or not this time","consequence":"You keep both of you protected, no exceptions.","outcome":"firm","best":true},{"text":"Agree, since it's 'just once'","consequence":"'Just once' is how slips happen; protection is every time."}],"debrief":"\"Just this once\" still means unprotected; the rule holds every time.","relearn":"\"Just this once\" isn't an exception; protection means every time.","persona":"any","source":"consistency"},
  {"id":"mc-1298","cat":"talk-it-through","type":"branch","hook":"You want to ask a clinician about your options but the waiting room feels exposed.","options":[{"text":"Ask the staff if you can speak privately for your questions","consequence":"You get to ask freely, out of earshot.","outcome":"private","best":true},{"text":"Whisper a half-question and leave without real answers","consequence":"You can ask for a private word; clinics expect that."}],"debrief":"You can request a private space to ask your real questions.","relearn":"Ask staff for a private word so you can speak freely at a clinic.","persona":"any","source":"confidentiality"},
  {"id":"mc-1299","cat":"talk-it-through","type":"branch","hook":"A partner agrees on a method but you realise neither of you actually has it ready.","options":[{"text":"Sort out getting it from a pharmacy or clinic before, not after","consequence":"The plan is real, not just talk.","outcome":"ready","best":true},{"text":"Figure it's fine and deal with it whenever","consequence":"A plan only protects if the method is actually on hand; get it first."}],"debrief":"Agreeing a method means actually getting it ready beforehand.","relearn":"Make a protection plan real by getting the method ready in advance.","persona":"Vijay","source":"shared plan"},
  {"id":"mc-1300","cat":"talk-it-through","type":"branch","hook":"You want to talk to a partner but only ever catch them around friends.","options":[{"text":"Ask for a calm, private moment just the two of you","consequence":"The talk gets the space it needs to go well.","outcome":"private","best":true},{"text":"Blurt it out in front of everyone","consequence":"A private, calm moment is where this conversation works best."}],"debrief":"Start this talk in a calm, private moment, simply and honestly.","relearn":"Pick a calm, private moment to start the conversation.","persona":"any","source":"communication"},
  {"id":"mc-1301","cat":"talk-it-through","type":"branch","hook":"A partner agrees to everything fast, then says 'so we don't need to keep checking, right?'","options":[{"text":"Say checking in stays open between you, every time","consequence":"You keep consent and the plan alive, not a one-off.","outcome":"ongoing","best":true},{"text":"Agree, to avoid seeming distrustful","consequence":"Consent and the plan are ongoing; checking in stays normal."}],"debrief":"Consent and protection aren't settled once; checking in stays open.","relearn":"Keep checking in; consent and the plan are ongoing, not a one-time deal.","persona":"any","source":"consent (links g31)"},
  {"id":"mc-1302","cat":"talk-it-through","type":"spot","hook":"Spot the two lines that pressure or manipulate, not the honest ones.","scene":[{"id":"a","text":"\"If you really cared, you'd skip the condom.\"","trick":true},{"id":"b","text":"\"Let's agree on protection we're both okay with.\"","trick":false},{"id":"c","text":"\"Tell me honestly if you're not ready.\"","trick":false},{"id":"d","text":"\"Everyone our age does it, don't be weird.\"","trick":true},{"id":"e","text":"\"We can stop any time you want.\"","trick":false}],"why":"\"If you cared\" and \"everyone does it\" are pressure lines; the others are honest and respectful.","relearn":"\"If you cared\" and \"everyone does it\" are manipulation; honest talk respects your choice.","persona":"any","source":"manipulation lines"},
  {"id":"mc-1303","cat":"talk-it-through","type":"spot","hook":"Spot the two red flags in how this partner handles the protection talk.","scene":[{"id":"a","text":"Refuses to discuss it and gets angry","trick":true},{"id":"b","text":"Asks what you'd both be comfortable with","trick":false},{"id":"c","text":"Mocks you for bringing it up","trick":true},{"id":"d","text":"Listens to what you're not ready for","trick":false},{"id":"e","text":"Suggests sorting a method together","trick":false}],"why":"Refusing to discuss and mocking you are the red flags; listening and planning together are good signs.","relearn":"Refusing the talk and mocking you are red flags; a good partner listens and plans with you.","persona":"any","source":"red flags"},
  {"id":"mc-1304","cat":"talk-it-through","type":"spot","hook":"Spot the two unsafe moves in how this person treats a clinic visit.","scene":[{"id":"a","text":"Trusts a forwarded message over the doctor","trick":true},{"id":"b","text":"Asks if the visit is confidential","trick":false},{"id":"c","text":"Skips the real question out of fear of judgment","trick":true},{"id":"d","text":"Asks the doctor to explain in plain words","trick":false},{"id":"e","text":"Books a follow-up to ask more","trick":false}],"why":"Trusting forwards over the doctor and hiding the real question are the unsafe moves; the rest are wise.","relearn":"Trusting rumour over a clinician, or hiding your real question, are the unsafe moves.","persona":"any","source":"clinician communication"},
  {"id":"mc-1305","cat":"talk-it-through","type":"spot","hook":"Spot the two lines that ignore consent, not the ones that check it.","scene":[{"id":"a","text":"\"You didn't say no, so it's fine.\"","trick":true},{"id":"b","text":"\"Are you actually okay with this?\"","trick":false},{"id":"c","text":"\"We can stop whenever you want.\"","trick":false},{"id":"d","text":"\"You agreed last time, so it's settled.\"","trick":true},{"id":"e","text":"\"Tell me if anything changes for you.\"","trick":false}],"why":"\"Didn't say no\" and \"agreed last time\" ignore ongoing consent; the others actively check it.","relearn":"Silence or a past yes isn't consent now; real consent is checked, ongoing.","persona":"any","source":"consent (links g31)"},
  {"id":"mc-1306","cat":"talk-it-through","type":"spot","hook":"Spot the two pressure lines about being 'ready', not the supportive ones.","scene":[{"id":"a","text":"\"You're being immature, just get it over with.\"","trick":true},{"id":"b","text":"\"Take all the time you need.\"","trick":false},{"id":"c","text":"\"It's totally fine to wait.\"","trick":false},{"id":"d","text":"\"Everyone's past this by now, hurry up.\"","trick":true},{"id":"e","text":"\"Your pace is yours to set.\"","trick":false}],"why":"\"Immature, get it over with\" and \"everyone's past this\" pressure you; the others respect your pace.","relearn":"Calling you immature or rushing you is pressure; waiting is valid and respected.","persona":"any","source":"pressure"},
  {"id":"mc-1307","cat":"talk-it-through","type":"spot","hook":"Spot the two manipulation tactics, not the fair requests.","scene":[{"id":"a","text":"Sulking until you give in","trick":true},{"id":"b","text":"Asking calmly what would make you comfortable","trick":false},{"id":"c","text":"Threatening to leave if you don't agree","trick":true},{"id":"d","text":"Accepting a 'not yet' without a fuss","trick":false},{"id":"e","text":"Offering to plan protection together","trick":false}],"why":"Sulking-to-win and threatening to leave are manipulation; the rest respect your answer.","relearn":"Sulking or threatening to leave to get a yes is manipulation, not negotiation.","persona":"Sneha","source":"manipulation lines"},
  {"id":"mc-1308","cat":"talk-it-through","type":"spot","hook":"Spot the two lines that wrongly skip protection, not the safe ones.","scene":[{"id":"a","text":"\"I'll be careful, we don't need a condom.\"","trick":true},{"id":"b","text":"\"Let's use protection every time.\"","trick":false},{"id":"c","text":"\"Just this once without is fine.\"","trick":true},{"id":"d","text":"\"If it ever fails, we'll sort EC quickly.\"","trick":false},{"id":"e","text":"\"Condoms also protect against STIs, let's use them.\"","trick":false}],"why":"\"I'll be careful\" and \"just this once\" skip real protection; the others keep you both safe.","relearn":"\"I'll be careful\" and \"just this once\" aren't protection; a method every time is.","persona":"Vijay","source":"consistency"},
  {"id":"mc-1309","cat":"talk-it-through","type":"spot","hook":"Spot the two lines that pressure secrecy, not the honest ones.","scene":[{"id":"a","text":"\"Don't tell anyone, especially a doctor.\"","trick":true},{"id":"b","text":"\"You can ask a clinic anything, privately.\"","trick":false},{"id":"c","text":"\"If you cared you'd keep this just between us.\"","trick":true},{"id":"d","text":"\"It's okay to get advice from someone you trust.\"","trick":false},{"id":"e","text":"\"Asking questions is a good thing.\"","trick":false}],"why":"Pushing secrecy and using 'care' to silence you are the flags; seeking advice is healthy.","relearn":"Pressuring you into total secrecy is a flag; seeking confidential help is your right.","persona":"any","source":"red flags"},
  {"id":"mc-1310","cat":"talk-it-through","type":"spot","hook":"Spot the two lines that pressure an under-18, not the protective ones.","scene":[{"id":"a","text":"Older person: \"Keep us secret from your family.\"","trick":true},{"id":"b","text":"\"If anyone pressures you, tell a trusted adult.\"","trick":false},{"id":"c","text":"Older person: \"You're mature, age doesn't matter.\"","trick":true},{"id":"d","text":"\"Waiting is completely valid at your age.\"","trick":false},{"id":"e","text":"\"You can step back any time you want.\"","trick":false}],"why":"An older person pushing secrecy or 'age doesn't matter' is a flag; the rest protect you.","relearn":"An older person pushing secrecy is a flag; tell a trusted adult.","persona":"any","source":"safeguarding (POCSO)"},
  {"id":"mc-1311","cat":"talk-it-through","type":"reflect","hook":"Lensy: having the words ready for a partner makes the talk far less scary. Worth practising?","prompt":"What do you think?","options":["Yes","I'll rehearse","Feels doable"],"affirm":"Rehearsing the words once means they're there when you actually need them.","relearn":"Having a line ready makes the protection talk much easier to start.","persona":"any","source":"communication"},
  {"id":"mc-1312","cat":"talk-it-through","type":"reflect","hook":"Lensy: 'I'm not ready, and I need you to respect that' is always a line you're allowed to use. Sit with that.","prompt":"What do you think?","options":["Always allowed","Good to know","Reassuring"],"affirm":"Your readiness is yours; that line is valid any time, no justification needed.","relearn":"\"I'm not ready, respect that\" is always a valid thing to say.","persona":"Sneha","source":"boundaries"},
  {"id":"mc-1313","cat":"talk-it-through","type":"reflect","hook":"Lensy: asking a doctor, even when it's awkward, is exactly what looking after yourself looks like. Agree?","prompt":"What do you think?","options":["Agree","That's maturity","I can do that"],"affirm":"Asking the awkward question anyway is what taking charge of your health looks like.","relearn":"Asking a clinician, awkward or not, is responsible self-care.","persona":"Arjun","source":"clinician communication"},
  {"id":"mc-1314","cat":"talk-it-through","type":"reflect","hook":"Lensy: a partner who'll genuinely talk this through with you is showing real care. Notice that?","prompt":"What do you think?","options":["Yes","Good sign","I see it"],"affirm":"A partner who talks it through honestly is showing the kind of care that matters.","relearn":"Willingness to talk protection through is a sign of a caring partner.","persona":"any","source":"partner communication"},
  {"id":"mc-1315","cat":"talk-it-through","type":"reflect","hook":"Lensy: checking 'do you actually want to?' isn't awkward, it's kind. Feel that?","prompt":"What do you think?","options":["It's kind","Makes sense","I'll ask"],"affirm":"Checking a partner genuinely wants to is care in action, never a mood-killer.","relearn":"Checking a partner genuinely wants to is kindness, not awkwardness.","persona":"any","source":"consent (links g31)"},
  {"id":"mc-1316","cat":"talk-it-through","type":"reflect","hook":"Lensy: you don't owe anyone a reason for your boundary, just the boundary. Sit with that.","prompt":"What do you think?","options":["I don't owe a reason","Good to hear","Freeing"],"affirm":"\"No\" and \"not yet\" are complete answers; you owe no explanation for them.","relearn":"You can hold a boundary without justifying it to anyone.","persona":"Sneha","source":"boundaries"},
  {"id":"mc-1317","cat":"talk-it-through","type":"reflect","hook":"Lensy: knowing you can walk into a clinic and ask, confidentially, is a quiet kind of power. Feel it?","prompt":"What do you think?","options":["Yes","Reassuring","Good to know"],"affirm":"Knowing where to go and what to ask is part of owning your own choices.","relearn":"Knowing you can ask a clinic confidentially is real, usable power.","persona":"any","source":"access-and-rights"},
  {"id":"mc-1318","cat":"talk-it-through","type":"strike-rewrite","hook":"\"Bringing up protection ruins the moment.\"","myth":{"un":"Bringing up protection ruins the moment.","re":"A short, honest talk is part of caring; it protects the moment, not spoils it.","why":"Feeling safe with each other is what lets the moment be good."},"relearn":"Talking protection through is caring, not a mood-killer.","persona":"any","source":"partner communication"},
  {"id":"mc-1319","cat":"talk-it-through","type":"strike-rewrite","hook":"\"Wanting to use a condom means you don't trust your partner.\"","myth":{"un":"Wanting a condom means you don't trust your partner.","re":"Protection is about health, not trust; you can fully trust someone and still use it.","why":"Health choices and trust are two separate things."},"relearn":"Protection is a health choice; it says nothing about trust.","persona":"any","source":"manipulation lines"},
  {"id":"mc-1320","cat":"talk-it-through","type":"strike-rewrite","hook":"\"A clinician won't keep what I tell them private.\"","myth":{"un":"A clinician will tell my family what I asked about.","re":"Consultations are confidential; what you share stays between you and the clinician.","why":"Confidentiality is part of how the care is meant to work."},"relearn":"Asking a clinician about contraception stays private from your family; they'll explain the one legal limit.","persona":"Arjun","source":"clinician communication"},
  {"id":"mc-1321","cat":"talk-it-through","type":"strike-rewrite","hook":"\"If you have to talk about it first, you're not really ready.\"","myth":{"un":"Needing to talk about it first means you're not ready.","re":"Talking it through is exactly what readiness looks like, not a sign against it.","why":"Thinking and agreeing beforehand is a mark of maturity."},"relearn":"Wanting to talk it through is a sign of readiness, not the opposite.","persona":"Sneha","source":"partner communication"},
  {"id":"mc-1322","cat":"talk-it-through","type":"strike-rewrite","hook":"\"Saying 'I'm not ready' will make them lose interest, so don't.\"","myth":{"un":"Saying 'I'm not ready' will make them lose interest.","re":"A partner worth your time respects 'not ready'; if they don't, that's the real signal.","why":"Respect for your pace is the bare minimum, not a bonus."},"relearn":"Saying you're not ready is valid; a good partner respects it.","persona":"any","source":"boundaries"},
  {"id":"mc-1323","cat":"talk-it-through","type":"strike-rewrite","hook":"\"Once you've agreed once, you can't change your mind later.\"","myth":{"un":"Once you've agreed, you can't change your mind.","re":"You can change your mind at any point; consent is ongoing, not a one-time signature.","why":"What you want can shift, and that's always allowed."},"relearn":"You can change your mind any time; consent is ongoing.","persona":"any","source":"consent (links g31)"},
  {"id":"mc-1324","cat":"talk-it-through","type":"strike-rewrite","hook":"\"You shouldn't bother a busy doctor with 'small' questions.\"","myth":{"un":"You shouldn't bother a busy doctor with small questions.","re":"Your questions about your own health are exactly what the visit is for.","why":"No health question you have is too small to ask."},"relearn":"Your health questions are never too small to ask a clinician.","persona":"Vijay","source":"clinician communication"},
  {"id":"mc-1325","cat":"talk-it-through","type":"strike-rewrite","hook":"\"Negotiating the method means you have to give up on protection.\"","myth":{"un":"Negotiating the method means giving up protection.","re":"You can discuss which method, but protection itself stays non-negotiable.","why":"How you protect each other is flexible; whether you do isn't."},"relearn":"You can negotiate the method, but protection itself stays.","persona":"Vijay","source":"negotiation"},
  {"id":"mc-1326","cat":"talk-it-through","type":"sort","hook":"Sort each line: opens the talk well, or shuts it down?","items":[{"id":"a","text":"\"Can we talk about how we'll keep each other safe?\""},{"id":"b","text":"\"Ugh, why are you making this awkward?\""},{"id":"c","text":"\"I want us both to feel okay about this.\""},{"id":"d","text":"\"Don't ruin the mood with that.\""},{"id":"e","text":"\"Tell me honestly what you're comfortable with.\""},{"id":"f","text":"\"Just drop it, it's not a big deal.\""}],"bins":[{"id":"open","label":"Opens it well","valence":"pos"},{"id":"shut","label":"Shuts it down","valence":"neg"}],"key":{"a":"open","b":"shut","c":"open","d":"shut","e":"open","f":"shut"},"relearn":"Calm, honest, mutual lines open the talk; mockery and 'drop it' shut it down.","persona":"any","source":"communication"},
  {"id":"mc-1327","cat":"talk-it-through","type":"sort","hook":"Sort each move: respects your boundary, or pressures past it?","items":[{"id":"a","text":"Accepts your 'not yet' calmly"},{"id":"b","text":"Sulks until you change your answer"},{"id":"c","text":"Asks what would make you comfortable"},{"id":"d","text":"Says you're immature for waiting"},{"id":"e","text":"Checks in before going further"},{"id":"f","text":"Guilt-trips you for saying no"}],"bins":[{"id":"respect","label":"Respects you","valence":"pos"},{"id":"pressure","label":"Pressures you","valence":"neg"}],"key":{"a":"respect","b":"pressure","c":"respect","d":"pressure","e":"respect","f":"pressure"},"relearn":"Accepting your answer and checking in respects you; sulking and guilt-tripping pressure you.","persona":"Sneha","source":"red flags"},
  {"id":"mc-1328","cat":"talk-it-through","type":"sort","hook":"Sort: a good way to ask a clinician, or a way that leaves you unsure?","items":[{"id":"a","text":"\"Can you explain my options in plain words?\""},{"id":"b","text":"Nodding along without understanding"},{"id":"c","text":"\"Is this kept confidential?\""},{"id":"d","text":"Guessing from a forwarded message instead"},{"id":"e","text":"\"Can I come back if I have more questions?\""},{"id":"f","text":"Leaving without asking the real thing"}],"bins":[{"id":"good","label":"Gets you answers","valence":"pos"},{"id":"unsure","label":"Leaves you unsure","valence":"neg"}],"key":{"a":"good","b":"unsure","c":"good","d":"unsure","e":"good","f":"unsure"},"relearn":"Asking plainly and about privacy gets answers; nodding along or relying on rumour doesn't.","persona":"any","source":"clinician communication"},
  {"id":"mc-1329","cat":"talk-it-through","type":"sort","hook":"Sort each line: honest and caring, or a manipulation?","items":[{"id":"a","text":"\"If you loved me you'd skip protection.\""},{"id":"b","text":"\"I want us both to be safe.\""},{"id":"c","text":"\"Everyone does it, don't be a child.\""},{"id":"d","text":"\"Tell me what you actually want.\""},{"id":"e","text":"\"You'll lose me if you say no.\""},{"id":"f","text":"\"We go at the pace you're okay with.\""}],"bins":[{"id":"honest","label":"Honest & caring","valence":"pos"},{"id":"manip","label":"Manipulation","valence":"neg"}],"key":{"a":"manip","b":"honest","c":"manip","d":"honest","e":"manip","f":"honest"},"relearn":"\"If you loved me\", \"everyone does it\" and \"you'll lose me\" are manipulation; honest lines respect you.","persona":"any","source":"manipulation lines"},
  {"id":"mc-1330","cat":"talk-it-through","type":"sort","hook":"Sort: checks consent, or assumes it?","items":[{"id":"a","text":"\"Are you okay with this right now?\""},{"id":"b","text":"\"You didn't say no, so it's fine.\""},{"id":"c","text":"\"Tell me if anything feels off.\""},{"id":"d","text":"\"You agreed before, so it's settled.\""},{"id":"e","text":"\"We can stop whenever you like.\""},{"id":"f","text":"Reading silence as a yes"}],"bins":[{"id":"checks","label":"Checks consent","valence":"pos"},{"id":"assumes","label":"Assumes it","valence":"neg"}],"key":{"a":"checks","b":"assumes","c":"checks","d":"assumes","e":"checks","f":"assumes"},"relearn":"Real consent is asked and ongoing; silence or a past yes isn't a yes now.","persona":"any","source":"consent (links g31)"},
  {"id":"mc-1331","cat":"talk-it-through","type":"sort","hook":"Sort: a green flag in how a partner handles this talk, or a red flag?","items":[{"id":"a","text":"Listens to what you're not ready for"},{"id":"b","text":"Refuses to discuss protection at all"},{"id":"c","text":"Plans a method together with you"},{"id":"d","text":"Mocks you for bringing it up"},{"id":"e","text":"Accepts a 'not yet' without sulking"},{"id":"f","text":"Threatens to leave to get a yes"}],"bins":[{"id":"green","label":"Green flag","valence":"pos"},{"id":"red","label":"Red flag","valence":"neg"}],"key":{"a":"green","b":"red","c":"green","d":"red","e":"green","f":"red"},"relearn":"Listening and planning together are green flags; refusing, mocking and threatening are red.","persona":"any","source":"red flags"},
  {"id":"mc-1332","cat":"talk-it-through","type":"sort","hook":"Sort: where to get accurate help, or where you'll just get rumour?","items":[{"id":"a","text":"An adolescent-friendly clinic (Ujala)"},{"id":"b","text":"A random forwarded message"},{"id":"c","text":"A doctor or pharmacist"},{"id":"d","text":"Gossip in a group chat"},{"id":"e","text":"Childline 1098 if someone pressures you"},{"id":"f","text":"A rumour from a senior"}],"bins":[{"id":"real","label":"Real, reliable help","valence":"pos"},{"id":"rumour","label":"Just rumour","valence":"neg"}],"key":{"a":"real","b":"rumour","c":"real","d":"rumour","e":"real","f":"rumour"},"relearn":"Clinics, doctors and Childline are real help; forwards and gossip are just rumour.","persona":"any","source":"access-and-rights"},
  {"id":"mc-1333","cat":"talk-it-through","type":"sort","hook":"Sort: a respectful response to 'I'm not ready', or a pressuring one?","items":[{"id":"a","text":"\"That's completely okay, no rush.\""},{"id":"b","text":"\"Stop being so dramatic about it.\""},{"id":"c","text":"\"Thanks for telling me honestly.\""},{"id":"d","text":"\"You'll regret making me wait.\""},{"id":"e","text":"\"We go at your pace.\""},{"id":"f","text":"\"Everyone else would've said yes.\""}],"bins":[{"id":"respect","label":"Respects it","valence":"pos"},{"id":"pressure","label":"Pressures you","valence":"neg"}],"key":{"a":"respect","b":"pressure","c":"respect","d":"pressure","e":"respect","f":"pressure"},"relearn":"\"No rush\" and \"your pace\" respect a 'not ready'; mockery and threats pressure it.","persona":"any","source":"boundaries"},
  {"id":"mc-1334","cat":"talk-it-through","type":"match","hook":"Match the tricky line to a clear, kind reply.","pairs":[{"left":"\"A condom means you don't trust me.\"","right":"\"It's about health, not trust.\""},{"left":"\"Everyone our age does it.\"","right":"\"What others do isn't my reason.\""},{"left":"\"Let's just figure it out in the moment.\"","right":"\"I'd rather sort it beforehand.\""},{"left":"\"Talking about it kills the mood.\"","right":"\"Two minutes so we both feel safe.\""},{"left":"\"If you loved me you'd say yes.\"","right":"\"Love doesn't set me a test.\""}],"relearn":"Every pressure line has a calm, clear reply that holds your boundary.","persona":"any","source":"manipulation lines"},
  {"id":"mc-1335","cat":"talk-it-through","type":"match","hook":"Match the goal to the line that gets you there.","pairs":[{"left":"Agree protection upfront","right":"\"If we ever do this, we use protection.\""},{"left":"Set your boundary","right":"\"I'm not ready yet, please respect that.\""},{"left":"Check genuine consent","right":"\"Do you actually want to, right now?\""},{"left":"Ask a clinician openly","right":"\"Help me understand my options.\""},{"left":"Keep a plan working","right":"\"Let's keep checking this works for us.\""}],"relearn":"Each goal in this talk has a simple, ready line that does the job.","persona":"any","source":"communication"},
  {"id":"mc-1336","cat":"talk-it-through","type":"match","hook":"Match the worry to where it actually gets answered.","pairs":[{"left":"\"Is my visit private?\"","right":"Ask the clinic directly"},{"left":"\"Which method fits me?\"","right":"A doctor or AFHC clinic"},{"left":"\"Where do I get condoms?\"","right":"A pharmacy"},{"left":"\"Someone is pressuring me.\"","right":"A trusted adult or Childline 1098"},{"left":"\"Is this rumour true?\"","right":"A reliable clinician, not forwards"}],"relearn":"Each worry has a real place to take it; rumour isn't one of them.","persona":"any","source":"access-and-rights"},
  {"id":"mc-1337","cat":"talk-it-through","type":"match","hook":"Match the moment to the consent check that fits it.","pairs":[{"left":"Before going further","right":"\"Are you okay with this?\""},{"left":"If they seem unsure","right":"\"We can stop any time.\""},{"left":"Something changed for you","right":"\"I've changed my mind for now.\""},{"left":"Checking it's real, not pressure","right":"\"Do you actually want to?\""},{"left":"Keeping it open","right":"\"Tell me if anything feels off.\""}],"relearn":"Consent has a line for every moment; it's checked, ongoing and honest.","persona":"any","source":"consent (links g31)"},
  {"id":"mc-1338","cat":"talk-it-through","type":"match","hook":"Match the partner behaviour to what it really signals.","pairs":[{"left":"Refuses to discuss protection","right":"A serious red flag"},{"left":"Plans a method with you","right":"Real care"},{"left":"Accepts 'not yet' calmly","right":"Respect for your pace"},{"left":"Guilt-trips you for asking","right":"Manipulation"},{"left":"Checks you're comfortable","right":"Healthy consent"}],"relearn":"Read the behaviour: refusal and guilt-trips are flags; planning and checking are care.","persona":"any","source":"red flags"},
  {"id":"mc-1339","cat":"talk-it-through","type":"match","hook":"Match the awkward feeling to the line that gets you past it.","pairs":[{"left":"Too shy to start","right":"\"Can we talk for a minute?\""},{"left":"Mind goes blank at the clinic","right":"\"Can I take a moment to think?\""},{"left":"Worried it sounds presumptuous","right":"\"If we ever do this...\""},{"left":"Afraid of being judged","right":"\"This is awkward, but I want to ask.\""},{"left":"Unsure it's confidential","right":"\"Is what I share kept private?\""}],"relearn":"Every awkward feeling has a simple line that moves you through it.","persona":"any","source":"communication"},
  {"id":"mc-1340","cat":"talk-it-through","type":"match","hook":"Match the situation to the assertive thing to say.","pairs":[{"left":"Partner jokes about 'forgetting' protection","right":"\"Every time, or not at all.\""},{"left":"Partner wants to skip it 'just once'","right":"\"Just once is how slips happen.\""},{"left":"Partner says you're overthinking","right":"\"This is what feeling safe needs.\""},{"left":"Partner pushes secrecy","right":"\"I can ask for advice if I want.\""},{"left":"Partner mocks the talk","right":"\"A short talk is part of doing this right.\""}],"relearn":"Each pushy situation has a calm, assertive line that keeps you safe.","persona":"any","source":"consistency"},
  {"id":"mc-1341","cat":"talk-it-through","type":"match","hook":"Match who can help with what, India-grounded.","pairs":[{"left":"Confidential SRH counselling","right":"Adolescent-friendly clinic (Ujala)"},{"left":"Condoms and EC","right":"A pharmacy"},{"left":"A prescribed method","right":"A doctor / family-planning service"},{"left":"Being pressured or exploited","right":"A trusted adult or Childline 1098"},{"left":"A health question you're unsure of","right":"A clinician, not a forward"}],"relearn":"Match the need to the right Indian service: clinic, pharmacy, doctor, or Childline.","persona":"any","source":"access-and-rights"},
  {"id":"mc-1350","cat":"the-full-picture","type":"sort","persona":"any","source":"effectiveness tiers (WHO)","hook":"Sort each method: needs nothing daily, or depends on remembering?","items":[{"id":"a","text":"Implant in the arm"},{"id":"b","text":"Copper IUD"},{"id":"c","text":"The daily pill"},{"id":"d","text":"Male condom each time"},{"id":"e","text":"Hormonal IUD"},{"id":"f","text":"Withdrawal ('pulling out')"}],"bins":[{"id":"larc","label":"Nothing to remember","valence":"pos"},{"id":"every","label":"Depends on every-time use","valence":"uhoh"}],"key":{"a":"larc","b":"larc","c":"every","d":"every","e":"larc","f":"every"},"relearn":"LARC (IUD, implant) works without a daily action; the pill, condoms and withdrawal depend on consistent use."},
  {"id":"mc-1351","cat":"the-full-picture","type":"sort","persona":"any","source":"dual protection (CDC)","hook":"Sort: protects against STIs too, or pregnancy only?","items":[{"id":"a","text":"Male condom"},{"id":"b","text":"The pill"},{"id":"c","text":"Implant"},{"id":"d","text":"Copper IUD"},{"id":"e","text":"Injectable"},{"id":"f","text":"Hormonal IUD"}],"bins":[{"id":"both","label":"Pregnancy + STIs","valence":"pos"},{"id":"preg","label":"Pregnancy only","valence":"uhoh"}],"key":{"a":"both","b":"preg","c":"preg","d":"preg","e":"preg","f":"preg"},"relearn":"Only the condom protects against STIs as well as pregnancy. That's dual protection."},
  {"id":"mc-1352","cat":"the-full-picture","type":"sort","persona":"Vijay","source":"access (RKSK/AFHC)","hook":"Sort: where you can actually get this, or not a real route?","items":[{"id":"a","text":"Condoms at a pharmacy"},{"id":"b","text":"Emergency pill at a pharmacy"},{"id":"c","text":"An implant fitted at an AFHC (Ujala) clinic"},{"id":"d","text":"A 'guaranteed' method from a friend's rumour"},{"id":"e","text":"The pill via a doctor"},{"id":"f","text":"A WhatsApp forward's 'home trick'"}],"bins":[{"id":"real","label":"A real source","valence":"pos"},{"id":"no","label":"Not a real source","valence":"neg"}],"key":{"a":"real","b":"real","c":"real","d":"no","e":"real","f":"no"},"relearn":"Pharmacy, doctor and AFHC (Ujala) clinics are real routes; rumours and forwards are not."},
  {"id":"mc-1353","cat":"the-full-picture","type":"sort","persona":"any","source":"emergency contraception (WHO)","hook":"Sort: true about the emergency pill, or a myth about it?","items":[{"id":"a","text":"Works best within 5 days of unprotected sex"},{"id":"b","text":"Mainly works by delaying ovulation"},{"id":"c","text":"It ends an existing pregnancy"},{"id":"d","text":"It's the same as an abortion"},{"id":"e","text":"You can get it at a pharmacy"},{"id":"f","text":"It's a backup, not a regular method"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"true","b":"true","c":"myth","d":"myth","e":"true","f":"true"},"relearn":"EC prevents pregnancy after sex, best within 5 days. It is not an abortion and won't end a pregnancy."},
  {"id":"mc-1354","cat":"the-full-picture","type":"sort","persona":"any","source":"reversibility (WHO)","hook":"Sort: reverses when you stop, or it's permanent?","items":[{"id":"a","text":"The pill"},{"id":"b","text":"The implant (once removed)"},{"id":"c","text":"The copper IUD (once removed)"},{"id":"d","text":"Male condom"},{"id":"e","text":"A surgical sterilisation"},{"id":"f","text":"The injectable (once stopped)"}],"bins":[{"id":"rev","label":"Reversible","valence":"pos"},{"id":"perm","label":"Meant to be permanent","valence":"neutral"}],"key":{"a":"rev","b":"rev","c":"rev","d":"rev","e":"perm","f":"rev"},"relearn":"These everyday methods are reversible. Fertility returns after stopping; only sterilisation is meant to be permanent."},
  {"id":"mc-1355","cat":"the-full-picture","type":"sort","persona":"any","source":"typical vs perfect use","hook":"Sort: raises real-life effectiveness, or lowers it?","items":[{"id":"a","text":"Using a condom every single time"},{"id":"b","text":"Taking the pill at the same time daily"},{"id":"c","text":"Skipping pills when you forget"},{"id":"d","text":"Reusing one condom"},{"id":"e","text":"Reading the method's leaflet"},{"id":"f","text":"Trusting a 'safe day' guess"}],"bins":[{"id":"up","label":"Raises it","valence":"pos"},{"id":"down","label":"Lowers it","valence":"neg"}],"key":{"a":"up","b":"up","c":"down","d":"down","e":"up","f":"down"},"relearn":"Consistent, correct, informed use is what makes a method actually effective in real life."},
  {"id":"mc-1356","cat":"the-full-picture","type":"sort","persona":"any","source":"method matching","hook":"Sort by the need: STI cover too, or pregnancy cover only?","items":[{"id":"a","text":"Condom"},{"id":"b","text":"Condom + the pill together"},{"id":"c","text":"The pill alone"},{"id":"d","text":"Implant alone"},{"id":"e","text":"Copper IUD alone"},{"id":"f","text":"Injectable alone"}],"bins":[{"id":"sti","label":"Covers STIs too","valence":"pos"},{"id":"preg","label":"Pregnancy cover only","valence":"uhoh"}],"key":{"a":"sti","b":"sti","c":"preg","d":"preg","e":"preg","f":"preg"},"relearn":"Any plan that includes a condom covers STIs too; methods used alone (no condom) cover pregnancy only."},
  {"id":"mc-1357","cat":"the-full-picture","type":"sort","persona":"any","source":"risk basics","hook":"Sort: can lead to pregnancy/STI, or carries no such risk?","items":[{"id":"a","text":"Unprotected sex 'just once'"},{"id":"b","text":"Unprotected sex on a 'safe' day"},{"id":"c","text":"Choosing not to have sex"},{"id":"d","text":"A split condom, no backup"},{"id":"e","text":"A condom used right every time"},{"id":"f","text":"Unprotected sex the first time"}],"bins":[{"id":"risk","label":"Can lead to pregnancy/STI","valence":"uhoh"},{"id":"none","label":"No such risk","valence":"pos"}],"key":{"a":"risk","b":"risk","c":"none","d":"risk","e":"none","f":"risk"},"relearn":"Any unprotected sex can lead to pregnancy or an STI; delaying and correct condom use carry no such risk."},
  {"id":"mc-1358","cat":"the-full-picture","type":"sort","persona":"any","source":"method features","hook":"Sort: lasts for years, or used per-act / per-day?","items":[{"id":"a","text":"Implant"},{"id":"b","text":"Hormonal IUD"},{"id":"c","text":"Copper IUD"},{"id":"d","text":"Male condom"},{"id":"e","text":"The daily pill"},{"id":"f","text":"The emergency pill"}],"bins":[{"id":"long","label":"Lasts years","valence":"neutral"},{"id":"short","label":"Per-act or per-day","valence":"neutral"}],"key":{"a":"long","b":"long","c":"long","d":"short","e":"short","f":"short"},"relearn":"LARC (implant, IUDs) lasts for years; condoms, the daily pill and the emergency pill are used per-act or per-day."},
  {"id":"mc-1359","cat":"the-full-picture","type":"sort","persona":"Arjun","source":"dual protection (CDC)","hook":"Sort: covers STI risk for any partners, or pregnancy only?","items":[{"id":"a","text":"Condom"},{"id":"b","text":"Regular STI check-ups"},{"id":"c","text":"The pill"},{"id":"d","text":"An implant"},{"id":"e","text":"Condom every time"},{"id":"f","text":"A copper IUD"}],"bins":[{"id":"sti","label":"Helps with STI risk","valence":"pos"},{"id":"preg","label":"Pregnancy only","valence":"uhoh"}],"key":{"a":"sti","b":"sti","c":"preg","d":"preg","e":"sti","f":"preg"},"relearn":"STI protection comes from condoms and check-ups, whoever your partner is; pregnancy-only methods don't cover STIs."},
  {"id":"mc-1360","cat":"the-full-picture","type":"sort","persona":"any","source":"split-condom backup","hook":"Sort: a sensible step if a condom splits, or not a real fix?","items":[{"id":"a","text":"Consider emergency contraception soon"},{"id":"b","text":"Get the EC pill from a pharmacy"},{"id":"c","text":"Plan an STI check if needed"},{"id":"d","text":"Just hope and do nothing"},{"id":"e","text":"Wash and assume it's fine"},{"id":"f","text":"Wait a month to 'see'"}],"bins":[{"id":"do","label":"Sensible step","valence":"pos"},{"id":"no","label":"Not a real fix","valence":"neg"}],"key":{"a":"do","b":"do","c":"do","d":"no","e":"no","f":"no"},"relearn":"A split condom → consider EC soon (best within 5 days) and an STI check; hoping or washing is not a fix."},
  {"id":"mc-1361","cat":"the-full-picture","type":"sort","persona":"any","source":"methods vs myths","hook":"Sort: a real method that works, or a myth that doesn't?","items":[{"id":"a","text":"The implant"},{"id":"b","text":"The copper IUD"},{"id":"c","text":"Standing up after sex"},{"id":"d","text":"A lemon or salt 'trick'"},{"id":"e","text":"The condom"},{"id":"f","text":"Skipping the day on a 'calendar guess'"}],"bins":[{"id":"real","label":"Real method","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"real","b":"real","c":"myth","d":"myth","e":"real","f":"myth"},"relearn":"Implants, IUDs and condoms are real methods; 'standing up', 'home tricks' and 'calendar guesses' are myths."},
  {"id":"mc-1362","cat":"the-full-picture","type":"sort","persona":"any","source":"effectiveness (WHO)","hook":"Sort by typical-use effectiveness: over 99%, or lower than that?","items":[{"id":"a","text":"Implant"},{"id":"b","text":"Hormonal IUD"},{"id":"c","text":"Copper IUD"},{"id":"d","text":"The pill (typical use)"},{"id":"e","text":"Male condom (typical use)"},{"id":"f","text":"Withdrawal (typical use)"}],"bins":[{"id":"top","label":"Over 99%","valence":"pos"},{"id":"lower","label":"Lower in typical use","valence":"uhoh"}],"key":{"a":"top","b":"top","c":"top","d":"lower","e":"lower","f":"lower"},"relearn":"LARC is over 99% effective; the pill (~91%), condom (~87%) and withdrawal are lower in typical use."},
  {"id":"mc-1363","cat":"the-full-picture","type":"sort","persona":"any","source":"certain option","hook":"Sort: 100%-certain against pregnancy, or 'very effective but not 100%'?","items":[{"id":"a","text":"Choosing not to have sex"},{"id":"b","text":"The implant"},{"id":"c","text":"The pill, taken well"},{"id":"d","text":"A condom every time"},{"id":"e","text":"A copper IUD"},{"id":"f","text":"Waiting until you're ready"}],"bins":[{"id":"certain","label":"100% certain","valence":"pos"},{"id":"high","label":"Very effective, not 100%","valence":"neutral"}],"key":{"a":"certain","b":"high","c":"high","d":"high","e":"high","f":"certain"},"relearn":"Delaying / not having sex is the only 100%-certain option; LARC and others are very effective but not 100%."},
  {"id":"mc-1364","cat":"the-full-picture","type":"sort","persona":"any","source":"access (RKSK/AFHC)","hook":"Sort by where it comes from: a pharmacy, or a doctor/clinic?","items":[{"id":"a","text":"Male condoms"},{"id":"b","text":"The emergency pill"},{"id":"c","text":"An implant (fitted)"},{"id":"d","text":"An IUD (fitted)"},{"id":"e","text":"A prescription for the daily pill"},{"id":"f","text":"Over-the-counter condoms"}],"bins":[{"id":"pharm","label":"Pharmacy, over the counter","valence":"neutral"},{"id":"clinic","label":"Doctor / AFHC clinic","valence":"neutral"}],"key":{"a":"pharm","b":"pharm","c":"clinic","d":"clinic","e":"clinic","f":"pharm"},"relearn":"Condoms and the EC pill come from a pharmacy; fitted methods and prescriptions come from a doctor or AFHC clinic."},
  {"id":"mc-1365","cat":"the-full-picture","type":"sort","persona":"Vijay","source":"partner protection plan","hook":"Sort: part of a solid two-person protection plan, or not?","items":[{"id":"a","text":"Agreeing to use a condom together"},{"id":"b","text":"Both knowing where to get it"},{"id":"c","text":"Keeping a condom that isn't expired"},{"id":"d","text":"Assuming the other 'handled it'"},{"id":"e","text":"One partner deciding alone, silently"},{"id":"f","text":"Talking it over before, calmly"}],"bins":[{"id":"solid","label":"Solid plan","valence":"pos"},{"id":"weak","label":"Not a real plan","valence":"neg"}],"key":{"a":"solid","b":"solid","c":"solid","d":"weak","e":"weak","f":"solid"},"relearn":"A real plan is agreed together, informed and checked; assuming or deciding silently isn't a plan."},
  {"id":"mc-1366","cat":"the-full-picture","type":"match","persona":"any","source":"method features","hook":"Match each method to its standout feature.","pairs":[{"left":"IUD / implant","right":"Set-and-forget, lasts years"},{"left":"Condom","right":"Also blocks STIs"},{"left":"The daily pill","right":"Taken at the same time each day"},{"left":"Emergency pill","right":"Backup within 5 days of sex"},{"left":"Delaying sex","right":"The one 100%-certain option"}],"relearn":"Each method has a job: LARC lasts, condoms cover STIs, the pill is daily, EC is backup, delaying is certain."},
  {"id":"mc-1367","cat":"the-full-picture","type":"match","persona":"any","source":"method timing","hook":"Match each method to how often you have to deal with it.","pairs":[{"left":"Implant","right":"Once every few years"},{"left":"Injection","right":"Every few months"},{"left":"The pill","right":"Every single day"},{"left":"Condom","right":"Every time you have sex"},{"left":"Emergency pill","right":"Only after unprotected sex"}],"relearn":"Methods differ by upkeep: LARC is years, injections are months, the pill is daily, condoms are per-time, EC is backup-only."},
  {"id":"mc-1368","cat":"the-full-picture","type":"match","persona":"any","source":"key terms","hook":"Match each term to what it actually means.","pairs":[{"left":"Typical use","right":"Real life, including slips"},{"left":"Perfect use","right":"Every time, exactly right"},{"left":"Dual protection","right":"Pregnancy and STIs both covered"},{"left":"LARC","right":"Long-acting, nothing to remember"},{"left":"Reversible","right":"Fertility returns after stopping"}],"relearn":"These five terms are the vocabulary of the full picture. Knowing them is half of choosing well."},
  {"id":"mc-1369","cat":"the-full-picture","type":"match","persona":"any","source":"method matching","hook":"Match the situation to the method worth knowing about.","pairs":[{"left":"Want STI protection too","right":"Condom, alone or with another method"},{"left":"Want nothing to remember daily","right":"IUD or implant"},{"left":"Unprotected sex already happened","right":"Emergency pill, within 5 days"},{"left":"Want the most certain option","right":"Choosing not to have sex"},{"left":"Keep forgetting the daily pill","right":"Switch to a LARC method"}],"relearn":"Fit the method to the need: dual protection, set-and-forget, backup, certainty, or no daily action."},
  {"id":"mc-1370","cat":"the-full-picture","type":"match","persona":"Vijay","source":"access (RKSK/AFHC)","hook":"Match what you need to where you actually get it.","pairs":[{"left":"Condoms","right":"A pharmacy"},{"left":"The emergency pill","right":"A pharmacy, soon after"},{"left":"An implant fitted","right":"An AFHC (Ujala) clinic"},{"left":"A pill prescription","right":"A doctor"},{"left":"Confidential SRH counselling","right":"Adolescent-Friendly Health Clinic"}],"relearn":"Pharmacy for condoms/EC; doctor or AFHC (Ujala) clinic for fitted methods, prescriptions and confidential counselling."},
  {"id":"mc-1371","cat":"the-full-picture","type":"match","persona":"any","source":"emergency contraception (WHO)","hook":"Match each fact about the emergency pill to its plain meaning.","pairs":[{"left":"Best within 5 days","right":"Sooner works better"},{"left":"Mainly delays ovulation","right":"Stops an egg being released"},{"left":"Not an abortion","right":"Won't end an existing pregnancy"},{"left":"A backup, not routine","right":"Not a regular daily method"},{"left":"From a pharmacy","right":"No prescription needed"}],"relearn":"EC is a time-sensitive backup that prevents pregnancy. It is not an abortion and not a routine method."},
  {"id":"mc-1372","cat":"the-full-picture","type":"match","persona":"any","source":"methods vs myths","hook":"Match each myth to the fact that corrects it.","pairs":[{"left":"'The pill stops STIs'","right":"Only condoms protect against STIs"},{"left":"'Contraception causes infertility'","right":"It's reversible; fertility returns"},{"left":"'EC is an abortion'","right":"It prevents pregnancy, not ends one"},{"left":"'Condoms never work'","right":"Used right, they work well"},{"left":"'First time is always safe'","right":"Any unprotected sex carries risk"}],"relearn":"Each common myth has a clear fact behind it. The fact is what you act on, not the rumour."},
  {"id":"mc-1373","cat":"the-full-picture","type":"match","persona":"any","source":"who fits what","hook":"Match the everyday reason to the method that suits it.","pairs":[{"left":"Hate the idea of a daily routine","right":"Implant or IUD"},{"left":"Want STI cover with a new partner","right":"Condom"},{"left":"Already pregnant-risk after a slip","right":"Emergency pill"},{"left":"Not ready for sex at all","right":"Delaying, fully valid"},{"left":"Want extra pregnancy cover with condoms","right":"Add the pill or a LARC"}],"relearn":"There's no single 'right' method. The right one fits your life, your needs and your timeline."},
  {"id":"mc-1374","cat":"the-full-picture","type":"match","persona":"any","source":"dual protection (CDC)","hook":"Match each plan to what it does and doesn't cover.","pairs":[{"left":"Condom only","right":"Pregnancy + STIs, good every-time use needed"},{"left":"Pill only","right":"Pregnancy only, no STI cover"},{"left":"Condom + pill","right":"STIs covered, extra pregnancy cover"},{"left":"IUD only","right":"Strong pregnancy cover, no STI cover"},{"left":"Nothing","right":"No cover at all"}],"relearn":"Only plans that include a condom cover STIs; pairing a condom with another method adds pregnancy cover."},
  {"id":"mc-1375","cat":"the-full-picture","type":"match","persona":"Arjun","source":"ask a clinician","hook":"Match your question to who can answer it without judging.","pairs":[{"left":"'Which method suits me?'","right":"A doctor or AFHC clinician"},{"left":"'Is this kept private?'","right":"Yes, confidentiality is part of the service"},{"left":"'Where do I buy condoms?'","right":"Any pharmacy"},{"left":"'I had a slip last night'","right":"Pharmacy EC, within 5 days"},{"left":"'I'd rather wait'","right":"That's valid and respected"}],"relearn":"Asking a clinician is routine care. They inform and help in private, whoever you are, and explain any limits."},
  {"id":"mc-1376","cat":"the-full-picture","type":"match","persona":"any","source":"timing matters","hook":"Match each method to when you use it.","pairs":[{"left":"The daily pill","right":"Same time every day"},{"left":"Male condom","right":"Each time, before sex"},{"left":"Emergency pill","right":"After a slip, within 5 days"},{"left":"Implant","right":"Once, lasts a few years"},{"left":"Injectable","right":"A repeat every few months"}],"relearn":"Methods differ by timing: daily, per-act, after-the-fact, once-for-years, or every few months."},
  {"id":"mc-1377","cat":"the-full-picture","type":"match","persona":"any","source":"effectiveness drivers","hook":"Match each habit to what it does to real-life effectiveness.","pairs":[{"left":"Taking the pill on time daily","right":"Keeps it near its best"},{"left":"Forgetting pills often","right":"Drops it toward typical use"},{"left":"A fresh, in-date condom","right":"Works as intended"},{"left":"Reusing a condom","right":"Makes it unreliable"},{"left":"Choosing a LARC","right":"Removes the daily-slip risk"}],"relearn":"Effectiveness is mostly about use: consistent, correct, in-date use keeps a method near its best."},
  {"id":"mc-1378","cat":"the-full-picture","type":"match","persona":"any","source":"vocabulary check","hook":"Match each plain phrase to the method it describes.","pairs":[{"left":"'Lasts years, fit and forget'","right":"IUD or implant"},{"left":"'Take one every day'","right":"The pill"},{"left":"'Use one each time, blocks STIs'","right":"Condom"},{"left":"'A backup after a slip'","right":"Emergency pill"},{"left":"'The 100%-certain choice'","right":"Not having sex"}],"relearn":"Plain language maps cleanly onto methods. You don't need jargon to know the full picture."},
  {"id":"mc-1379","cat":"the-full-picture","type":"strike-rewrite","persona":"any","source":"dual protection","hook":"\"If you're on the pill, you don't need condoms for anything.\"","myth":{"un":"On the pill, you never need condoms.","re":"The pill prevents pregnancy only; a condom is still what protects against STIs.","why":"Each method does a different job."},"relearn":"The pill covers pregnancy; only condoms add STI protection. That's why people pair them."},
  {"id":"mc-1380","cat":"the-full-picture","type":"strike-rewrite","persona":"any","source":"emergency contraception (WHO)","hook":"\"The emergency pill only works the next morning, then it's useless.\"","myth":{"un":"EC only works the very next morning.","re":"It works best within 5 days of unprotected sex. Sooner is better, but it isn't only for the morning after.","why":"It mainly works by delaying ovulation."},"relearn":"EC has a 5-day window; act sooner for the best chance, but the morning after isn't the only moment."},
  {"id":"mc-1381","cat":"the-full-picture","type":"strike-rewrite","persona":"Vijay","source":"access (RKSK/AFHC)","hook":"\"You can't get contraception unless you're married.\"","myth":{"un":"Only married people can get contraception.","re":"Condoms and the EC pill are sold at any pharmacy, and AFHC (Ujala) clinics give confidential information to young people.","why":"Access isn't tied to marital status."},"relearn":"A pharmacy sells condoms/EC to anyone; AFHC clinics inform young people confidentially."},
  {"id":"mc-1382","cat":"the-full-picture","type":"strike-rewrite","persona":"any","source":"reversibility (WHO)","hook":"\"An IUD will leave you unable to have children later.\"","myth":{"un":"An IUD leaves you unable to have children later.","re":"The IUD is reversible. Once removed, fertility returns; it doesn't cause later infertility.","why":"It prevents pregnancy only while it's in place."},"relearn":"LARC like the IUD is reversible; fertility returns after it's removed."},
  {"id":"mc-1383","cat":"the-full-picture","type":"strike-rewrite","persona":"any","source":"risk basics","hook":"\"You can't get pregnant the very first time.\"","myth":{"un":"You can't get pregnant the first time.","re":"Any unprotected sex can lead to pregnancy or an STI, including the first time.","why":"The body doesn't keep count of 'firsts'."},"relearn":"There's no 'free pass' first time; it's the act, not the count, that carries risk."},
  {"id":"mc-1384","cat":"the-full-picture","type":"strike-rewrite","persona":"any","source":"methods vs myths","hook":"\"Pulling out in time is as good as a condom.\"","myth":{"un":"Pulling out is as good as a condom.","re":"Withdrawal is far less reliable and gives no STI protection; a condom does both jobs better.","why":"It depends on perfect timing and covers no STIs."},"relearn":"Withdrawal is unreliable and STI-blind; a condom is the more dependable, dual-protection choice."},
  {"id":"mc-1385","cat":"the-full-picture","type":"strike-rewrite","persona":"any","source":"methods vs myths","hook":"\"A safe day on the calendar means you never need protection.\"","myth":{"un":"A 'safe day' means you never need protection.","re":"Cycle timing is hard to predict, so a 'safe day' guess is unreliable; protection is what actually covers you.","why":"Ovulation timing shifts and can't be guessed exactly."},"relearn":"'Safe day' guessing is unreliable; a real method is what protects you."},
  {"id":"mc-1386","cat":"the-full-picture","type":"strike-rewrite","persona":"any","source":"effectiveness basics","hook":"\"Condoms fail so often there's no point using them.\"","myth":{"un":"Condoms fail so often there's no point.","re":"Used correctly every time they're highly effective, about 98 in 100, and they're the only STI protection.","why":"Most 'failure' is inconsistent or incorrect use."},"relearn":"Used right every time, condoms work well and uniquely guard against STIs."},
  {"id":"mc-1387","cat":"the-full-picture","type":"strike-rewrite","persona":"any","source":"larc facts","hook":"\"The implant has to be taken out and put back every month.\"","myth":{"un":"The implant is swapped every month.","re":"The implant is long-acting. Once fitted it lasts a few years with nothing to do daily.","why":"That's the whole point of LARC."},"relearn":"LARC like the implant lasts years; there's nothing monthly or daily to remember."},
  {"id":"mc-1388","cat":"the-full-picture","type":"strike-rewrite","persona":"any","source":"emergency contraception (WHO)","hook":"\"Taking the emergency pill is basically having an abortion.\"","myth":{"un":"The emergency pill is basically an abortion.","re":"EC prevents pregnancy, mainly by delaying ovulation; it cannot end an existing pregnancy.","why":"Prevention after sex is not termination."},"relearn":"EC prevents pregnancy and is not an abortion; the two are different things."},
  {"id":"mc-1389","cat":"the-full-picture","type":"strike-rewrite","persona":"any","source":"certain option","hook":"\"Choosing not to have sex isn't a real form of protection.\"","myth":{"un":"Not having sex isn't real protection.","re":"Delaying / not having sex is the only 100%-certain option against pregnancy and STIs, and it's fully valid.","why":"No exposure means no risk."},"relearn":"Delaying is the most certain option and an equal, respected choice, never a lesser one."},
  {"id":"mc-1390","cat":"the-full-picture","type":"strike-rewrite","persona":"any","source":"dual protection","hook":"\"Two condoms at once give you double the protection.\"","myth":{"un":"Two condoms give double protection.","re":"Doubling up causes friction and is more likely to tear; one condom used correctly is the protective choice.","why":"More isn't safer here. Correct single use is."},"relearn":"One condom, used right, protects best; doubling up backfires."},
  {"id":"mc-1391","cat":"the-full-picture","type":"strike-rewrite","persona":"Arjun","source":"inclusive facts","hook":"\"Protection talk is only for people who could get pregnant.\"","myth":{"un":"Protection only matters if pregnancy is possible.","re":"STI protection matters for any partners; condoms and check-ups are part of looking after each other's health.","why":"Health, not just pregnancy, is the point."},"relearn":"Protection is about health for everyone, not only about pregnancy."},
  {"id":"mc-1392","cat":"the-full-picture","type":"strike-rewrite","persona":"any","source":"info empowers","hook":"\"Knowing about contraception just pushes young people into sex.\"","myth":{"un":"Knowing about contraception pushes you into sex.","re":"Good information helps people make safer, more thoughtful choices, including choosing to wait.","why":"Knowledge informs a choice; it doesn't make it."},"relearn":"Information empowers a free choice, including delaying. It doesn't nudge anyone anywhere."},
  {"id":"mc-1393","cat":"the-full-picture","type":"strike-rewrite","persona":"any","source":"methods vs myths","hook":"\"You can flush out pregnancy risk by washing right after sex.\"","myth":{"un":"Washing after sex prevents pregnancy.","re":"Washing does nothing to prevent pregnancy; a real method or the EC pill is what works.","why":"It can't reach or stop what's already happened."},"relearn":"Washing isn't contraception; a real method beforehand or EC afterward is what protects you."},
  {"id":"mc-1394","cat":"the-full-picture","type":"strike-rewrite","persona":"Sneha","source":"reversibility (WHO)","hook":"\"Starting the pill young will mess up your fertility for good.\"","myth":{"un":"The pill young ruins your fertility.","re":"The pill is reversible; fertility returns after you stop, whatever age you started.","why":"It prevents pregnancy while taken, not after."},"relearn":"The pill is reversible at any age you start; stopping returns your fertility."},
  {"id":"mc-1395","cat":"the-full-picture","type":"reflect","persona":"Vijay","source":"autonomy","hook":"Lensy: now you've seen the whole method picture: no gaps, no rumour. How's that sit?","prompt":"What do you think?","options":["Clearer now","Good to know it all","I can decide for myself"],"affirm":"Having the complete picture is exactly what lets a choice be genuinely yours.","relearn":"Full, accurate information is what makes a choice truly your own."},
  {"id":"mc-1396","cat":"the-full-picture","type":"reflect","persona":"any","source":"autonomy","hook":"Lensy: knowing every method also means knowing waiting is a real, equal option. Notice that?","prompt":"What's true for you?","options":["Waiting counts too","No pressure either way","I like having options"],"affirm":"Every option here is equal, including waiting; the choice and the timing stay yours.","relearn":"Delaying is a full, equal option; the full picture never nudges you toward any choice."},
  {"id":"mc-1397","cat":"the-full-picture","type":"reflect","persona":"Sneha","source":"autonomy","hook":"Lensy: a method that fits your life beats one someone else picked for you. Agree?","prompt":"Which feels right?","options":["Fit it to my life","My call, my body","Depends on what I need"],"affirm":"There's no single 'right' method. The one that fits you is the right one for you.","relearn":"The best method is the one that fits your own life and needs. It's your call."},
  {"id":"mc-1398","cat":"the-full-picture","type":"reflect","persona":"any","source":"autonomy","hook":"Lensy: asking questions until you actually understand a method: that's maturity, not nosiness. Feel that?","prompt":"How do you see it?","options":["Asking is smart","I'd rather understand fully","No silly questions here"],"affirm":"Seeking accurate information and asking is exactly what maturity looks like.","relearn":"Asking until you understand is mature and your right, never something to feel shy about."},
  {"id":"mc-1399","cat":"the-full-picture","type":"reflect","persona":"Arjun","source":"autonomy","hook":"Lensy: the full picture is the same facts for everyone, whoever you are. How's that land?","prompt":"What do you think?","options":["Good, same facts for all","No special case here","Just want the real info"],"affirm":"Accurate health facts belong to everyone equally. Your questions are routine and welcome.","relearn":"The full picture is for everyone equally; the facts don't change with who you are."},
  {"id":"mc-1400","cat":"the-full-picture","type":"reflect","persona":"any","source":"autonomy","hook":"Lensy: trusting evidence over a confident-sounding rumour takes a bit of courage. Recognise that?","prompt":"Which is you?","options":["I'll check the facts","Rumour isn't proof","Ask a clinic, not a forward"],"affirm":"Choosing reliable facts over rumour is a real skill, and it keeps the choice truly informed.","relearn":"Facts from a clinic or reliable source beat any confident rumour."},
  {"id":"mc-1401","cat":"the-full-picture","type":"reflect","persona":"any","source":"autonomy","hook":"Lensy: knowing where to actually get a method is as useful as knowing the method itself. True for you?","prompt":"What's your take?","options":["Knowing where matters","Pharmacy and clinic, got it","Useful to know the route"],"affirm":"Knowing the method and knowing where to get it together turn information into a real choice.","relearn":"Knowing the access route, like pharmacy, doctor or AFHC clinic, is part of the full picture."},
  {"id":"mc-1402","cat":"the-full-picture","type":"spot","persona":"any","source":"myth-spotting","hook":"Spot the two lines that are myths, not facts.","scene":[{"id":"a","text":"\"You can't get pregnant the first time\"","trick":true},{"id":"b","text":"\"Condoms also protect against STIs\"","trick":false},{"id":"c","text":"\"A 'safe day' means no protection needed\"","trick":true},{"id":"d","text":"\"The pill is reversible\"","trick":false},{"id":"e","text":"\"LARC lasts for years\"","trick":false}],"why":"'First time' and 'safe day' are classic myths; the other three are true.","relearn":"Catch the myths; trust evidence over confident-sounding rumour."},
  {"id":"mc-1403","cat":"the-full-picture","type":"spot","persona":"any","source":"myth-spotting","hook":"Spot the two false claims about the emergency pill.","scene":[{"id":"a","text":"\"It's the same as an abortion\"","trick":true},{"id":"b","text":"\"It works best within 5 days\"","trick":false},{"id":"c","text":"\"It mainly delays ovulation\"","trick":false},{"id":"d","text":"\"It's a normal daily method\"","trick":true},{"id":"e","text":"\"You can get it at a pharmacy\"","trick":false}],"why":"EC is not an abortion and not a daily method; the other three lines are accurate.","relearn":"EC is a time-limited backup that prevents pregnancy, not abortion, not routine."},
  {"id":"mc-1404","cat":"the-full-picture","type":"spot","persona":"any","source":"myth-spotting","hook":"Spot the two myths a 'helpful' friend slips in.","scene":[{"id":"a","text":"\"Two condoms give double protection\"","trick":true},{"id":"b","text":"\"One condom, used right, works well\"","trick":false},{"id":"c","text":"\"Condoms cover STIs too\"","trick":false},{"id":"d","text":"\"Washing after sex prevents pregnancy\"","trick":true},{"id":"e","text":"\"In-date condoms work as intended\"","trick":false}],"why":"Doubling up and washing after are myths; the other three are sound advice.","relearn":"One condom used correctly is the protective choice; washing isn't contraception."},
  {"id":"mc-1405","cat":"the-full-picture","type":"spot","persona":"any","source":"myth-spotting","hook":"Spot the two false statements about effectiveness.","scene":[{"id":"a","text":"\"LARC is the most effective method\"","trick":false},{"id":"b","text":"\"Condoms never really work\"","trick":true},{"id":"c","text":"\"The pill prevents pregnancy only\"","trick":false},{"id":"d","text":"\"Pulling out is as safe as a condom\"","trick":true},{"id":"e","text":"\"Typical use depends on consistency\"","trick":false}],"why":"'Condoms never work' and 'pulling out is as safe' are false; the other three are accurate.","relearn":"Condoms work well used right; withdrawal is far less reliable and covers no STIs."},
  {"id":"mc-1406","cat":"the-full-picture","type":"spot","persona":"any","source":"myth-spotting","hook":"Spot the two myths about access and fertility.","scene":[{"id":"a","text":"\"You need to be married to buy condoms\"","trick":true},{"id":"b","text":"\"AFHC clinics keep your visit confidential\"","trick":false},{"id":"c","text":"\"Contraception makes you infertile later\"","trick":true},{"id":"d","text":"\"Pharmacies sell the emergency pill\"","trick":false},{"id":"e","text":"\"These methods are reversible\"","trick":false}],"why":"The marriage rule and the infertility claim are myths; the other three are true.","relearn":"Anyone can buy condoms; methods are reversible and AFHC care is confidential."},
  {"id":"mc-1407","cat":"the-full-picture","type":"spot","persona":"any","source":"myth-spotting","hook":"Spot the two pieces of fake 'pharmacy advice'.","scene":[{"id":"a","text":"\"A home lemon trick replaces a condom\"","trick":true},{"id":"b","text":"\"Condoms are sold over the counter\"","trick":false},{"id":"c","text":"\"Standing up after sex prevents pregnancy\"","trick":true},{"id":"d","text":"\"EC works best taken soon\"","trick":false},{"id":"e","text":"\"A doctor can prescribe the pill\"","trick":false}],"why":"The 'lemon trick' and 'standing up' are myths; the other three are real facts.","relearn":"Home 'tricks' aren't contraception; pharmacies and doctors are the real routes."},
  {"id":"mc-1408","cat":"the-full-picture","type":"spot","persona":"any","source":"myth-spotting","hook":"Spot the two lines that pressure or mislead, not inform.","scene":[{"id":"a","text":"\"Real adults don't bother with protection\"","trick":true},{"id":"b","text":"\"Delaying is a valid, certain choice\"","trick":false},{"id":"c","text":"\"Good information helps you choose well\"","trick":false},{"id":"d","text":"\"Asking a clinic means something's wrong with you\"","trick":true},{"id":"e","text":"\"Only condoms protect against STIs\"","trick":false}],"why":"Both 'real adults skip it' and 'asking means something's wrong' pressure or shame; the rest inform.","relearn":"Protecting yourself and asking questions are mature. Pressure lines like these are red flags."},
  {"id":"mc-1409","cat":"the-full-picture","type":"role-play","persona":"Vijay","source":"talk-it-through","hook":"You and a partner are working out a protection plan.","setup":"You want to agree on using condoms. What do you say?","yourLine":[{"text":"\"If we ever do this, I want us to use a condom. Are we agreed?\"","best":true},{"text":"\"I guess we'll just figure it out in the moment.\""}],"relearn":"Protection is something partners agree on together, clearly and ahead of time."},
  {"id":"mc-1410","cat":"the-full-picture","type":"role-play","persona":"Arjun","source":"ask a clinician","hook":"You're at an AFHC (Ujala) clinic and want clear method info.","setup":"You're a little nervous but want the facts. What do you ask?","yourLine":[{"text":"\"I'd like to understand which contraception options would suit me.\"","best":true},{"text":"\"Never mind, I'll just look it up online later.\""}],"relearn":"Asking a clinician is normal, even when awkward. They're there to inform, not judge."},
  {"id":"mc-1411","cat":"the-full-picture","type":"role-play","persona":"any","source":"split-condom backup","hook":"A condom split, and your partner says to leave it.","setup":"You want to act on the slip sensibly. What do you say?","yourLine":[{"text":"\"It split. Let's get the emergency pill from a pharmacy soon.\"","best":true},{"text":"\"Okay, let's just hope it's fine.\""}],"relearn":"A split condom is a real signal to consider emergency contraception soon."},
  {"id":"mc-1412","cat":"the-full-picture","type":"role-play","persona":"any","source":"dual protection","hook":"A partner says the pill alone is enough, no condom.","setup":"You want STI cover too. What do you say?","yourLine":[{"text":"\"The pill covers pregnancy, but I want a condom for STI protection too.\"","best":true},{"text":"\"Fine, if you're sure the pill handles everything.\""}],"relearn":"The pill prevents pregnancy only; a condom is what adds STI protection."},
  {"id":"mc-1413","cat":"the-full-picture","type":"role-play","persona":"any","source":"access (RKSK/AFHC)","hook":"A friend insists a 'home method' works fine.","setup":"You'd rather use a real, reliable route. What do you say?","yourLine":[{"text":"\"I'd rather get a real method from a pharmacy or clinic than trust a home trick.\"","best":true},{"text":"\"Maybe you're right, the home thing is probably okay.\""}],"relearn":"Real methods come from a pharmacy, doctor or clinic, not from home tricks or rumour."},
  {"id":"mc-1414","cat":"the-full-picture","type":"role-play","persona":"Sneha","source":"info empowers","hook":"Someone teases you for reading up on contraception.","setup":"You stand by wanting the facts. What do you say?","yourLine":[{"text":"\"Knowing my options is how I make a good choice. That's the point.\"","best":true},{"text":"\"You're right, maybe I'm overthinking it.\""}],"relearn":"Seeking accurate information is exactly what a thoughtful, mature choice looks like."},
  {"id":"mc-1415","cat":"the-full-picture","type":"role-play","persona":"any","source":"forgot-pill fit","hook":"You keep forgetting the daily pill and feel stuck.","setup":"You want a method that fits your life better. What do you say to a clinician?","yourLine":[{"text":"\"I keep forgetting the pill. Could a method I don't take daily suit me?\"","best":true},{"text":"\"I'll just keep trying to remember it somehow.\""}],"relearn":"Forgetting often is a signal to fit the method to your life, like a LARC with no daily action."},
  {"id":"mc-1416","cat":"the-full-picture","type":"role-play","persona":"any","source":"confidential care","hook":"You want to ask about contraception but worry it'll get back home.","setup":"You want to confirm privacy first. What do you say?","yourLine":[{"text":"\"Before we start, is what we discuss here kept confidential?\"","best":true},{"text":"\"Actually, never mind, I'll just leave it.\""}],"relearn":"It's your right to ask what stays private; they won't tell your family, and they'll explain the one legal limit."},
  {"id":"mc-1417","cat":"the-full-picture","type":"branch","persona":"any","source":"split-condom backup","hook":"A condom slipped last night. It's now late morning. What do you do?","options":[{"text":"Get the emergency pill from a pharmacy today","consequence":"Acted in time, sensible and timely.","best":true},{"text":"Wait a couple of weeks to 'see'","consequence":"Waiting misses the EC window, which works best within 5 days."},{"text":"Assume one slip can't matter","consequence":"Any unprotected sex can carry risk; one slip still counts."}],"debrief":"A split condom → consider EC soon, best within 5 days.","relearn":"After a slip, EC from a pharmacy is the timely, sensible step."},
  {"id":"mc-1418","cat":"the-full-picture","type":"branch","persona":"any","source":"forgot-pill fit","hook":"You forget the daily pill most weeks and it's stressing you. What now?","options":[{"text":"Ask a clinician about a no-daily method like a LARC","consequence":"Fitting the method to your life keeps you reliably covered.","best":true},{"text":"Keep forgetting and hope","consequence":"Missed pills lower its real-life effectiveness."},{"text":"Stop and use nothing","consequence":"That leaves you unprotected; easier options exist."}],"debrief":"Forgetting often is a signal to fit the method to your life.","relearn":"A LARC needs no daily action. It can suit a life where pills get missed."},
  {"id":"mc-1419","cat":"the-full-picture","type":"branch","persona":"any","source":"dual protection","hook":"You want both STI cover and strong pregnancy cover. What's the plan?","options":[{"text":"Use a condom plus another method, like the pill or a LARC","consequence":"Condom covers STIs; the second adds pregnancy cover.","best":true},{"text":"Use the pill alone, skip condoms","consequence":"That covers pregnancy only: no STI protection."},{"text":"Use neither and 'be careful'","consequence":"Being careful isn't a method; this leaves you exposed."}],"debrief":"Dual protection = a condom plus, optionally, another method.","relearn":"A condom covers STIs; a second method adds pregnancy cover."},
  {"id":"mc-1420","cat":"the-full-picture","type":"branch","persona":"Vijay","source":"access (RKSK/AFHC)","hook":"You want reliable contraception but don't know where to start. What now?","options":[{"text":"Get condoms at a pharmacy; ask an AFHC clinic about methods","consequence":"Real routes, accurate options, confidential help.","best":true},{"text":"Follow a 'home trick' forward","consequence":"Home tricks aren't contraception and won't protect you."},{"text":"Do nothing: too awkward","consequence":"Awkward is normal, but the info is your right."}],"debrief":"Pharmacy for condoms; doctor or AFHC clinic for methods.","relearn":"AFHC (Ujala) clinics give young people confidential method advice."},
  {"id":"mc-1421","cat":"the-full-picture","type":"branch","persona":"any","source":"info empowers","hook":"You're unsure which method suits you; a friend has strong opinions. What now?","options":[{"text":"Get facts from a doctor or AFHC clinic, then weigh your needs","consequence":"Reliable facts plus your values make it your choice.","best":true},{"text":"Copy whatever your friend uses","consequence":"What suits them may not suit you, or be freely chosen."},{"text":"Pick one at random","consequence":"Rushing skips what makes a method fit you."}],"debrief":"Gather facts, weigh your needs. The choice is yours.","relearn":"There's no single 'right' method; the right one fits your needs."},
  {"id":"mc-1422","cat":"the-full-picture","type":"branch","persona":"any","source":"certain option","hook":"You're unsure you're ready for sex but feel pressure to decide. What now?","options":[{"text":"Remember waiting is valid; take your time","consequence":"Delaying is respected and the most certain option.","best":true},{"text":"Go ahead to stop the pressure","consequence":"Pleasing others isn't choosing freely; re-decide."},{"text":"Feel something's wrong for waiting","consequence":"Nothing's wrong. Waiting is common and your right."}],"debrief":"Waiting is a full, equal option; no one should pressure you.","relearn":"Delaying is respected and the most certain choice; the timing is yours."},
  {"id":"mc-1423","cat":"the-full-picture","type":"branch","persona":"any","source":"emergency contraception (WHO)","hook":"A friend asks what the emergency pill actually does. What do you say?","options":[{"text":"It prevents pregnancy after a slip, best within 5 days, not an abortion","consequence":"Accurate: it prevents pregnancy by delaying ovulation.","best":true},{"text":"It ends a pregnancy already started","consequence":"A myth: EC can't end an existing pregnancy."},{"text":"It's a daily method like the pill","consequence":"EC is a backup, not a daily method."}],"debrief":"EC prevents pregnancy, best within 5 days, not an abortion.","relearn":"EC is a time-limited backup that prevents pregnancy."},
  {"id":"mc-1424","cat":"the-full-picture","type":"branch","persona":"any","source":"methods vs myths","hook":"A WhatsApp group swears a 'safe day' means no protection is needed. What now?","options":[{"text":"Treat it as unreliable; use a real method","consequence":"Cycle timing can't be guessed; a method protects you.","best":true},{"text":"Trust the 'safe day', skip protection","consequence":"Guesses are unreliable; unprotected sex carries risk."},{"text":"Forward it on as advice","consequence":"Passing on a myth spreads risk; check facts first."}],"debrief":"'Safe day' guessing is unreliable. Trust a method, not a forward.","relearn":"Cycle timing can't be guessed; a real method protects you."},
];

